/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080121-6","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"区民委員会","time":"午後１時０３分～午後４時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区民カードと住基カードの発行枚数と、大体どのような年齢構成の方がそれぞれ登録しているのかお伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"交付枚数ですが、区民カードが累計で５,２６６枚、住基カードが６,４０２枚となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"住基カードと区民カードを重複して取得している人がいるのかお伺いいたします。","respondent":"上川内戸籍住民課長","answer":"区民カード所持者のうち約１割弱の方が住基カードも重複して持っております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"住基ネットの本格稼働の前に発行された区民カードということですけれども、区民カードの新規登録の激減と住基カードの普及の増加の相関関係といいますか、それは特に連動するものなのかどうかお伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"先ほど数字の推移をお話ししましたが、区民カードが平成１５年度に４,０７２枚取得されたということは、高齢者の方たちが本人確認の書類として区民カードしかなかったということです。住基カードは全国的に金融機関にも通用するということです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"重複しているのは１割だけという話だったので、関係はそんなにないのではないかという感想です。今回区民カードが廃止されることによって、住基カードを持つのは抵抗がありますけれども、区民カードのように本人確認できる証明書が欲しいという方がいる可能性があると思うんですけれども、その辺のことはどのようにすればいいのかお伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"「品川区の場合、区民カードと住基カードがあります。区民カードは無料、住基カードは有料です。ただし、区民カードは品川区役所の中でしか通用しません。住基カードは全国どこでも通用します」と言うと、ほとんどの方が「住基カードにします」という現状があるという認識です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"今のご説明で、区民カードは無料で、写真も撮ってくださって中に組み込まれる。住基カードは１,０００円でしたか。先ほど来、ダブっている方が１割ということで、５,２６６枚のうち高齢者がどのぐらいかわかりませんけれども、区民カードで満足されている方が住基カードしか今後は得られないとなった場合の利便性についてはどうなのでしょうか。","respondent":"上川内戸籍住民課長","answer":"もしカードがない場合、区民カードも住基カードもまだ作っていないから証明書がないといった場合、ほかのもので代用していますので、証明書類がないからといって届出ができないということはありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問","question":"区民カードを利用されている方は高齢者が多い。家庭の主婦とか高齢者の方にとっては大事なのかなと思っていましたけれども、今のご説明からすると、不利益にはならないということでしょうか。区民カードがなくなったからといって住基カードに移行されるわけではなくて、希望された方ということですね。区民の皆さんにとって不利益はないと受けとめてよろしいでしょうか。","respondent":"上川内戸籍住民課長","answer":"そのとおりです。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"番、行政視察の報告書","agenda":"番、行政視察の報告書","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"オークションの件ですけれども、手数料はどのようになっているのでしょうか。","respondent":"武内税務課長","answer":"ただ、品物が落札されますと、例えば１万円ですと３％の手数料がヤフーオークションの会社に支払われるような形になりますので、その部分につきましては、売れた物件、つまり滞納者の負担ですので、区の持ち出しはないと考えていただいてよろしいかと思います。","voiceIndex":27,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"伝統の技と味のところですけれども、チラシの裏面に実演ということが書いてありますけれども、実演にあたっての準備とか材料に関して、区から補助が出ているのかどうか、その点だけお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"技のほうに関しましては、出店について委託の契約をしておりまして、委託料の中で賄っているのではないかと考えています。味のほうについては、特に私どものほうでは用意しておりませんので、当日販売する中で出店者のほうが工面しているのかと考えております。","voiceIndex":29,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"報告のところは口頭だけでは書き切れないので、ぜひ簡単なものでいいので資料をつけていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":6928,"voices":33}},{"id":"h20-20080121-7","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"厚生委員会","time":"午後１時０３分～午後２時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば、計画の設計図が全然できていない状況で今日出せないということなのでしょうか、そこが１点。それから、併設が中止ということであれば、０歳児から３歳児までの認可保育園が新たにプラスされるということで、区民の親御さんたちから大きな期待があったわけですけれども、これが一体どうなっていくのかということについても教えていただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"荏原西地区において０歳児から３歳児の枠が増えるということで、地域の中で期待されていたところが、今回中止になったですが、この地域については原小学校跡施設の部分、五反田地域にできる私立保育園等も考えますと。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、平塚幼稚園があるわけですから、それはどうなるのか、具体的にどうなっていくのか教えていただきたいと思います。それから、突然という思いをしているわけです。校庭面積というのは地域からもずっと前から出ていたと思うんですけれども、それがなぜ今なのか。これがどこで、いつ決まったことなのかという、基本的なところをもう１回教えていただきたいと思います。","respondent":"古川児童保健事業部長","answer":"私どもはこの基本設計というのは当然実施設計に高めていって、間もなく予算の編成の時期ですので、この予算の中で具体的に今後２カ年の建設経費を計上しながら、２年後には小中一貫校と幼保一体施設が荏原西地区に完成することを、当然私どもも考えてございましたし。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことでしたら、それはそれであるのかなと思うんですけれども、とにかく認可保育園に対しては地域の中で高い要望がありまして、今回保育園の入園申し込みの方が去年よりまた増えているということを窓口でお聞きしたんですけれども、そういう点では認可保育園の増設は区民から待ち望まれておりますので、ぜひ荏原西地区小中一貫校に併設というのはなくなったとしても、部長が言われたように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"その前に今のような校庭がどうだということを考えて基本設計に入らなければ、それ自体がむだになる。極端に言えば違った話になってきてしまう。皆さん方はなかなか直接区民にぶつかる機会がないけれども、我々は今日もこれからいろいろなところへ顔を出していったときに、何でですかという話になる。ですから、そういったことが、後でまちに誤った変な話が出てこないようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"堺委員","kind":"質問・要望","question":"日野学園、伊藤学園等については、それぞれあのような形で完成を見ましたので、できる限り私としては、区の描いておられる小中一貫校６校構想については、ぜひ成功させていただきたいという思いがありますので、今回このことにつきましては、今後のいい教訓として、これからの荏原東地区、品川小学校と城南中学校、八潮についてはそれほど問題はないかと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-005"},{"speaker":"本間委員","kind":"質問・要望","question":"見通しについての誤りにつきましては部長からお話しをお聞きしましたが、平成２２年度中に開設という部分の、平成２０年度から２年間の分をどうしていくのかということでございまして、これは問題がどうかなです。意見のようになってしまいましたけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"意見","question":"今の報告を聞いて非常に残念だなと思います。所管が違うのかもしれませんけれども、荏原西地区の学校のイメージをどのように描いていたのか。最初の計画のところでも、当然そういうことは検討されていたのではないかと思うんですけれども、スポーツなどの位置づけがどうだったのか、それに変更があったのかどうか、その辺のところの説明をお願いしたいと思います。","respondent":"古川児童保健事業部長","answer":"地下２階に体育館をおろす、あるいは給食調理室を地下に設けるとか、いろいろな工夫をして、先ほど来いろいろ各委員の皆様方からお叱りとこれからの課題についてご指摘をいただきましたが、そういう中で私ども基本設計については一定の見通しを立てていたわけですが、その後。","voiceIndex":13,"id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると今度の変更にあたっては、グラウンドそのものは広くなっていくのか、そこのところはどうなのか。もしかしたら、教育委員会からいろいろ計画が変更になって、もっと広げていきたいという中での今回の話なのか、その辺のところをもう少しお伺いしたいと思います。例えば、グラウンドが広くなったということであれば、どのくらいだったのがどのくらいなのか、その辺もお伺いしたいと思います。","respondent":"古川児童保健事業部長","answer":"地下１階に予定しておりました給食調理室を地上階の平屋のほうにといった、ちょっと具体的な全体像が見えないのですが、そういった中で当初の前提条件については当然クリアすることを今回最優先で計画変更し、実施設計の中では基本設計を若干変更せざるを得なかったということで。","voiceIndex":15,"id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"幼保一体施設をこの学校の中につくることは難しいということですけれども、今回は小中一貫校をつくる中で、３校を一つにしていくわけですから、逆にほかの学校施設を活用できるのではないかと思うんです。先ほど、いろいろそういうことも含めて検討したいということのようなので、ぜひそういう方向で検討していただきたいと思います。要望になりますけれども、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すべての人にやさしいまちづくり推進計画というのは、今の説明の中でも国のさまざまな法律とか、ガイドラインが出されていますけれども、そういう中でこういう計画をつくるようにという国からの方針というか、義務づけというか、そういうものが出されたところで、こういう計画が出されているということなのでしょうか。福祉のまちづくり計画策定のガイドラインも出ていますね。","respondent":"上山介護保険担当課長","answer":"特に、法において義務づけ等があるわけではないです。品川区の場合には、平成９年に既に今申し上げています推進計画を策定しておりますので、その後の社会状況の変化に応じて計画をこの時点で改定したです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"他の自治体の計画の状況というのがわかったら、一つ教えていただきたいと思います。そういうところでは、区民の声を反映させながら、継続的にどんどん改善をさせていくというご説明をいただきましたけれども、区民の声を反映させるしくみがどういうしくみになっているのかお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長、上山介護保険担当課長","answer":"今回、これについて２月にパブリックコメントを実施して、骨子案の全ページをホームページに掲載する予定ですので、こういった形でご意見を伺って、今後推進協議会を母体にして、今後ともさまざまな区民の声を聞いていく予定です。面的なまちづくりにつきましても、重点施設周辺におきます設置・整備につきましては、住民や高齢者、障害者等の参加を得ながら実施していきますので、この時点での意見の反映あるいは実効性を高めていくための工夫はできるかと思います。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一つ、パブリックコメントを２月１日から２０日まで行うことは評価するところですけれども、あわせてこういう問題というのは本当に待たれていたことですので、区民の方への説明会を持っていただいて、意見を聞く場をぜひ持っていただけたら、パブリックコメントでも、よりたくさんの実際に生かせるような声が聞けるのではないかと思いますので、ぜひ区民への説明会をやっていただきたいと思うんですが。","respondent":"上山介護保険担当課長","answer":"１点目、区民への説明会ですけれども、パブリックコメントがその趣旨に沿った形での対応かなと考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、パブリックコメントを終わって、これは骨子案ですので、改めて推進計画の本番ができると思うんですけれども、それができたところではぜひこの委員会にもご報告をしていただきたいと思いますので、障害福祉計画のときは骨子案だけが説明されて、本当にできたときにこの委員会に説明がなかったので、ぜひ計画ができ上がった段階で、委員会の中で説明をしていただきたいと思いますが。","respondent":"上山介護保険担当課長","answer":"先ほど、区民説明会ということでございましたので、説明という観点でご説明いたしましたけれども、今回の施策の体系で述べています、例えば意識づくりのところにつきましては、区民の方への広がりを非常に大事にする部分ですので。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、大幅な変更が出なくても、例えばパブリックコメントでこういう意見があったということもあわせて、ぜひ最終段階での説明をしていただきたいと思いますが、お答えいただけますか。","respondent":"上山介護保険担当課長","answer":"パブリックコメントの締め切りが２月２０日ですので、こちらの委員会のスケジュール等を考え合わせながら、意見等を含めたご報告をさせていただきたいと考えております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"今回のすべての人にやさしいまちづくりは、特に改定と書いてあるように高齢者や障害者にやさしいということですから、一番、対象になると申し上げていいのかどうかわかりませんが、それはいわゆるここで言う品川区の障害者７団体の方々かと思うんですけれども、こういう方々との懇談会を開催されるということですけれども、いつ頃、どういうふうにされる予定なんですか。","respondent":"高橋障害者福祉課長","answer":"推進計画改定委員会につきましては、障害者７団体懇談会の副会長であります団体から、改定の検討委員に出ていただいておりますので、随時その辺の連携に対しては進めさせていただいている状況です。","voiceIndex":33,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"そういう面からいきますと、先ほど申し上げましたように、代表の方が出てご意見を述べるというのも一つの考え方かもしれません、否定するものではありませんが、こういう場合については、できる限り多くのご意見と同時に、障害はみんな違うわけですから、そういう面からいきますと、そういう方々から直接ご意見を伺っていったほうが、よりいい形のものができ上がるのではないかという気がするので。","respondent":"上山介護保険担当課長","answer":"加えまして、障害者７団体との懇談会は、それぞれの障害者の団体の方々と別個に懇談会を設け、かつ２月に改めてご説明させていただきたいと考えているものです。","voiceIndex":35,"id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"重ねて申し上げて恐縮ですが、やはり直接関係者からご意見を伺うということは、非常に大事な要素かなと思いますので申し上げました。それから、日本語の表現の仕方と言っていいのでしょうか、特にこだわっているわけではないですけれども、例えば「（仮称）品川区すべての人にやさしいまちづくり」と、ここでは「すべての人」という表現になっています。","respondent":"上山介護保険担当課長","answer":"考えていく過程の中で、「あらゆる人に」とかいろいろ表現を模索していることは事実ですので、最終的にどういった表現がいいのかを含めまして検討してまいりたいと思います。","voiceIndex":37,"id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"誤解されるといけないので、変えなさいと言っているのではないのです。これはこれでいいだろうと思うんです。何か意味があるのかと思って、教えていただければという意味で申し上げただけですから、そんなに深い意味ではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"高橋委員","kind":"質問","question":"コンサルティング会社が入っていると思うんですが、特にこのコンサルティング会社は福祉関係に強いのかどうか、また、どれぐらいの費用で契約されているのかわかれば教えていただければと思います。","respondent":"上山介護保険担当課長","answer":"経費につきましては、７００万円です。プロポーザルの中で、この業者がバリアフリー新法への対応の仕方も含めまして、考え方がしっかりしているということと、それ相応の実績があるということで、今回この業者に決めたものです。","voiceIndex":40,"id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"この計画がいいものになるように期待したいと思います。もう一つ、鉄道の場合、私はいつも思っているんですけれども、ホームドアは新しい駅にはついているんですけれども、既存の駅につくるのが非常に遅いなという気がしているんですけれども、それは今回のユニバーサルデザインのところには位置づけられるのかどうか、そこのところを伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"下神明駅が残っていますけれども、これについては鉄道事業者に問い合わせいたしましたところ、現在検討中であるです。それから、２点目のホーム側のドアについては、今回のバリアフリー新法等では、そこまでは法で求めていないかと思います。","voiceIndex":42,"id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そこのところは住民の方の要望もありますが、法律との関係もありますので、やはりプッシュしていただきたいと思います。そういう意味では、メンバーの中に鉄道事業者もいるわけですから、そういう検討もぜひ俎上に乗せていただきたいと思うんですけれども、その辺の区側の認識をお伺いしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"これについてはまちづくり推進協議会に鉄道事業者が出ておりますので、現実問題、どういうような状況なのか、この問題については区のほうも具体的な把握をしてございませんので、関心を持って事業者に問題を投げかけていきたいと思ってあります。","voiceIndex":44,"id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ぜひ、お願いしたいと思います。それから、ノンステップバスのことが出ておりますが、バス停のいすや屋根がばらばらなんですね。そういうところも気をつけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"私自身、今、町会とか青少年の地区委員をやらせていただいて、現場はこのとおり、５４歳の山元は若手と言われるぐらいです。そういう意味で、まだまだ意識が高い方がいらっしゃるわけですので、ぜひ区として何か対策といいますか、手立てを考えていただければと。何かお考えがあれば、ぜひ教えていただければと思います。","respondent":"冨岡高齢事業課長","answer":"それも高齢事業課だけのものではなくて、他の地域活動とかさまざまなセクションと連携を取りながら、少しでも地域に向けて一緒にやっていただけることを、これから私どももしなければいけないことですが、誘われたらやってみたいという方も３割ぐらいいらっしゃるということで。","voiceIndex":51,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":30897,"voices":61}},{"id":"h20-20080121-8","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"建設委員会","time":"午後１時０３分～午後３時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の環状六号線整備に伴う池上線架道橋改良工事のための測量調査","agenda":"の環状六号線整備に伴う池上線架道橋改良工事のための測量調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この改良工事、恐らく長い期間かかるであろうと思いますけれども、総事業費は幾らぐらいなんですか。区とか都とか国とかのもの、補助金の関係を少し教えてください。","respondent":"阿部都市計画課長","answer":"この工事につきましては、今申し上げたとおり、これから設計をしていくという段階ですので、工事については、まだ決まっていないと聞いております。ただ補助金の関係はどうなのか、その辺はちょっと承知しておりません。申しわけございません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"それがどこら辺の高さというか、地中に来るのかを教えてほしいのと、今の費用の話なんですけど、これは第二建設事務所がどうしても中央環状品川線の中で、これは構わないんですけれども、ぜひ東急電鉄にも区が何かあるときは協力してというか、あまりに東急、多分金を払わないので、どこをやっても、東急は協力的じゃないから。","respondent":"阿部都市計画課長、家壽田下水道河川課長","answer":"ただ東急につきましては、私ども区としてもいろいろな場面で話をする必要がある機会がありますので、そういう機会には区の主張は十分にやっているわけですけれども、なかなか鉄道事業者との調整がうまく合わない部分があるです。恐らく今、委員がおっしゃったのは、埋設物にぶつかった推進管のことだと思いますが、推進工そのものはかなり浅いところを掘っておりますので、中央環状品川線はそれよりかなり下、深いところを掘っているということで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"よくわからないんだけど、例えば３８ｍ掘るのはそれで、その下はいいんだけれども、上に今、下水道管とか、右岸の排水施設も掘るわけでしょう。やっぱり管理をある程度、工事、気をつけてよと言ったほうがいいものなのか、そこら辺がわからないので、教えていただければありがたい。","respondent":"家壽田下水道河川課長","answer":"仮に影響が出る場合には、そのための対策工事を事前に必ず行うことにしておりますので、今回、その対策を恐らくやらないことになると思いますが、それはかなり深くて、地盤のいいところを掘っておりますので、地上には影響はほとんどないという結果で恐らく出るだろうと思います。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいんですが、調査の内容で、基本的にボーリング調査ということで、やっていくんでしょうが、いろいろボーリングだと、ボーリングになるんでしょうけど、そのほかに何か別の診断装置というんですか、診断と言ったらおかしいのかな。あくまでボーリング調査だけなんでしょうか。","respondent":"阿部都市計画課長","answer":"今回のは測量調査でございまして、要するに先ほども申し上げましたけれども、民地と接している部分がありますので、そういうことで境界等を含めた測量と聞いております。測量いたしまして、その後に設計に入っていくという形ですので、今回の測量はそういう中身です。","voiceIndex":12,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"今回、この測量調査ということでご報告いただいているのですが、測量調査の後、改良工事の日程と言ったらいいんですか、期間と、それから３ページ目のカラー刷りのほうでは、この工事区間のほうが、改良工事に伴って、この山手通りの拡幅工事を行うかどうか、その辺の工期を合わせているのであれば、それも一緒に教えてください。車線を減らしてやることになるのか、そういったことも教えてください。","respondent":"阿部都市計画課長","answer":"その関係で、山手通りの車線の変更をする必要が出てくるということで、この切廻しすりつけ区間というところに合わせて、車線を外に持っていきまして、すりつけていくです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"今のご説明の中で、このすりつけ区間という、工事期間中に車線を変えていって、工事がしやすくするようにという、その区間がここであるという理解でよろしいでしょうか。それから先ほど質問した中で、その工事期間中の交通規制はどのようになるかということを教えてください。","respondent":"阿部都市計画課長","answer":"交通の規制ですけれども、今申し上げましたとおり、ここの五反田の換気所がちょうど真ん中のところにできますので、その関係で車線の変更が出てくるですけれども、具体的にどういう形でやっていくか、そこまではまだはっきりはしておりませんので。","voiceIndex":16,"id":"exchange-006"}]},{"id":"topic-02","title":"の大井町線急行運行に向けての深夜試運転の実施","agenda":"の大井町線急行運行に向けての深夜試運転の実施","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"実施時期、最初の２回は１２日、１９日で、既に２回実施されたのでしょうか。もし実施されていて、沿線の住民の方から何か反応ですとか声があったのであれば、教えていただければと思います。","respondent":"阿部都市計画課長","answer":"１月１２日、１９日は実施しております。これにつきましては、東急に確認しましたけれども、沿線の方々から意見というものはなかったと聞いています。","voiceIndex":22,"id":"exchange-007"}]},{"id":"topic-03","title":"の品川駅・田町駅周辺まちづくりガイドライン","agenda":"の品川駅・田町駅周辺まちづくりガイドライン","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"全体の地域は６３０ｈａですか、膨大な広さのお話になるかと思うんですけれども、まず環境モデル都市づくりについて、パブリックコメントでも３０件あったそうですけれども、環境モデル地区のパブリックコメントに関するこの３０件の中身がもう少しわかれば、教えていただきたいなというのが１点と、これは品川区から何人ぐらいというのはわかるんですかね。もしわかったら、教えてください。","respondent":"青木都市開発課長","answer":"こうしたことに関しまして、お褒めいただいているご指摘についてはそれとして踏まえるとともに、最後にご紹介しましたような技術的なところでどうしたほうがいいというご意見につきましては、ガイドラインそのものには細かいところまでは記載しないけれども。","voiceIndex":28,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"パブリックコメントのことなんですけれども、６３０ｈａという膨大な地域の意見を伺うわりには、あまりにも期間が１５日間と短過ぎる。品川区はそれをどんなふうに見ているのか。このパブリックコメントをまずなぜ行ったのか、改めてそのパブリックコメントの理由、目的をご説明いただきたいのと、この状況についてどう思われているのか、不十分な点はないのか、お伺いしたいと思います。","respondent":"青木都市開発課長","answer":"品川区におきましては、特に先ほどご紹介しましたおにぎり型の部分、品川浦、あるいは旧東海道といったところが中心の話題になるわけですけれども、こちらにつきましては、景観のまちづくり等でまだ個別の取り組みをそれぞれ私どもの所管でやっておりますから。","voiceIndex":30,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"近所の方に聞いても、最近の五反田は、この辺はほとんど港区ですけれども、高層マンションを見て、こういう姿でいいのかなという話、去年、今年、年末年始そういう話もよく伺いました。ＣＯ２の話、風の道の話、結局は環境で配慮したときの何の環境なのか。どこに注目しているのか。この環境に配慮したという、この環境とは一体何を指しているのか、教えてください。","respondent":"青木都市開発課長","answer":"主にちょっと前の環境問題といいますと、人が公害から守られる、要するに排気ガスから喘息にならないように防がなければならないといったものが主に環境という言葉でとらえられていたんですけれども、現在。","voiceIndex":32,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"しかし、これだけ大規模になってくると、やはり根本原因が何なのか、ＣＯ２の削減目標を掲げながら増えているのが実態ですから、よく見直すべき点があると思いますので、議論すべきだと思っています。最後は意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-011"},{"speaker":"三上委員","kind":"意見","question":"今のやりとりを聞いている中で、このものについてというのは、品川区の地域ではほとんどないよね。港区では相当そういったことについて、話し合いはされていると思うんだけれども、品川区でこういう議論というのはどこまで反映されると考えていますか。","respondent":"青木都市開発課長","answer":"ですけれども、やはりサウスゲートの形成という形で、品川駅が港区にありながらも品川を名乗って、日本全国で見たときの品川区の玄関口であるということに関して言えば八ツ山踏切の解消でありそういった京浜急行の踏切の問題。","voiceIndex":35,"id":"exchange-012"},{"speaker":"三上委員","kind":"意見","question":"それはわかるんです。品川駅の開発が始まって、考えてみると２０年ぐらいずっとやってきていますよね。その間、品川区はずうっといろいろなことで地域として、それは位置づけは明確にしながら、品川区としての意見、それからどう取り組むかということはやってきていると思う。それは当然のことである。行政としてはそういかないかもわからない。それが普通ではないかと思うんです。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"平成１６年のときに品川区も基本計画策定委員会に出ているんですけれども、これ、品川区はだれが出られたのかというのを教えていただきたいのと、パブリックコメントなんだけれども、案の修正には至らなかった、文言の変更だけは間違いというのはしたと。東京都もこういうことを言いました。そういう話というのが何かもっと表に出てきてほしいなと思うんだけれども、その辺の感覚を教えてください。","respondent":"青木都市開発課長","answer":"品川区でどういったポジションの者が関与してきたかという、１点目のご質問ですけれども、この検討会等につきましては、まちづくり事業部の次長を委員に当てて、その下部での幹事会などという個別の課題に対するものは、都市開発課長を当ててきてまいっております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"せっかくその協議会に入っていて。どこか手をかけたときは、用地買収を含めて始めますよとか、今おっしゃったように権利関係がたくさんあるから、用地買収だって必要になってくるわけじゃないですか。本当、前進なんだけど、せっかくここに入ったんだから、そういう何かきっかけづくりみたいなものをぜひこれからも話す機会があるんでしょうから、それは要望だけにしますけど、ぜひお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"それはプラスの波及効果も考えられますが、一方で吸い取られる、あるいは品川というまち自体が北にシフトすることで、南側の品川が薄くなるというようなこともあるかもしれませんし、それはちょっとすぐには私にはわからないんですけれども、少なくともそういった、すぐ隣接する部分で、大きなまちができるということと、品川区のこれからのあり方を分析していく。","respondent":"青木都市開発課長","answer":"１点目のこのガイドラインを策定したことによってお金が引っ張ってこれるかということですけれども、ガイドラインそのものは冒頭ご説明したとおり、まず計画論を行政、自治体でつくります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"」というふうに書いてあるんですけれども、ここで実際の計画はないにしても、こういうところを品川区としては、具体化するようなことがイメージされて、こういうところに含まれているのか、その辺の区としての姿勢みたいな、まちづくりのイメージみたいなものはどういうふうに考えているんでしょうか。","respondent":"青木都市開発課長","answer":"ここでの特に観光拠点としての景観形成というのは、景観につきましては、当委員会所管の都市計画課長の所管で進めております景観行政を踏まえておりますし、あと観光という面でいいますと、ちょっと所管が違う委員会になるかと思うんですけれども。","voiceIndex":43,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"その前のホテルなどの宿泊機能というのは、品川駅でもいっぱいありますけれども、そういうのを品川のこちらのほうにもイメージ、あるいは結構具体的に自分たちの思いがここに言葉としてなっているというように聞こえたんですけれども、そういうふうになると、そういうこともいろいろな工場跡地とか、品川区にも結構あるわけですけれども、そういうことが既にイメージされているということですか。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"そうした中で、この品川駅・田町駅地域周辺のガイドラインについて議論をしていく中で、どうしても宿泊機能、お客様を迎え入れる機能というのが港区側のほうに意識が寄ってしまっていますので、品川区といたしましては。品川浦のところにホテルを建てるとか、そんな計画は現在区が持っているわけではありません。","voiceIndex":45,"id":"exchange-018"}]},{"id":"topic-04","title":"の平成１９年度マンション管理セミナー（第２回）の開催","agenda":"の平成１９年度マンション管理セミナー（第２回）の開催","exchanges":[{"speaker":"井上委員","kind":"提案","question":"今回の場合は大規模修繕のことがテーマなんですが、以前にテーマの設定の仕方について、参加している方たちからも意見を求めてほしいというようなことを提案しましたけれども、その中で今、ちょっとこれとは離れて申しわけないんですけれども、これはこれでいいんですけれども、テーマ設定について。","respondent":"齋藤住宅課長","answer":"それともう１つまだ予算の段階ではっきりしてないんですけど、私どもの区民住宅にも高層マンションがございまして、ファミーユ西五反田の東館の高層階の１８階の倉庫を災害対策の備蓄倉庫のようにして、まず民間よりも先に区がやってみようということで取り組み。","voiceIndex":52,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"じゃ、主に今までのマンション管理というのは、建て替えのケアだとか、住民合意をどうとるかとか、そっちのハードのところで、それはそれとして必要なことだと思いますけれども、今求められているのは、高層マンションが孤立化して、個別のところで、ソフトのほうがすごく重要だと思っているし、住んでいる人、管理をしている住民の方たちからもそういうセミナーの要望の声があるので、ぜひ防災の視点でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"４年か５年、もうちょっと前、やっと建て替えが終わったマンションの方にどんなご苦労があったんですかと聞いたところ、１０年間ずうっと話し合ってきたと。そういう方に対しての意識形成というのは大規模改修への話し合いというんですか、そういう点では現在や今後、何か工夫されている点があるのかどうか、ちょっとお伺いさせていただきたい。","respondent":"齋藤住宅課長","answer":"それで高齢の方からは、マンションの管理組合で話がまとまらない。休日、夜間に相談にのってほしいという要望を受けたもので、対応しようと今、区で考えているところです。","voiceIndex":55,"id":"exchange-021"}]},{"id":"topic-05","title":"の区民住宅長期滞納者（和解条項不履行）に対する強制執行","agenda":"の区民住宅長期滞納者（和解条項不履行）に対する強制執行","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今の説明の中で、経過があったんですけど、そもそもこの区民住宅の入居対象で、一定の所得を確認しますよね。すみません、僕はその辺はちょっとちゃんと理解していないんですけれども、その状況と今の状況と、どうしてここまでの、そごというのも違うんだけど、そこをちょっと教えていただけますか。","respondent":"齋藤住宅課長","answer":"これがやりとりだと聞いております。いろいろお話をさせてもらっていますが、なかなかうまくいかないということで、私どもの努力不足もありましたが、感情的になって、ちょっとうまく話ができないことがあります。","voiceIndex":61,"id":"exchange-022"}]},{"id":"topic-06","title":"の「品川区ワンルーム形式等集合建築物に関する指導要綱」の制定","agenda":"の「品川区ワンルーム形式等集合建築物に関する指導要綱」の制定","exchanges":[{"speaker":"井上委員","kind":"提案","question":"このワンルーム形式等集合建築物という、２００３年に発行されたものと新しいものがあるんですけれども、そこのところで、実は適用範囲というところで、２００３年にできたところでは、同じように居室がある階数が３階以上、かつその戸数が１５戸以上のワンルーム形式と集合建築物とするというふうに、今と同じような文言が入っていたのに、新しくできたものには、そこが外れてしまっているんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つはファミリー住宅の確保を義務づけるということですけれども、なぜ義務づけにしたのか。そこの理由をもう一度伺いたいのと、この戸数を例えば１５戸から１９戸だったら１つ、２０戸から２９戸だったら２つとした理由は何か、あわせてご説明いただきたいと思います。もう１つはファミリータイプの４０m2以上というのはどういう理由なのか、お考えを教えていただきたい。","respondent":"齋藤住宅課長","answer":"戸数はなぜこの戸数かといわれると、なかなか説明しがたいんですが、必ず１５戸以上ファミリータイプにさせるのがうちの区の独自のアイデアでございまして、それ以外は各区のバランスをとりながら、売りにくくはないんだけれども。","voiceIndex":68,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"２つ目は、ワンルームがあるとつくりにくい。今回は第１段だというお話で、今後どういうふうにやっていくのかはあれですけれども、もっとファミリー住宅の確保が、これはこれで必要なことだと思いますけれども、私はもっと増やすときではないかと思うんですけれども、今回第１段だということなので、今後の現状の問題意識だけ教えていただけますか。","respondent":"齋藤住宅課長","answer":"ワンルームを建てさせないことが善というのもなかなか言いがたいということもございまして、ワンルームマンションは条例で規定している自治体もあるんですが、これは自治事務ではなくて、例えば空缶のポイ捨てであれば、区が罰金をとって規制できるんですが。","voiceIndex":70,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"この商店街にできるワンルームマンションの１階部分を周辺の商店街に合わせて店舗として義務づける、そういうのというのは今回、これを見る限り入っていないんですけども、その辺のお考えがどうなのかを教えていただきたいと。私はこの要綱ではなくて、区の条例に格上げすることも検討するべきじゃないかなと思うんですけれども、そこについてはどのようなお考えなんでしょうか。","respondent":"齋藤住宅課長","answer":"ワンルームの１階部分を店舗にすることにつきましては、今後の検討課題だと考えています。そのようなニーズがあればでしょうけれども、今のところそこまでの話は聞いておりません。","voiceIndex":72,"id":"exchange-026"},{"speaker":"井上委員","kind":"意見","question":"指導要綱の新しい中ではワンルームマンションの規定が床面積２９m2未満の住戸ということになっていますけれども、これが適用の対象というのを、ここがなぜ２９m2じゃなくて、３０m2なのかということと、今も出ましたけれども、義務づける規定で、ファミリータイプを義務づけるというのは計画の中で見えてくるので、そこは違反をする人はないでしょうということで、設計時にも明らかになるんですが。","respondent":"齋藤住宅課長","answer":"３０m2未満となっていた。前は２９m2未満。１m2上がっています。多分、それは３０m2未満と矛盾している言い方。","voiceIndex":74,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"だから、これが何で２９m2になって、３０m2と、ここをしたんですかと。","respondent":"齋藤住宅課長","answer":"この問題につきましては、区といたしましてもなかなか対応しづらいんですけれども、先ほどちょっと申し上げました、地域活動課のほうでも、ワンルームマンションが急増して、地域全体の不安というものがありますので。","voiceIndex":76,"id":"exchange-028"},{"speaker":"阿部委員","kind":"意見","question":"それから既存のワンルームマンションというのは、直接にはこの規制はかかってこないと思うんですけれども、やはり今言いました、その後できるソフトの部分、あるいはバリアフリーなんかの手すりをつけるといったようなことは、これまた既存のワンルームマンションの所有者に対して、何らかの働きかけをするお考えかどうかというのを説明してください。","respondent":"齋藤住宅課長","answer":"あるいはそういったものをまず初めとして誘導しないかというのは、また別な切り口として考えています。ただ、１棟売りして建ったものに対しての指導はなかなか難しゅうございまして、ご理解のほうをお願いいたします。","voiceIndex":78,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問","question":"なかなか建てられないというと、それが８位、９位になってくるのかどうか知らないけれども、だけれども、その部分の土地の部分と、土地の評価、それから２３区の中の全体の品川区という評価と、地域と連携するというのはまた分けて話をしないと、難しい話だと思うんだけど、そこら辺のところをどうとらえて、この１位、２位になったことをとらえて。","respondent":"齋藤住宅課長、岩田まちづくり事業部長","answer":"ただ、うちの区が最もワンルームマンションの規制が緩いというのもまた事実でありますので、またワンルームマンションをめぐる建築紛争について、いろいろこの２年間ずっとやってきましたけれども、住民の皆さんのご不安。前にもちょっとお答えしたことがあるんですけれども、いわゆる単身者が品川区に外部から来ていただくことは決して悪いことではないわけですね。","voiceIndex":80,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点だけちょっと教えていただきたい。第一種低層住居専用地域を頭出しさせた。これ、現実には、この平成１４年から含めてでいいんだけれども、この中の割合でも構いません。戸数の中で、そんなにないと思っていたんだけれども、もし、わかっているなら、戸数でもいいです、棟数でもいいんだけれども、何か理由があったから飛び出させたんだろうから、そこを教えてください。","respondent":"齋藤住宅課長","answer":"第一種低層住居の区内のエリアでの割合は５.７％ぐらい、エリア的にはある。そうすると、この数年で４件ほどあります。荏原地域で多いということですね。","voiceIndex":83,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ただ、今、４件もあったというので、ちょっと意外だったんだけど、ぜひそこら辺は、もしこれは要綱なので、いつでも変えられるので、一種のところだけはもしそういう、またあれがあるなら、もっとやったって、これはファミリータイプで、どうせ開発するなら同じになるような気がするので、ここら辺はちょっと検討していただければなと。これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"それで管理人は置きませんよと。どんな状況かということを見たときに、やはり品川区のほうが若干緩いのかなというところに対して、せっかく他区でそういう実績があるなら、それをやはりいいところどりじゃないんですけど、緩くなればやはりどうしても上下あれば下のほうに流れてくるわけですから、それだったらある程度それに近い均衡がとれるような施策が僕は必要じゃないかと思うんです。","respondent":"齋藤住宅課長","answer":"この下町の地域と、品川区、目黒区、世田谷区とか、大田区といったところでは、ワンルームに対して実需が違いますので、なかなか比較が難しい。これはまた事実です。","voiceIndex":86,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"先ほどちょっとほかの委員からもありましたが、実際、あくまで指導要綱ということですよね。今恐らく業者は遵守はしてくれるんだろうとは思うんですが、強い強制力というのはもちろんないわけですが、恐らく守ってくれるだろう、遵守してくれるだろうということで、今、住宅課長のほうからお話があったんですが、それはかなり大丈夫だと思っていいんでしょうかね。","respondent":"齋藤住宅課長","answer":"業者を呼んでヒアリングをしたのはそういうところもあります。９割ぐらいの業者は多分間違いないと思います。","voiceIndex":88,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"しようがないかと思うんですが、できるだけ指導していただきたいということと、あと、先ほどほかの委員からありましたが、私も重ねて言わせていただきますが、あくまで転売ということも今あると思うんですね。完全な投資ということで、これもかなり出てきていると思いますので、その辺の後も何とか追えるように、施行された後は従ってもらうように何とか指導を強化していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"なぜ説明会なのかというと、実際全部とは言わないですけど、乱暴な業者はとにかく住民説明会を３回我慢すればいいんだと。説明会の規定というのはもう少し明確にするべき必要があるんじゃないのかなと思うんですけれども、同じことですけれども、お考えを教えてください。","respondent":"齋藤住宅課長","answer":"説明会についての規定に変更はございません。説明会だけは２３区の中では私どもがリードしておりまして、２Ｈの範囲で説明すればいいという規定が多い中で、説明会を開きなさいというのは品川区。","voiceIndex":91,"id":"exchange-036"},{"speaker":"中塚委員","kind":"意見","question":"範囲の話は今、ご説明があったんだけれども、実際、僕、業者と話していて、３回我慢すればいいんだと、ぽろっと言って、それですごくみんな反感を買って。会の話はあれですけど、やっぱり近隣住民から申し出があった際は、しっかり対応するという文言や指導は必要ではないのかなと思うんですけども。","respondent":"齋藤住宅課長","answer":"住民の方がよくおっしゃるのはそのことでございまして、もめている以上は建築確認をおろさないでほしいとか、着工させないように指導しなさいということをおっしゃるんですが、なかなかそこまで言い切ることが難しい。","voiceIndex":93,"id":"exchange-037"}]},{"id":"topic-07","title":"耐震化促進計画","agenda":"耐震化促進計画","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"３３ページの支援についてなんですけれども、１点目、所得税の特別控除の条件が、これは平成２０年の１２月３１日となっておりますけれども、その１年間だけのものなのかということと、あと、固定資産税の減額措置というのは、区単独なのか、全体的にほかの区なんかも同じような条件なのかということで、傾向を教えていただきたい。","respondent":"片田建築課長","answer":"基本的には、これは国のほうの考え方ですから、今後また来年度の国の予算についても、それとの絡みの中で、どのような内容が盛り込まれているかということが区のほうとしても重視していきたいと思いますけれども、基本的には東京都、あと全国を含めて。","voiceIndex":103,"id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"２７年までに耐震の９０％を実現していこうという中で、ここについて所得税とか区独自で考え方を示していくということは、国としてそうということなのか。それ以降のことについては、どのようなことを考えられているのか、その辺の検討とかはないんでしょうか。","respondent":"片田建築課長","answer":"区としてどうのという検討ではございませんで、国としての考え方として、これをどう連動させていくかということだと、私も認識しています。","voiceIndex":105,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"一点お考えを伺いたいのと、このチラシはこれで第一弾としてはいいんでしょうけれども、何年、区が耐震促進計画を進めて、そういう防災に対する、簡単には書いてあるんですけれども、これは第一弾として、こういう壁とかつくるといえ、あなたの家も大事だけど、また地域の災害の減災をするためにも、家を補強する必要があるんだと、こういう視点が啓発として大事になってくるのかなと思っているんですが。","respondent":"片田建築課長","answer":"今回は全戸を前提に、町会回覧をやる予定ですけれども、そういういろいろな工夫をしながら、地域のほうにもご説明にお伺いするといったようなこっちからの視点を考えてきてありますので、そういう内容についても、あわせて進めていきたいということで考えてあります。","voiceIndex":107,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"直接この話じゃないですけど、例えば今、耐震偽装の話から、建築確認審査がなかなかおりにくくて、何カ月も待っているという話もあるけれども、できるだけ一定の幅を持ったといいますか、大体当時の設計図も昔の家で、持っていない人もいたり、中古で買った場合は、当時の図面だって実際に目視をして、設計図面を書き直してからやるんでしょうけれども、進めるに当たって。","respondent":"片田建築課長","answer":"例えば学校の耐震補強等で、他区の他の事例なんかでは、逆にグレースコートといいますか、筋交いみたいなものが大々的にということもありましたけれども、その中で安全にするということは。","voiceIndex":109,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺は幅をきかせて運用の中でよく工夫していただきたいということです。そっちを前面に出していかないと、じゃ、あなたは事情があるからこっちですねというふうに簡単にしちゃうと、それじゃやっぱりだめなんじゃないかなと思っていて、その考え方をお聞きしたいんです。","respondent":"片田建築課長","answer":"それと耐震シェルターに関する考え方ですけれども、基本的にはこれは委員が言うまでもなく、建物の安全、９０％というのはシェルターも含めて９０％ではなくて、本体の建物をそこで震災に遭われても、またそこで生活再建ができるということを基本として考えてありますから。","voiceIndex":111,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"これはどれを指したのか。当然、毎日の生活費では、この耐震シェルターの負担と言われても、生活がぎりぎりなものですから、生活保護世帯の方々というのは、この耐震シェルターの関係ではどういうふうに運用を考えているのか、現状を教えていただけますか。","respondent":"片田建築課長","answer":"つまり、どういうことかというと、避難できるかどうかということ、それに対して、そこの介助者はなかなかそういう方々の場合に難しいところがありますので、というところで、すぐ避難できる場所が身近にあることが望ましいだろうという考え方に基づくものです。","voiceIndex":113,"id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、どうせやるなら、区で行くぜというところの意欲を見せたところはどこなのかというのを横引きとかじゃなくて、これは完全に区で考えて、区で対象者を考えましたと。お金も区で出します。補助金は見込んでいませんというぐらいの、区でこの９０％にするためにどうしたのですかというのがどこかにあるなら、それを教えてほしい。これが生活サイクルで、必ず大体変わるはずでしょう。","respondent":"片田建築課長","answer":"１点目、全体のほうのご質問ですけれども、特にシェルター、実は委員のご質問の中でございましたけれども、確かに東京都のほうについても、そういう命を守るという切り口の中で。","voiceIndex":115,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほどお話ししたように、昭和５６年以前は、基本的には木造軸組み工法がほとんどなわけですよ。その間の部分をあまり診断だ、改修工事だとやっていると、違った方向へ行くような気がしてならないので、それはぜひ生活サイクル、建物の部分の老朽化も含めて必ずあるはずなので、ぜひそこはとらえて、独自に政策を打っていただければなと、これはお願いをしておくのと、また違ったところで質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":50568,"voices":122}},{"id":"h20-20080121-9","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"文教委員会","time":"午後１時０２分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"荏原西地区小中一貫校に関する設計変更","agenda":"荏原西地区小中一貫校に関する設計変更","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"理由が述べられたんですけれども、地盤が相当軟弱だったということのようなんですけれども、私、前の資料を用意してこなかったので、改めて確認したいんですけれども、もともと平塚小学校に幼稚園がありましたよね。いわゆる、幼稚園部分がなくなって、小学校と中学校の学校施設だけで建設していくと説明を受けたんですけれども、改めてそこを確認したい。","respondent":"市川庶務課長","answer":"今、委員のほうからお尋ねがあった３点のうち、１点目と３点目が関連があろうかと思うんですが、今回の設計変更によりまして、小中一貫校の単独施設の建設ということで、現在、平塚小学校と併設されている平塚幼稚園については、新しい施設には入ってまいりません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"大体はわかりましたけれども、学校についても、幼保一体化施設についても、一定程度長期にわたって安全に使用しなくてはいけないものですし、また、災害が起こったときは避難所にもなる施設ですから、軟弱な地盤で、非常にそういう心配のあるものをつくるということは絶対にやっちゃいけないことですから、そういう地盤であるということについては、設計変更もやむを得ないと。","respondent":"市川庶務課長","answer":"１,０００m2のボリューム感ということですが、先ほど、小山小学校の現場で見ていただいた教室の基準でいきますと、教室は大体８０m2ぐらいあります。それと前の廊下部分を合わせると、１教室１００m2程度、それの１０教室分です。やはり、かなりのスペースになってしまう。","voiceIndex":9,"id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"設計の変更はわかりました。それから、設計変更ということになりますと、もちろん設計会社に、また新たに設計の見直しということになって、費用がまたかかってくるということで、工事費すべてにおいて、トータルすると経費がかかってくるんですが、その辺はどう考えているのかということを教えてください。","respondent":"市川庶務課長","answer":"従来、幼保一体施設を予定しておりました２階建ての棟になるわけですけれども、そこを、今回の変更で、従来２階建てで考えていたものを１階建てに直すといったことですので、設計の全体像としては、そう大きく変わるものではございませんので、そこの点で。","voiceIndex":12,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"こういうことがあったということは、ある意味、この６校構想の中で設計ができている段階もありますけれども、やはりこういう調査を事前にして、なるべくロスをなくすという形にしていただきたいなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"ハード的なものは、今までの質問で出ましたので、ソフト的なところを質問したいんですが、今まで、平塚幼稚園は小学校と併設になっておりますので、幼小という形での連携をいろいろされていたと思うんです。それは、一体施設のほうがやりやすいということもありますが、今後、それにどういう影響が出てくるのかなと。一貫校という形での考え方がどうなっていくのかということをお聞きしたいんです。","respondent":"市川庶務課長","answer":"１点目の、残る平塚幼稚園は、幼稚園単独施設か、あるいは幼保複合施設として残るのかということについては、先ほど、少し触れましたが、今、私どもでは、幼稚園単独施設として残るということで説明を聞いております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"西本委員","kind":"意見","question":"幼稚園だけを存続させるということは、ちょっと今の品川区の流れの中での位置づけとしてどうなんだろうなというところがありますので、今はわからなくても、これから児童保健事業部等々との関係になってくると思うんですが、その辺をどういうふうに検討されるのか、全く検討しないというわけではないと思うんですが、これからのスケジュールを含めて、考え方をお願いします。","respondent":"市川庶務課長","answer":"教育委員会といたしましては、この間、幼稚園とのハード的な関係で申し上げますと、小学校ないし小中一貫校の建設に当たって、幼保一体施設との複合施設化ということが可能であるのか、不可能なのか、できないのか、これについては、その計画ごとに検討をしてまいります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"それをぜひ、いろいろ検討をしていただきたいと思っています。これはほんとうに、非常に残念で仕方ないと思います。路線変わらずといっても、具体的なところでは、やはり大きな変更が出てきているようですから、それも含めて展開をしていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"大沢副委員長","kind":"意見","question":"幼稚園が平塚小学校の跡地に残るということなんですけれども、これは、今、委員会で報告を受けましたけれども、今後において、いつ、どういう時期に、どなたたちに対してご説明というか、町場に対してどういう時期に、タイミングといいますか。近隣のお母さん方も、頭の中でそれを予定している方もあるので、そこのところは、どのタイミングになるのか。","respondent":"市川庶務課長","answer":"特に幼稚園と小学校の保護者、それから、先ほど、委員、ご質問にございました、今後、幼稚園に入園を予定している方々、いわゆる地域と言っていいのかもしれないんですけれども、これについて十分に説明を行えるように、幼稚園、学校、それから地域の関係者の方と至急相談の上。","voiceIndex":20,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"地盤が非常に弱かったというのは、いつごろの時点でわかったんですか。","respondent":"市川庶務課長","answer":"昨年の秋の時点で、一定のボーリング調査の結果が出てまいりました。その後、これまで進めてきた設計作業の延長線で考えられるかどうか、そういうことを昨年末まで検討したという経緯があります。","voiceIndex":22,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"秋というと、９月から１１月、１２月ぐらいまで一定程度の期間があるんですけれども、１１月には議会があって、当然、文教委員会も開かれたんですけれども、そこには発表するまでにきちんとした結果が導き出せてなくて発表できなかったということなんでしょうか。","respondent":"市川庶務課長","answer":"方針を確定するのには、幾つか検討して、詰めるべきことがあります。一定の方針を出した上で、なおかつまだほかに選択の余地がないか、そういうことを検討した上で最終的に方針を決定した。こういったことで、この時期での報告となったということでご理解いただければと思います。","voiceIndex":24,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"ここに一体化施設ができるということで、区としても報告というか、発表していた。しかし、先ほども質問が出たように、幼稚園部分を平塚小学校に残すということだけでほんとうにいいのかどうか、変わる代替案をきちんと早急に整理して、それに取り組むように進めていただきたいということを、改めて申し上げておきたいと思うんです。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"金野委員","kind":"確認","question":"すみません、確認だけ。先ほど、地盤が軟弱ということで、地下の工事を圧縮するということでしたが、前に配られた設計図を改めて見ると、給食室部分というんでしょうか、いわゆる体育館、アリーナは残すということなので、その部分ということなんでしょうか。","respondent":"市川庶務課長","answer":"最終的な決定ではないということを前置きして、説明しますけれども、以前、お示しした資料の中で、地下１階の部分、調理室、視聴覚室、それから、剣道場と表記してある部分、いわば本体の屋内体育館の脇にくっついている、ちょっと雑な表現ですみませんが。","voiceIndex":27,"id":"exchange-012"},{"speaker":"金野委員","kind":"質問","question":"そうすると、その部分をそぎ落とすということで、剣道場とか、こういうのは学校についているところは少ないので、こういうのはなくしちゃうんですか。それとも、それもちゃんと設計図の中に端のほうに生かせるようになってくるのでしょうか。","respondent":"市川庶務課長","answer":"大体、見込みが立って、先ほど申し上げました施設のローリングがうまくできそうだというめどを立てているという状況です。","voiceIndex":29,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"今回は、たまたま地盤の関係で上に出すと、今、説明がありましたけれども、そういうふうに働く姿を見せる、そして食べ物をつくる作業の状況を子どもたちに見せるという教育的な側面から、やっぱり地下ではなくて、できるだけ地上部分で、子どもが見えるような設計を考えていただきたいなということを、出たついでと言っちゃ失礼ですけれども、関連で、そのことも意見としてお伝えしておきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"鈴ケ森小学校の休校措置","agenda":"鈴ケ森小学校の休校措置","exchanges":[{"speaker":"金野委員","kind":"質問","question":"そうなると、電話もあるということだったんですが、メールは、いわゆる届きました、見ましたというやりとりはなくて、一方的に流すだけなんでしょうか、そのやりとりについて。要するに連絡がとれた人からと書かれているので、メールだと、その連絡が行ったかどうかというのは、どうなるのかなということです。","respondent":"古里学務課長","answer":"先ほど、電話でもと言いましたが、メールは着信確認ができるかどうか、そういう機能があるかどうかわかりませんけれども、学校からの説明によれば、メールと電話で連絡をとってですので、それは保護者と直接確認ができた者から下校させていくです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"金野委員","kind":"質問","question":"発生したその日の朝、７５名が欠席をして、それでこういう経過ということで、この症状ではなかった子どもたちの父兄への連絡方法として、今、ご説明を受けた限り、メール配信でされたものと、電話でされたものと伺ったんですが、今回のは集団欠席のことで、ほかにまた、例えば災害時とか、保護者に伝えるときは、やはりメール配信と電話でされているんだと思うんですが、この先。","respondent":"古里学務課長","answer":"先ほど、申し上げましたけれども、今回の場合は、基本的には、学校で保護者に確認をしてから下校させております。それから、今、全体の学校名、数は把握してございませんけれども、実は、教育委員会がきちんと設置をしたメール配信システムというのはないんです。","voiceIndex":41,"id":"exchange-016"},{"speaker":"金野委員","kind":"質問","question":"今、お考えをお聞きしましたので、最新の機能を使っての配信も、それも使いこなすと便利なものもあるかと思いますけれども、できれば直接言葉で伝えていく昔ながらの連絡網というのがやっぱり一番安全なのかなと思います。それも含めて、緊急時の対応というんでしょうか、ぜひ、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいと思います。１１日の朝、欠席が７５名ということで、前日までは、風邪で多少休まれた子どももいたんでしょうけれども、一気に７５名近い人数が休んだということで、緊急性があるという判断なのか。それから、７５名は特定のクラスに集中していたのか、全体にばらけていたのかというところは、いかがだったんでしょうか。","respondent":"古里学務課長","answer":"緊急性で、午後から休校、翌週２日休校としたことですけれども、これについて、感染性の大腸炎のおそれがあるということでございまして、間に１３、１４日というお休みがありましたけれども、その２日間で、全員の子どもたちの健康回復が可能かどうかというところで考えた場合に。","voiceIndex":44,"id":"exchange-018"},{"speaker":"西本委員","kind":"確認","question":"非常に感染力が強いということで、これは確認ですが、給食等が感染源でないということが、今の時点では言えるという理解でよろしいんでしょうか。","respondent":"古里学務課長","answer":"ただ、報告を差し上げましたとおり、調理済みの保存食、それから、介在している職員からはノロウイルス、細菌等も検出しておりませんので、現在の段階での口頭の報告によれば、給食を介して、いわゆる食中毒としての感染ではないのではないかという報告を受けてあります。","voiceIndex":46,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私もちょっとそこのところを伺いたかったんですけれども、学校が提供している給食から発症している状況はかなり低くなってきているというところは何よりだったなと思うんです。失礼しました、成人式で３連休だったんですね。１５、１６日が休校だったと、それならわかりました。何で１日あけて、１５、１６日なのかなと、ちょっとあれだったので、そこを伺いたかったんです。質問はいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"石田（慎）委員","kind":"質問","question":"ちょっと聞きたいんですけれども、全体で１０８名程度の児童が、何らかの嘔吐等で欠席をしたと思うんですが、そのうち、１８日現在で、４７名程度が検便検査を実施したということなんですが、２１日現在はきょうですので、まだわからないのかもしれないんですが、１０８名全員に対して検査をするんでしょうか。その２点を、お聞かせください。","respondent":"古里学務課長","answer":"ただ、この対応について、３学期末までにどのようにして取り返すかということは、今、至急学校が検討しているところでございまして、保護者のほうにも、この２日間の休校については、学期末までにきちんと取り戻しをしますということは報告をしております。","voiceIndex":49,"id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、検便検査というのは、欠席者だけでなくて、学校全体での検査を促したというか、希望される方のみ実施をしたということでよろしいんでしょうか。","respondent":"古里学務課長","answer":"そのようです。先ほど、申し上げた、メールでの送信ですけれども、そのようなこともしますということで、ＰＴＡのメールを借りて緊急の連絡の中に、そのようなことに触れて通知をしたと、学校から聞いてあります。","voiceIndex":51,"id":"exchange-022"},{"speaker":"大沢副委員長","kind":"質問","question":"１１日は給食を中止して、市販のパンと牛乳の代替給食ということなんですが、食中毒ではないということが、１１日にわかったわけですけれども、先ほど来、お話に出ているように、ノロウイルスは非常に感染力が強いということ、また、１５日に全校を次亜塩素酸ナトリウムで消毒したというような対策を考えると、１１日の給食を中止をしたことはいいんですが、牛乳と市販のパンによる代替給食は。","respondent":"古里学務課長","answer":"当日につきましては、当然、児童、保護者等も給食があるものとして登校しておりますので、何らかの形での給食の実施はせざるを得ないということで、牛乳の安全性と市販のパンの安全性をきちんと確認をした上で、これを配付する教員、それから児童は。","voiceIndex":53,"id":"exchange-023"},{"speaker":"市川委員","kind":"確認","question":"すみません、ちょっと確認だけさせてください。その日、保護者に連絡をして、連絡がとれた人ととれなかった人というのは、どの程度の割合だったのかということ。それから、今、非常に感染力が強いウイルスだということと、冬場では発症率も高まるという説明があったんですけれども、今、鈴ケ森小学校のことを受けて、他校で何か特別な対応とかをしていることがありましたら、教えてください。","respondent":"古里学務課長","answer":"吐いた後は非常に元気に遊び回っているというようなことですので、この辺が非常に難しいところですけれども、とにかく、嘔吐・下痢等の症状があった場合は、必ず医師の診断を仰ぐようにということと、先ほど言ったように、完治後も、２日間は出席停止という扱いをして。","voiceIndex":55,"id":"exchange-024"}]},{"id":"topic-03","title":"特別支援学級等整備計画","agenda":"特別支援学級等整備計画","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺は、どういう場合に介助員をつけられるのか。介助がついている状況がどの程度あるのかということを、ちょっと教えていただきたいというのが、とりあえず一つあります。特別支援教育を進めていくための体制みたいなものを、改めて、巡回相談だとか、校内委員会だとか、そういうことも含めて、ちょっと整理できるように教えていただければと思います。","respondent":"河野指導課長","answer":"障害がある子どもの登校に関して介助員がついているのかと聞こえたんですが、それでよろしいでしょうか。","voiceIndex":62,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"自分の子どもについていた介助員がほかの学年の子どもについていたんだけれども、その辺は、親としては外された理由がわからなかったという声も聞いたんですけれども、その辺、さっきの質問との関連で、どういうふうに見たらいいのかということ、それをちょっと教えていただきたい。","respondent":"河野指導課長","answer":"子どものための学習、自立の邪魔というか、弊害になってしまいますので、この程度はできるだろう、あるいはやらせなければいけないだろうという子どもについては、そういう事情を当該の保護者にも説明しつつ、介助員の配置の日数を段階的に減らしていくという措置を。","voiceIndex":66,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういう個別のところではきちんと理解なり、了解なりをいただける対応が、学校側にも必要なのかなと思いながら伺ったので、ぜひその辺もちょっと受けとめていただければと思います。通級というのは、さっきもおっしゃったように、情緒障害だとか、あるいは、言葉の教育だとか、そういう意味ではちょっと理解はしたんですけれども、そこと固定級との違いが何なのかというのをちょっと教えてください。","respondent":"河野指導課長","answer":"通常の義務教育学校に設置されている、いわゆる固定級、昔の特殊学級というような名称で呼んでおりましたが、公立の学校に設置されている特別支援学級は、軽度の知的障害を持つ子どもが対象になります。","voiceIndex":69,"id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"特に固定級ですが、設置の考え方を確認したいんです。ブロックに分れているんですが、そのブロックに小学校、中学校ということで固定級を設置していくという形で、一貫校のどちらかにある場合には、そこに集約していくと。そうすると、ブロックの中の、地区の中の開校している固定級は閉鎖になって、一貫校に移管していくという形の考え方でよろしいんですか。そこのところを。","respondent":"河野指導課長","answer":"そのかわり、中学校のほうで日野学園の特別支援学級を希望される方は、中学校から日野学園のほうの特別支援学級に入級してくださいという形でやっております。冒頭に申し上げたように、すべての施設一体型の小中一貫校に特別支援学級を設置するという考え方ではございません。","voiceIndex":72,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"わかりました。そうすると、一貫校の小学部に固定級があって、中学校になければ、そこは増設する。それでたくさんつくられてしまうので、地域のバランスを見て整備していきますと。子どもたちはそこに通っているわけですから、その年からあっちですよとかいう形になってしまうと思うんですね。そこのタイミングというのは、それぞれの施設の場合に考えた形で、これに落とされているのか、どうなんでしょうか。","respondent":"河野指導課長","answer":"将来的に、第四日野小学校が改築されるか、されないか今後の計画の推移を見守っていく必要もあるかと思いますが、せっかく十分なスペースが確保できて、なおかつその中に特別支援学級も十分に組み込めるだけのスペースがあるということであれば。","voiceIndex":74,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"バランスはいいんですけれども、その子どもたちがＡ小学校だったのに、来年はＢ小学校に行きなさいとか、結局、それが教育委員会の都合の話であって、子どもたちからすると、やっぱりその学校を選んで、その学校にいるわけですから、そこで卒業したいというようなことは当然考えるわけですよね。そこを配慮した切り替えというのを考えていただけるんでしょうかということです。","respondent":"河野指導課長","answer":"ただ、浜川中学校に関して言えば、そういう構想がありますよということで、来年の４月に入級を予定される子どもを対象に、そういう話はしています。ということはどういうことかといいますと、現在、７年生で在籍している子どもは、平成２２年３月をもって卒業されます。","voiceIndex":76,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"浜川中学校のほうに集中しているという現状があります。先ほどの閉級に関してのところは、浜川中学校のような形で考慮をされているのかということと、それから、そのブロックの中で、こういう特徴があるでもいいですけれども、なるべくそちらのほうに促すわけではないんですが、もうちょっと広く知っていただきたいなと思いますが、いかがでしょうか。","respondent":"河野指導課長","answer":"昨年度の場合は、ちょうど１年前の今ごろ、まさに伊藤中学校の特別支援学級にするか、浜川中学校の特別支援学級にするかという、学校を選択する際に、これは大変残念なことですが、伊藤中学校のほうは４月からできるということは決まっていたんですけれども。","voiceIndex":78,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"私もちょっと、今の話は伺っていて、それはそれとして理解はするんですけれども、浜川中学校が、平成２２年度から閉級になりますよね。固定級がずっと平成２１年度まであって、平成２２年度から固定から通級開級というのは、さっき説明された情緒障害だとか、発達障害だとか、そういう部分で、中身的に質が変わるということなんですか。","respondent":"河野指導課長","answer":"私どもは、個々の子どもたちのそういう利害関係を全く考えてないわけではありません。","voiceIndex":80,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"それはそれとして理解はできるところなので、理解しているところなんですけれども、何となくちょっと、八潮の特別な地域という、あの周辺の環境自体があるわけですから、別に八潮をなくしちゃったら、八潮に住んでいる子どもがほかの地域に通わざるを得ないという状況が出てくるので、それは同様の心配になってくるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4624#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":31583,"voices":90}},{"id":"h20-20080121-5","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"総務委員会","time":"午後１時０２分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"今のパブリックコメントのところでお聞きしたいんですけれども、１１４件の意見が寄せられたということですけれども、品川区の今後の２０年間の基本的な構想をつくり上げていく上で行政の意思の決定過程をまず示してというところで、１１４件のご意見というのは本当に品川区の基本構想の論議としては、私なんかは非常に少ないんじゃないかなという思いがあるんですけれども、この１１４件の意見。","respondent":"福島長期計画担当課長","answer":"１１４件ですけれども、この数が多いか少ないか、確かに難しい問題で、多いとも少ないとも言いにくいところもあります。ただ、策定委員会で出たご意見の中では、特に委員長が１１４はかなり多いだろうと。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"このパブリックコメントに当たって、ホームページへの掲載ですとか広報紙、募集チラシとか出されておりますけれども、考え方はいろいろあるとは思いますけれども、本来こういう最も重要な部分での意思決定をしていくわけですから、せっかくパブリックコメントをやるのであれば、区民に直接行政が説明をしていくという体制が、私はまず必要なのではないのかなと思っているんですけれども。","respondent":"福島長期計画担当課長","answer":"ホームページをごらんになっている方もかなり増えてきていますので、そういったことのほうがいいのではないかということで、今回につきましては直接の説明は行いませんでした。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほどアンケートなんかも通じていろいろな区民のたくさんの意見をいただいているという話でしたけれども、実質的には、今回の基本構想についても直接的には１１４件という意見だと思うんですけれど、今後のあり方として、やはり直接説明をし、意見を聴取していくという形をぜひ私はつくっていただきたいと思います。もう１つ、直接的に文章のほうでお聞きしたいんですけれども、個別の話になりますけれども。","respondent":"福島長期計画担当課長","answer":"議決後、この基本構想に基づきまして長期基本計画を策定してまいりますので、その策定に当たりましてはこの基本構想を直接区民の方にお示しし、ご説明し、それに基づいてどのような施策をつくっていったらいいのか。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"具体的にどうのこうのじゃないと言っているんだけれど、ここではその下のほうでかなり具体的に「商店街と連携したマイバッグ運動」とか記載されていますよね。もう１つだけ。これって決まったものなんですか。こういう大きな施策について、例えば半年とか１年間は長過ぎるかどうかわからないですけれど、もっと長い期間は、先ほどの説明もあわせてパブリックコメントを行うという考え方はないんでしょうか。","respondent":"福島長期計画担当課長","answer":"確かにこの基本構想は基本的なものですので、長くというのもあるかもしれませんけれども、かといって長ければ本当に集まるのかどうか、なかなか難しいことはあるかと思いますので、要綱に定められたとおり行うのが妥当ではないかと考えています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"もしかしたら普通のいい方ですと多分「健全な家庭」と、健全というと体とか心の健康も多少は含まれていると思うんですけれど、こちらのほうはどのような考え方で「健康」とされたか１つお伺いしたいところです。その１点をお伺いします。","respondent":"福島長期計画担当課長","answer":"ほかの意見の中でもこの中で健康あるいは医療についてあまり触れられていないのではないかというご意見もいただいておりましたので、ここであえて、確かに「健全」というのもあるかと思いますけれども「健康」と、これは単に家庭だけにかかわらず３０代前半の方々が今後健康に。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"今回につきましても結構な件数が出ているんですけれども、どのような形でホームページに掲載されるのか。今、見開きのような形になっていますけれど、耐震のほうは意見と回答という形だったんですけれども、こういう形で出るようにするのかその点をお伺いしたいのと、あと、いつごろに掲載をされる予定なのかなということも。","respondent":"福島長期計画担当課長","answer":"パブリックコメントの結果の公表ですけれども、現在考えていますのは、これをこのままといいますか、少し修整は加えますけれども見開きで読めるようにということで、いただいた意見とその要約、さらに対応という形で全文が見えるようにしたいと考えています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"１点だけ。すみません、今お伺いすればよかったんですけれども。１１４件来たわけですけれども、このご意見を寄せられた方には、例えばホームページだけで見てくださいというのか、それとも広報紙の封筒で送られた方については何か別の方法でお知らせするのか。それだけちょっと。","respondent":"福島長期計画担当課長","answer":"もちろん全文を載せるわけにはいきませんから、こういうことがありました、結果についてはこうですというようなご報告につきましても、広報しながわを通じて行いたいと考えています。したがいまして個別に回答をお送りするというようなことは考えておりません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけ。今の話の続きなんですけれども、このコメントを寄せていただいた区民の皆さんというのは非常に思いがおありですよね。２０年に１回という改定の時期でこれだけ集まってきた。しかも２０年に１回だということになれば、もう少し丁寧な対応の検討をしていただけないでしょうかということなんですが、いかがでしょうか。","respondent":"福島長期計画担当課長","answer":"まさに２０年に１度のことですし、寄せられた意見の方々の重みというのも感じております。したがいまして、どのような形で満足度がより得られるのかどうか、少し検討させていただきたいと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"意見","question":"決して個々の人に文書で送れということは考えていません。だけれどホームページに載せるだけでいいというところで終わるのでなくもう少し、何というか必要性が、可能性があると思われますので、それはぜひ検討してください。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"原委員","kind":"意見","question":"伊藤委員から話がありましたけれど、もうちょっと深く。別紙３のところで肯定的、否定的ということで２１件と出ているんですけれど、関心があるからこそいろいろな意見をちょうだいするんですけれども、その辺のところ否定的な意見の中で幾つか、ちょっとお教えいただけますか。","respondent":"福島長期計画担当課長","answer":"先ほども少しご報告させていただきましたけれど、「区への責任を果たした協働というのは妥当でない」ですとか、「区の責任をどういうふうに考えているのか」みたいな意見をいただいたり、「まちの話と実際のあり方がごちゃごちゃになってわかりにくい」というご意見ですとか。","voiceIndex":23,"id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"２０年ということで、品川区民憲章の次に位置してこようかと思うので、ちょうど基本計画の１０年との間ですよね。そうするとやはり、もう１回言いますけれど、否定的といっても関心があるからいろいろな意見をちょうだいするという抜本的なところが大きいものですから、否定的なこの２１件がどんどん少なくなるような形のアピールの仕方をしていただきたいんですけれど、そこのところをもう１回。","respondent":"福島長期計画担当課長","answer":"確かに貴重な、否定的ではありますが大変貴重なご意見です。全文をこういう形でお示しすることにつきまして、今後長期計画を策定していく際にも検討していきたいと考えています。今回の結果については検討していきたいと考えています。","voiceIndex":25,"id":"exchange-011"},{"speaker":"土井委員","kind":"提案","question":"先ほど来の続きなんですが、パブリックコメントに応募していただいた方にすべて回答というスタイルで個別の回答をすることはやはり避けていいんじゃないかと思うんですよ。これからもこの種の形のものに区としていろいろと皆さんにご意見を伺うことも多々ありますから、「ぜひまたお聞かせください。こういう形でやっていただいたほうが一般的でかえっていいんじゃないかと。ちょっと勝手な提案ですけれど。","respondent":"福島長期計画担当課長","answer":"先ほどご回答しましたように、確かにそういった方々は大切だと思いますので、何らかの方法、今この段階でこういう形で回答しますというのは答えられないんですけれども、何かいい方法を検討してみたいと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと１つだけ今の説明の中で。なかなか理解しがたい……。１１月のときの都区のあり方検討委員会の報告が４４４項目ですか、都から出されているという話がありましたけれど、これも検討状況と一体なのかなとも思うんですけれど、その辺の検討状況がわかれば教えていただきたいんですが。","respondent":"日下部企画財政課長","answer":"そういうものとして受けとめればいいんじゃないかと考えています。それから４４４項目の検討状況ですけれども、これは上下水道に始まって法令に根拠を持つ事務も含めて総ざらえをするということで、今検討を進めつつあると。","voiceIndex":34,"id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"それまでの間に今のお話だけだと実際に事務配分そのものが進んでいくのかどうか。もしセットでという考え方をしていくと事務配分そのものが進んでいくのかどうか、平成２０年までに決定をし、報告なり何なりあるという状況になるのかどうか、ちょっと疑問としてあるんですけれど。","respondent":"日下部企画財政課長","answer":"もともとは最初に事務配分をスタートさせて、昨年の１０月からある程度事務配分が進んだところで区域の再編の問題に取り組む。","voiceIndex":36,"id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"都区の財政じゃないですよ、「都の区」じゃない東京市間の財政調整みたいなものをちゃんと考えていかなきゃいけないというのは、わかったようだけれども、さっき言った「実現可能の」というところと両面考えたら、これは区長会でまとめたものとの間で何かギャップが生じていて、集約をするために区長会会長が困っちゃったんじゃないかなという気がしないでもないんだけれども、その辺はどうなんですか。","respondent":"日下部企画財政課長","answer":"ですから、最初、経緯の中でも触れましたように、いろいろな観点からの調査・検討がなされて、いろいろな経過を経て今回こういう具体的な提言になったわけでありますけれども、区長会の会長はかなり画期的な内容だということで評価をしておりますけれども。","voiceIndex":38,"id":"exchange-015"},{"speaker":"土井委員","kind":"意見","question":"そういうことになるとしか考えようがないわけですけれども、これから具体化するのに具体的なものはある意味では何も書いてあるわけじゃありませんから、これからどういうふうにしていくかということが議論され、進めていく形になるんですが。ある意味ではこれはもろ刃の剣なわけですよね。ちょっとお考えを聞かせていただいて、きょうのところは終わりに。","respondent":"日下部企画財政課長","answer":"で、１つの落としどころとして自立性を高めつつ調整機能は残すという形で、今回の連合の構想が生み出されたと私どもは受けとめておりますし、いずれにしても２３区の受けとめ方はいろいろこれからあろうかと思いますので、十分な議論が必要ではないかと考えております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"土井委員","kind":"意見","question":"私がこれを聞いた段階で思うのは、今の財政調整も含めた、また仕事の割り振りを含めたものを、今ある都と今ある２３区とで考えるからいけないのであって、都でやっている仕事も何もかも、地域の仕事は全部こちらがいただくんだと。そういうことを我々は目指すべきじゃないかなと思っているもので、ちょっとその辺の流れが変にならないのかなと思っただけです。意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これに書かれてあることは非常に刺激的ですよね。中身のこと以外の議論もできるんですけれど、やはり区長会はどういうふうにこれを位置づけているのかなということが一番気になりますね。これを本当に本格的議論をしていくと腹を決めたのであれば、それこそ２３区の区議会だって相談があってしかるべきだし、区民にとっても大きな問題になってくるというところまで行くわけじゃないですか。","respondent":"日下部企画財政課長","answer":"いずれにしましても中身は非常に盛りだくさんでありますし、またこの間のいろいろな経緯を踏まえますとかなり大胆な提言もされておりますので、区長会そして我々区も、理事者側としてもこれからしっかりと。","voiceIndex":43,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひお願いしたいのが、区長会としてこういうことを真剣に議論していこうということになった場合、これは当然議会にも報告をしていただきたいのと、場合によっては議会からこのことに対して意見を申し上げるものをつくっていただきたい。という要望ぐらい、内容がすごく刺激があり過ぎるじゃないですか。「都の区」の制度廃止とか、新しい財政のスキームをつくっていくとか。","respondent":"日下部企画財政課長","answer":"私も過去いろいろ勉強した経緯がありますけれども、自治権の拡充運動という、品川区は非常に主導的な役割をされたというふうに承知しておりますけれども、その際はやはり行政だけではなくて、もちろん議会、区民の皆さん方を巻き込んで、やはり皆さん方が考え方を１つにして。","voiceIndex":45,"id":"exchange-019"}]},{"id":"topic-02","title":"移ってまいります。予定表の３、行政視察の報告書","agenda":"移ってまいります。予定表の３、行政視察の報告書","exchanges":[{"speaker":"土井委員","kind":"意見","question":"事故が起きると先ほどの案のように預かりのルール化なんていうのをやるんですけれど、ルールをつくったって、もう預かりたくなくなりますよね、みんな。そうすると結局、預けられなくなっちゃうと一番困るのは区民のそういう皆さんなのね。だからそこのところはぜひ気持ちをくみ上げて、ちゃんと預かれるルール化をしてください。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"１２７万何がしを相続人に渡したと。それはどこから出されているかということと、現実にどうしているかということですね。それを教えてください。","respondent":"桑村総務課長","answer":"公金等でそれについて埋めるという準備をしていますけれども、一定の段階が来るまでというふうにさせていただいて、この１２７万７,０００円のうち２７万７,０００円はいわゆる本当に預かったということなんですけれども、施設から預かったお金。","voiceIndex":55,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1774#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":36480,"voices":59}},{"id":"h20-20080122-14","meetingId":"h20-cm01","date":"2008年1月22日","dateIso":"2008-01-22","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時２２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"財政（歳入）に関すること","agenda":"財政（歳入）に関すること","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"教えていただきたいんですが、この表を見て、保育料をはじめ、今、それぞれの課長から６項目について説明いただいたんですけれども、単純に教えていただきたいんですが、平成１８年度だけで結構なんですけれども、平成１８年度の未収入額というのを、ここに多分記載されていないと思うんですけれども、収入未済額はこういう形で繰り越しになってその金額が出ているんですが。","respondent":"日下部企画財政課長","answer":"２点ご質問をいただきました。","voiceIndex":10,"id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"何点かお伺いしたいと思います。これはもしやっていなければ、ちょっと一度その視点で洗っていただければと思うんですが、いかがでしょうか。これが１点です。そうすると、毎年いろいろと収入確保に向けた取り組みをされているということなんですが、年間の徴収のコストと年間の２０万円の収入額と比較したときに、果たしてどうなのかなと、ちょっとその辺のお考えを伺いたい。","respondent":"小林保育課長、金子産業振興課長","answer":"２点のお尋ねです。１点目、払えるのに払わないのはどういう状況なのかというお尋ねですけれども、こちらは収入未済の中で、現年度分のお支払いいただいていない分と、過年度分と分けてご説明をしたいと思います。全部が全部ではないですけれども、少額ではありますが、きちっと定期的に払っていただいている方もおりますので、私どもとしては、この部分について簡単に放棄することはできないだろうと考えています。","voiceIndex":12,"id":"exchange-002"},{"speaker":"阿部委員","kind":"提案","question":"虐待家庭を発見するのはそれこそかなり大変なことでもありますし、いろいろな手段で発見に努めるべきであろうかと思われますので、この保育園保育料の滞納という情報を、個人情報の関係なんかもあって難しい点はあるかとは思いますけれども、このことを福祉につなげていくことで、発見のツールとして活用できないだろうかとご提案させていただきましたので、改めてご答弁をお願いいたします。","respondent":"小林保育課長","answer":"現状なんですけれども、確かに納めていただけないケースで、保育園のほうで対応しておりますので、どうしてなんだろうということでみたときに、例えばご両親が今、別居中ですとか、そういった形で滞納に結びつく例があろうかと思います。","voiceIndex":15,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"全体のところで基本的なところを、前も１回あったと思うんですが、教えてもらいたいんですけれども、不納欠損になるのは、さきほど生活福祉課長もちらっと言っていましたが、５年でいいんですか。５年滞納が繰越になると不納欠損のほうに入るのかどうか、教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"そういうのが適用されるようなものについては１０年とか、そういうものもあるんですが、法律に特別の定めのないもの、例えば地方税とか国民健康保険については、その法律の中で具体的に規定されておりますけれども、それ以外の一般的な分担金とか使用料とか。","voiceIndex":17,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"そうすると、ここに出していただいているのは全部５年という考えでよろしいんですね。そうしますと、ちょっとまたその仕組みのことで教えてもらいたいのが、不納欠損になって、例えば何年かたつと不納欠損からも数字が除かれるんでしょうか。ここに今回出していただいているものは、すべて不納欠損になるのは５年ということでよろしいんですね。","respondent":"日下部企画財政課長","answer":"基本は５年なんですが、時効の援用といいますか、具体的に時効についての適用といいますか、そういったものを申し出をした場合に、それが１つの時効の適用の前提条件になるとか、あるいは消滅事項につきましても、例えば督促をした場合、その時効の中断ということで。","voiceIndex":19,"id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"いまひとつわからないんですが、聞きたかったことをストレートに聞かせていただくと、例えば６ページのこの中小企業事業資金のほうですと、不納欠損額が平成１７年度１６０万円強でありまして、平成１８年度になると不納欠損額がゼロになっているんですけれども、これは不納欠損額に数字として出てきて、どういう理由でゼロになるのかという、何年かたつととか、そういうのがあるんでしょうか。","respondent":"金子産業振興課長","answer":"先ほど企画財政課長が説明を申し上げました５年で時効になるというものの例外が私どもの債権でして、先ほど説明したとおり、債務者のほうが、消滅時効が成立しているので支払い義務もないといったような申し立てをするとか、あるいは何らかの事情。","voiceIndex":21,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問","question":"１６２万何がしというのは今の理由で、不納欠損扱いとしてここに数字が出てきたということだと思うんですけれども、その翌年に今度不納欠損がゼロになっているということは、その理由が今の理由なんでしょうか。ちょっと私の聞き方が悪いかもしれませんが。","respondent":"金子産業振興課長","answer":"平成１８年度につきましては、今のように破産の申し立てであるとか、あるいは亡くなっているとか、そういった事実が確認できたものがありませんので、この不納欠損の処理をするものがないということでゼロになってあります。","voiceIndex":23,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"そうすると不納欠損については、１年たつと、基本的には前年度に出た数字は１回ゼロになると、そういう考えですね。収入未済額の中の４年間かの滞納繰越でずっと来ているのとまた違って、１年ごとでゼロに１回戻ると。それでまた新たに不納欠損が出てくる場合と出てこない場合があると、そういう見方でよろしいですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"所管の説明の中で、いろいろ対応の中でこういう実態があるというお話が出ていましたけれども、まず区の姿勢として、滞納者に対してどのように接しているのか、いくのか、調査把握が私は大事ではないかと思うんですけれども、まずその区の全体的な姿勢を伺わせてください。","respondent":"日下部企画財政課長","answer":"払えない実態の把握ということでありますけれども、これはさっきもいろいろ収入確保の取り組みも含めてご説明させていただきましたけれども、それぞれの内容によって、いろいろな性格とか事情に違いはありますけれども、基本的には納めていただく。","voiceIndex":28,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"今のお話ですと、それぞれの課のほうで状況や理由の把握を進めているというお話でしたので、ちょっとそれぞれ伺いたいんですけれども、保育課のほうは保育料のこと、住宅課のほうは区営住宅、区民住宅のこと、この３つで結構ですけれども、どういった調査、把握を今実施しているのか、把握の方法について伺わせてください。","respondent":"小林保育課長、齋藤住宅課長","answer":"こういった経過の中で、払える能力云々という家庭の資力の問題、あるいはいろいろなご家庭のご事情も含めて、子どもの生活の状況の把握等をやり、そしてその中でやむを得ない場合につきましては、減額の対応をする場合もあり。住宅に関しましては、一般の住宅と違いまして、１つ入居者に義務があります。それは収入の状況を毎年度報告する義務があります。区営住宅に関しましては、基本的に３万７,１００円が基本料金です。","voiceIndex":30,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"ぜひほかの課でも相手の状況の流れを把握する上で、こういった状況の把握というのをまずはきちんと調査をすることが必要ではないかと思っていますので、全体的なことになると思いますけれども、まずはなぜ払えないのか、その調査を大切にやるべきだと思うので、もう一度その点をお聞かせください。区のほうではその辺はどういうふうに対応されているのかなということをお伺いしたいんです。","respondent":"日下部企画財政課長","answer":"１点目の実態の把握ということでありますけれども、今、保育課長、住宅課長のほうからもご説明をさせていただきましたけれども、それぞれの状況を踏まえて、それぞれ工夫をしながら実態を把握し、またそれに応じた形での対応をしているわけでありますので。","voiceIndex":33,"id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"これで最後にしますけれども、日弁連のほうが厚生労働省や国税当局に対して行った提言の中で、滞納者に対していたずらに強制執行を立てるのではなくて、まず多重債務者かどうかをきちんと調査すべきではないかという提案をしているんですね。ぜひそれぞれ保育課、住宅課、生活福祉課、いろいろあるとは思いますけれども、この多重債務者のまず調査を大事にしていただきたいと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"という考え方なのか、この保育料のところで言う３番の表を見ると、一番右側はＡ－Ｂ＋Ｃ－Ｄになっているとすると、Ａというのは全額その年に発生した保育園にあずけている親が払わなければいけないいわゆる保育料なのか、それとも１０億９,５００万円から今言ったような３,５００万円を引いた１０億６,０００万円ぐらいが、その年に払うべき保育料というふうに考えるものなのか。","respondent":"小林保育課長","answer":"収入未済額の今年度の３,３３７万９,４５０円の内訳といたしましては、現年度の分でお支払いいただけなかったものが８０２万８,９９０円、内訳として過年度分が２,５３５万４６０円ですので、前年度末の収入未済額３,５００万円のうち。","voiceIndex":36,"id":"exchange-013"},{"speaker":"林委員","kind":"意見","question":"次に聞こうと思ったんですけれども、そうすると、ご答弁いただいた保育料について聞きます。１０億９,５００万円の中に、前年の未済額３,５００万円は入っているか入っていないかということを先に知りたかった。その後に今の答えを。その分だけちょっと答えてください。","respondent":"小林保育課長","answer":"大変失礼いたしました。入っております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"そうすると、ここからちょっと頭が混乱してくる。さっき言ったＡ－Ｂ＋Ｃ－Ｄというのは、１０億９,５００万円から３,５００万円を引くと、１０億６,０００万円という数字から、１０億６,６１００万円を引くということになると、それで、合わないな。どうも数字が混乱しているんだけれども、入っているということがわかればいい。これはどういうふうに考えればいいんですかね。これをどうとらえますか。","respondent":"日下部企画財政課長","answer":"私自身の考え方から申しますと、さっき保育課長が収入未済額のところで、これが平成１８年度については３,３３７万９,４５０円になんですが、現年分、つまり平成１８年度だけで見ますと８００万円ですね。","voiceIndex":40,"id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"ちょっと違う視点からいきます。保育料の場合は、一番長い人で５年間、０歳から入った人は６年間払い続けなきゃならない。住宅の場合は一生というか、何十年というケースも出てくる。公平という観点から、現年分が増えるということはやむを得ないかもしれないけれども、過年度分について、前年に生じた返済分だよね。そういうきめ細かさというのをとっている部署はあるんですか。","respondent":"日下部企画財政課長","answer":"それぞれ今、とにかく滞納の解消ということで一生懸命努力しているわけですが、例えばさっき申し上げたように、住宅の例で申し上げますと、３ページに出てまいりますけれども、住宅課長は非常にこの間。","voiceIndex":42,"id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"保育料で言うと２００件ぐらいあるということなんだけれども、それが例えば今年払えなくなっちゃって、５万円ぐらいが、何カ月分にあたるかわからないけれども、５万円から１０万円ぐらいが残っちゃっている人と、ずっと払えなくて、何十万円あるいは１００万円に達している人がいるのかな。例えば５万円なら、５カ月で１万円ずつならそんなに厳しくないや。","respondent":"小林保育課長","answer":"現在抱えているのでは、一番短いものは４回払い、一番多いのは９０回払いまで持っておりますので、そういった形の中で対応しています。","voiceIndex":44,"id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"さっき保育課長からは現年分は８０２万円で過年度分が２,５００万円強、これは過年度分を抱えながら、今年度も滞納しているというふうにとるのか、新たに今年から滞納が始まった、そういう人もいますよね。そうすると、この滞納というのは、毎年、額じゃなくて、人数で増え続けているんですか。","respondent":"齋藤住宅課長","answer":"住宅課長の私から説明します。ケースバイケースでございまして、そこまできちんと分析はしておりませんが、区営住宅の例で参考に言わせてもらいますと、平成１８年度の例で申しますと、８８９万５,０００円ありますが、このうち現年の滞納は５０万円。","voiceIndex":46,"id":"exchange-018"},{"speaker":"林委員","kind":"質問・要望","question":"やっぱりその辺の額はこうやって出てきますよね。各部署で決算を出すわけだから。ここに６つ出していただいて、ちょっと５番、６番は違うかな。例えば保育園にお子さんを入れていて、区民住宅に住んでいて、奨学金もという、例えば重複して絡んでいる人はいないんですか。それからもう１点は、例えば返す人たちに、今年から品川区が実施している日曜開庁のときは、この返済は受け付けているんですか。","respondent":"齋藤住宅課長","answer":"保育料、区民住宅滞納についての突き合わせはしておりませんので、把握しておりません。日曜開庁につきましては、区民住宅につきましては、指定管理者のほうで出張して収納する。住宅課では取らないということにしておりますので、銀行があいていない日曜日は収納はできません。","voiceIndex":48,"id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"同じ人がいないことを祈りますけれども、それはすぐ簡単にできることでしょうから、しておかなきゃいけないんじゃないかなと思います。最後にします。３ページの住宅、１,０５６戸のうち空き室が２９戸、これは入ってもらっていれば収入があるわけですね。空き室だから収入はゼロですね。","respondent":"齋藤住宅課長","answer":"３世帯のオーナーさんとお話をさせていただきまして、２世帯おおむねご了解いただいたんですけれども、区が頭を下げて住宅施策に協力したんだから、空きがあるのは区のせいだと、こういった形でオーナーさんと話をされますと、大きい意味で言うと。","voiceIndex":50,"id":"exchange-020"},{"speaker":"林委員","kind":"意見","question":"ちょっと違うんだよ。僕が言っているのは、滞納という考え方からすると、入ってくるべきものが入ってこないというのは滞納でしょう。例えば月に保育料が３万円ですというところを、３万円が入ってこない、滞納になっていくわけです。それは入っていたら入っている人が払うべきだけれども、入っていないということは、区の責任で区が滞納しているというふうに考えることはできませんかと聞いているんです。","respondent":"齋藤住宅課長","answer":"率直に申し上げまして、サブリース契約、民間でもあります。１棟借りをするという契約での、私どもの義務は大家さんに入っていても入っていなくてもお支払いする義務があるという関係でございまして、空いていないのが滞納だというのは、ちょっと違うかなと私は考えております。","voiceIndex":52,"id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"もう少し厳しい言い方をしてしまえば、しっかりとどうにか徴収をしていかなきゃいけない。ですから、１０％お支払いしますよじゃなくて、これは考え方の問題だと思うんですけれども、１０％減額してあげますよという、民間で言うところのおまけですよという感覚になると思うんですね。というのは、我々委員も歳費ですから、動いても動かなくても同じ数字が入ります。","respondent":"齋藤住宅課長","answer":"それにつきましては、お話をさせていただいて、１カ月目から指定管理者の職員が滞納先にお邪魔しておりまして、そういった意味で言うと、そういったきめの細かさが高い収納率につながっていると考えておりますので、引き続き１００％に向けて努力をするです。","voiceIndex":54,"id":"exchange-022"},{"speaker":"原委員","kind":"質問","question":"実際に民間であれば９０を超えている。実際の問題、他区なんかの場合には８０ちょい超えから９１～２％がいいところだろうという感覚を持っています。それでもう１点だけ、次のステップとしてお聞きしたかったのが、今の法的なところに入ってきちゃうので難しいんですけれども、さっき一般的に５年というところなんですけれども、２番、３番について期間を教えていただければと思います。","respondent":"齋藤住宅課長","answer":"１０年に延びたものの滞納督促を去年ちょっと一生懸命やったんですけれども、先ほど申し上げました自力執行権といいまして、税務課の職員であれば銀行に行って税務吏員証というのを見せると、そこの人に銀行預金がここに幾らあって幾らかというのを教えてもらえるし。","voiceIndex":56,"id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたら、先ほどご説明いただきました民間の信用保証機関ですか、この辺を今以上に活用いただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"数点お伺いしたいのですが、まず初めに保育料の件なんですが、これは滞納者を出さないための取り組みを見ているだけでも、明らかに１００％口座振替になれば非常に収入率が上がるのかなと思うのですが、現在、９４％以上が口座振替で、納付書による金融機関等での納付が約５％弱ということですが、この収入率を見ても、先ほど９６.８％か何かが収入率だということで。","respondent":"小林保育課長、鷹倉区民課長","answer":"ないしは口座を持っているけれども、口座振替にしたくないという形で口座振替のご依頼をちょうだいできないケースです。ただ一たん貸付が始まりますと、これは私どももある意味では民民のお金を貸すだけですから、相手に対する調査権等々も特にございません。したがって、学校に対してどういう状況になっているかということも聞けることはありません。","voiceIndex":59,"id":"exchange-025"},{"speaker":"石田（慎）委員","kind":"提案","question":"僕たちも選挙があって、４年間の任期があって、その後また選挙ですが、その間に何もしなかったらもちろん忘れられてしまうという、やっぱり４年間というのは非常に長いものでして、できたら年に１回でも、件数がものすごく莫大だったらなかなかできないと思うんですが、何らかのコンタクトでも構わないと思うんですが、その意識を常に持っていただくというのが。","respondent":"鷹倉区民課長","answer":"私ども、先ほど返す１年ぐらい前からそういうお手紙という話なんですが、今、委員ご提案の部分も何らかの形で生かせないかどうか、創意工夫していきたいなと思ってあります。","voiceIndex":62,"id":"exchange-026"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ここに書いてあるとおり、貸付の目的として、将来有用な人材を育成するということなんですが、実際にこの貸付があった方たちに、転出等が生じた場合はもちろん終了するということなんですが、今まで例えば品川区に、中学、高校にいて、その高校に在学のときに借りていた方たちが、高校を卒業して品川区から出られてしまった方の率と、そのまま品川区に残って何らかの。","respondent":"鷹倉区民課長","answer":"退学といいますか、そういう場合もある。私ども貸すときに、修学が３年間継続していける方で、それがまさに勉学意欲がある方ということになりますので、途中でやめられないようにいろいろ考慮しています。","voiceIndex":64,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実態の把握はそれぞれ行っていますというご答弁があったんですけれども、払っていける能力があるか否か、その辺はどういったところで判断をされているのかというところを、１つ大きなところでお聞かせいただきたいのと、あと保育料のところがわかりやすいので、さっきから質問が集中しているんですけれども、保育料の滞納の階層別のところの分布状況がわかるような資料があったら教えていただきたいのと。","respondent":"日下部企画財政課長、齋藤住宅課長、小林保育課長","answer":"支払い能力をどうやって判断するのかということでありますけれども、それはまたそれぞれの科目によりましていろいろな違いはあろうかと思いますけれども。住宅に特化してみますと、収入階層を毎年度調査しておりますが、滞納の出る方は、収入は年間で見れば一定なんだけれども。それから減額についてですけれども、減額制度としては、基本的には本人の申請を前提といたしまして、減額が認められる要件としては。","voiceIndex":66,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"減額のところなんですけれども、減額を受けていても、かつ払えないという状況であるわけですよね。これは皆さん認めるところだと思うんです。だから、そういった状況がこの滞納というか、収入未済額のこういったところから、区政全体的に区民の実態をどうとらえていらっしゃるのかなというところを、ぜひ今の機会なので伺いたいんですが、いかがでしょうか。","respondent":"小林保育課長、日下部企画財政課長","answer":"免除のほうですけれども、生活保護世帯、あるいは住民税非課税世帯合わせまして全体で７.９％、８％弱の方が免除になってあります。区民生活と滞納の関係ということでのご質問かと思いますけれども、区民生活、３４万区民の生活実態というのはさまざまですので、なかなかこれを一律にどうということであらわすというのは、現実問題非常に難しいと思います。","voiceIndex":70,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"提案","question":"基本的なところはもちろんそうだと思って伺わせていただきました。だから、そういった面では滞納の原因をしっかりとつかんでいくというのが、まずその実態を調査して把握をするということが１番であるし、また今言ったような対策も品川区自治体としてぜひとっていただけたら、こういった問題も生活苦のところもあわせて改善していくのではないかと思うんですけれども、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"確かに多重債務の問題でよく出てくるのは、今、ご指摘のあったグレーゾーンの問題ですが、これもたしか新聞報道等でも、近々法改正が進んで、こういった問題の解消も進んでいくというふうに承知をしておりますので、一自治体のレベルで何ができるか。","voiceIndex":73,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多重債務とかサラ金の問題なんかは、区民相談なんかで今も実施をされていますけれども、ぜひ区のほうで積極的に区民の実態を把握するという意味で、相談の充実をしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"金野委員","kind":"質問・要望","question":"１つだけ確認というか、教えていただきたいのが生活保護費の弁償金のところなんですけれども、これは生活保護を受けているところに思いがけなく収入があったというところで、その分返還をしていくというものだと思うんですけれども、このとき、例えば先ほど例に挙げていただいた遺産だとか保険金だとか、それは額が結構大きいので。","respondent":"志村生活福祉課長","answer":"生活保護制度そのものを適用していくかどうかというのは、最低生活保護基準というのをまず算出してまいります。手近な例で、６０歳の方で、品川区にお住まいの方ですと、大体８万円弱が最低保護基準です。","voiceIndex":76,"id":"exchange-032"},{"speaker":"金野委員","kind":"質問","question":"そうすると、資力があるということで返すにあたって、資力の度合いによって返済をしていくのに、結構保護費の中で返済をするのが大変な方も中にはいらっしゃるかと思うんですが、その辺は現状どうなんでしょうか。","respondent":"志村生活福祉課長","answer":"保護の継続されている方につきましては、逆に言いますと、最低生活基準そのものの保護費を出しているわけですから、そこからお金を返していただくとなりますと、厳密に言いますと、返してもらった分だけ最低保護基準を割っているわけですね。","voiceIndex":78,"id":"exchange-033"},{"speaker":"阿部委員","kind":"意見","question":"冒頭、給食費のことがありましたが、公会計にのってこないものの中で、未納というものは他にあるものなのか。もしあれば、どういったものがありうるのか、あるいはその種類とボリュームがわかれば、お教えいただければと思います。","respondent":"日下部企画財政課長","answer":"これをどうして委員会として扱わないのかということですが、おそらく今回、テーマとしては歳入に関することで、これは厳密に言えば歳入扱いということにはなりませんので、そういう意味から、私どもとしては具体的な項目として上げさせていただいていないです。","voiceIndex":80,"id":"exchange-034"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"収入未済のうちの現年度と過年度で先ほど保育費が出ましたけれども、生活保護費の中でどういう割合になっているのかというのと、奨学金貸付金元利収入も現年度分と過年度分を教えていただきたいと思います。","respondent":"志村生活福祉課長、鷹倉区民課長","answer":"弁償金の中身についてご説明申し上げます。９６４万７,０００円。そして滞納分、調定額は申し上げましたので、収納額が９４２万３,６５０円、これの残りの２,１６１万５,６００円が滞納分の未済分、先払い分についてはすべて収納されているということになります。","voiceIndex":82,"id":"exchange-035"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"数字はわかりました。ただ生活保護費の中でもう１つ収入額が出てくる。この収入額は全額区の収入ではないですね。そこら辺の扱いはどうなるのか、それをちょっと説明していただきたいのと、それから奨学金に関してなんですけれども、これは制度的なものなんですけれども、先ほどの説明の中で、返済しているのは高校を卒業後１年以降の本人ですよね。他区の状況なんかは、やっぱり本人に貸しているんですか。","respondent":"志村生活福祉課長、鷹倉区民課長","answer":"お尋ねのとおりでございまして、収入済額の例えば平成１８年度の５,８２８万１,０００円、このうち現年度分が４,６００万円とお答えしました。勧誘に応じてしていただければそれをどんどん進めていくということなんですが、そこで拒否された場合にこれでなければだめだということにはならないということになっております。","voiceIndex":85,"id":"exchange-036"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"最後の部分がちょっと引っかかったんですけれども、入れるときは振込でもらっていますよね。これで振り込みますよという承諾をもらうときに。返済も口座振替ということは規定上、切りかえることはできないのかなというのは、そのほうが今後の回収を考えていくと、どういう条件でできないのかわからないんだけれども、その規定は改正することができればと思うんですけれども。","respondent":"鷹倉区民課長","answer":"自動引き落としをお願いしますという形で、金融機関に借りた方が行っていただくというスタイルになりますので、そういう形の行動をとっていただくように勧誘する、強く勧めるということまでかなと考えています。","voiceIndex":88,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":39468,"voices":92}},{"id":"h20-20080123-16","meetingId":"h20-cm01","date":"2008年1月23日","dateIso":"2008-01-23","committee":"街づくり特別委員会","time":"午前８時５０分～午後４時１４分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":1144,"voices":6}},{"id":"h20-20080222-3","meetingId":"h20-c-budget","date":"2008年2月22日","dateIso":"2008-02-22","committee":"予算特別委員会","time":"午後２時４５分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":2261,"voices":18}},{"id":"h20-20080225-6","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"区民委員会","time":"午前１０時０３分～午後２時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"年収が年金で２００万円の方にとってこういう増加というのは、やはり総体的に考えても負担が重いなと考えるんですけれども、この間、随分と、医療費適正化の名のもとに制度がどんどん変わっているので、平成１７年度、１８年度のこの２００万円の方の保険料というのはどのように変化していったのかというのを改めてお伺いしたいんですが。","respondent":"原国保年金課長","answer":"平成１７年度です。３万２,１００円。均等割のみという形になってあります。平成１８年度は４万７,３００円、それから平成１９年度が５万７,０００円、それから平成２０年度が７万３,０００円。細かいところは別にしまして、７万３,３００円余です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"だから、この上がり方は尋常じゃなくて、これが私は憲法２５条の精神、「すべての国民は貧富の差にかかわりなく医療を受ける権利を持つ」と、そういう生存権を規定しているわけですけれども、その権利を保障する義務を負うというこの国の義務、この２５条の精神に、ここまで来ると違反をするような改正という名の改悪だと思うんですが、やはり区が、そういう国の憲法に抵触するようなぐらいの改悪に、何とか。","respondent":"原国保年金課長","answer":"この間、住民税の改正がされましたけれども、この住民税の改正の考え方は、少子高齢化、こういったところをこれからどんどん進展する中で、この社会保障制度、こういったものを維持していくために、高齢者の方も所得に応じて負担を分かち合っていただくと。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"文化的な生活を営む権利があって、それを保障するという国の義務ということを定めた憲法に照らしてどうなのかという、ぜひその憲法の方向に向けて頑張るという立場で頑張ってほしいと思います。むしろ社会保障費が区民生活を圧迫しているんじゃないかというふうな認識というんですかね、それをどのように考えているのかというのをお伺いしたいんですけれども。","respondent":"原国保年金課長","answer":"それ以後も給与所得の方についてはおよそそのぐらいの金額を推移しています。こういったように、同じ金額でありながら、大きく金額の違うところを兼ね合いをしながら進めていきたいと思っているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"この間の地価高騰、再開発の推進によりまして家賃も上がってきていまして、二重三重に、相乗的に負担が大変になっちゃって。所得が低い人にも必ずかかる均等割のほうの比率が上がってきているというのは、ちょっとこれは私としてはむしろ逆なんじゃないかなと思うんですけれども、そこら辺の認識はいかがでしょうか。","respondent":"原国保年金課長","answer":"そういった中で、国保については、所得の低い方は、先ほど申し上げました国の基準では６割、４割というところを、特別区にあってはそれに１割を上乗せするというところで軽減策をさらに講じて、また保険料につきましても一般財源の繰り入れということで、例えば高額療養費。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"国保はもっと、今の制度をもっと区民の立場で、よくするために、負担をさせなくちゃいけないし、あと国が国保財政に負担する部分をもっと抜本的に上げなさいというのを言うべきだし、ましてやこれから負担を企業とかが引き上げるような動きに対しては絶対に許さないという立場をとってくださいというふうに、苦しめている大もとの国の政治に対して、政府に対してがつんと意見を上げるとか。","respondent":"原国保年金課長","answer":"医療費の問題につきましては、伸びだけの問題ではなくて、やはり医療費の中身、今、国の総医療費が３３兆円という中で、この中でこの４月から実施します特定健診、特定保健指導に見られますように、生活習慣病にかかっている治療費。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望というのはどういう要望なのかいうのを、それだけちょっと聞きたいんですけれども。","respondent":"原国保年金課長","answer":"例えば全国市長会、こういったところで、今回始まります健診等についても、それなりの負担を国のほうで負ってほしいということでの要望をしておりますし、国庫負担の４割等についても、そういったところについても増やしてほしい等々の要望をしています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"今、法改正による大まかなことを伺った中で、ほんとうはやはり品川区としてどうしているかというところを伺いたいんですが、まず、今賦課割合のところ、所得割と均等割は制度上の考慮といいますか、区としての対応は非常によくわかりました。５０対５０が基本の中で、低所得者層のためということで、ほかの政令市等の状況等をかんがみて、制度上はすごくわかりました。","respondent":"原国保年金課長","answer":"出産、葬祭、こういった経費等々含めてお願いしているところでございまして、それと職員の給与費。こういったところも一般会計の繰り入れです。そういったものを踏まえますと、先ほども申し上げました５０億円前後のお金を一般会計からの繰り入れでお願いしています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"今、国保の個人負担分という中で、滞納というのはどのぐらいあるのでしょうか。","respondent":"原国保年金課長","answer":"当然こちらにつきましては、いろいろお支払いいただくための交渉等をしておりますので、その後増えてまいりますけれども、そういった数字です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"渡部委員","kind":"意見","question":"１４％程度の滞納をされている方がいらっしゃるとして、その後支払いをお願いしていても、現実問題として入ってこない部分というのが多分あるんであろうと思います。逆を言うと、６５歳未満の給与所得者というのがこれからどんどん減っていく現状というのがある中で、国民健康保険の制度を維持していかなければならないと思うんです。","respondent":"原国保年金課長","answer":"健診等こういったものを効果的に実施する中で、医療費の伸びを見ながら、また健康寿命というんですか、病気をしながら長生きをする前に、健康で長生きできる、こういったために今一番大きな問題になっております生活習慣病、こういった対策にも力を入れながら。","voiceIndex":22,"id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"課長さんに細かくご説明いただいたんですけれども、すごく難しくて、数字とか表ではわかるんですけれども、実態でどうなっているのかなというのがほんとうにつかみにくいし、どうしてこんなに複雑なんですかと聞きたいぐらいですけれども、そこを聞いても仕方がないのでそこは聞きませんけれども、一番わかりやすいのが、さっき安藤委員が質問で、３８ページの年金所得者の特に２００万円。","respondent":"原国保年金課長","answer":"所得割、均等割等々についても、賦課割合は５０対５０というような基本的な基準政令というものを持ってあります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今、大もとのところを伺ったら、医療費が増えている。もちろん高齢化が進んでいるので、医療費は増えていると思いますけれども、それだけでしょうか。１９８４年に、今まで医療費の４５％、全体の４５％を国が出していたのが、医療給付の５０％。実際に使われた医療給付の５０％。そこが１つ答えていただきたいのと、あと、住民の側にばかり負担がかかりますね。私はここをぜひお答えいただきたい。","respondent":"原国保年金課長","answer":"新しく、平成２０年度からは、そこに前期高齢者支援金ということで、さらに国保のほうは、全国で見ますと６５歳から７４歳の加入者割合が、国保を前提で見ますと非常に大きいと。２６％ぐらいと算定をされています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この２０年間で。その中で保険料がどうなっているのかといったら、１９８４年、３万９,０００円が、２００４年では７万９,０００円になっているんです。何と２倍ちょっとです。私はこの点が１つ、ここはきちんと認めていただきたいなと思うのが１つです。この医療と支援が一体何なのかというのを説明してほしいのと、どうして２本立てになったのかという部分をご説明をいただきたいと思います。","respondent":"原国保年金課長","answer":"自治体の負担がどうなるのかです。今回は、るる説明してまいりましたけれども、非常に大きな制度改正になってあります。一つ一つを取り出しますと、数字も億単位で動いております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問","question":"特定健診のところなんですが、前にもお伺いしたことなのであれなんですけれども、国の特定健診、メタボリック症候群に焦点を当てた特定健診の中身なんですが、この間お伺いをしているんですが、国基準のところを示すと、品川区でも今までと変わらないでやりますよというお話をこの間も伺ったんですが、国の基準の項目のところをもう一回お話ししますけれども。","respondent":"原国保年金課長","answer":"国の基準から外れて今までやっているものについては、区のほうで、国の基準への上乗せ項目ということで実施するということで決めてありますので、従前の区民健診と同等の中身で行くです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"失礼だったかな。特定健診に基づいて保健指導をやられるということですけれども、前に伺ったときに、これは民間委託で行われるということで、一体どういうところがこの保健指導を行うのかというところと、あと今までは保健師が把握をしていた部分が、保健指導のところが委託されたときに、どうその辺で住民を把握するというところにつながっていくのかというところがとても見えないので、教えてください。","respondent":"原国保年金課長","answer":"そういった中で、具体的に民間に委託できる部分については委託をしていくということで考えてございまして、これは国保でいきますとこういった流れをこれからつくっていくわけですけれども、民間での健保組合等々においては。","voiceIndex":33,"id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問","question":"民間委託は例えばどういうところに業務が委託されるのかというのと、予算的には、すごい単純なところを委託するということなのでしょうか。その辺をもうちょっと知りたいんです。","respondent":"原国保年金課長","answer":"民間委託の件ですけれども、現在民間事業者への委託ということで、プロポーザルを実施してございまして、区のほうで基本的な考え方を持ちながら、民間のノウハウの中でどういったことがより効果的なものとして対応が可能かということで、提案を今いただいている最中ですので。","voiceIndex":35,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"説明のところでちょっと気になっちゃったので、必要なところは国保料ですけれども、あと全体の制度の問題で、基本的なところを政令で決めて、医療費がすごく増大しているからしようがないんだみたいな、我慢していただくんだというような説明というふうに聞こえたんですけれども、医療費というのは実際問題、日本というのはそんなにすごい多い、国際的に比べて多いものなんですかねということです。","respondent":"原国保年金課長","answer":"所得割についても現行の１００分の１１７が１００分の百三十幾つになってしまうということで、保険料を全体に押し上げるということで、その辺については従来どおり一般財源からの繰り入れでぜひお願いしたいということで、私どもは考えているところです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、そもそも医療費自体がものすごい異常な高さで、それがあって、しかも皆保健を維持するためには、どうしてもこの高い負担をお願いするしかないんだというような立場に立って説明されては困るというか、そもそも今回の改正と言いますけれども、改悪だと、改正の部分もありますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党として賛成します。今回の改正が後期高齢者医療制度の創設に伴った改正の部分がメインになって、保険料に対しては各軽減措置もとっていらっしゃいますし、品川区の一般財源の中で、４７億円ほどの繰り入れをしていることも含めまして、十分対応していると思います。この議案に対して賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-018"},{"speaker":"山路委員","kind":"意見","question":"そういうこともあって、今回昭和３６年以来の大幅な法改正が行われたと思うんですが、若い人がこれから持続可能な、また社会で元気に生きていける、働いていける、そういう意味が大いにこの裏には、数字の上には出てきませんけれども、そのもとで後期高齢といった高齢者の方でも、一定の年齢間格差をなくすために負担をしていただくということで、これで平等になって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"意見","question":"一部負担金、０歳から義務教育就学前までの対象拡大と、あと高額介護合算療養費、ここの部分はプラス面であると思っていますが、その他は反対です。１点目は、際限のない国保料の値上げ。国が当然負担すべきものを負担すべきだ。この点が１点です。７０歳から７４歳の窓口負担、２割負担。これもとんでもない大変な痛みなので、これはやめるべきであると思います。３点目、年金天引き。６５歳から７４歳。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"持続可能な医療保険制度を続けていく上で必要な改革だと思いますので、賛成をします。長いこれから先この地域を担ってくれる子どもたちの時代になったときに、どのようになっているかわからない。ただ、長い目で見た品川区、これからどんどん続けていくためにはこの医療保険制度の改革は必要だと思いますので、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"すばらしい条例だと思うんですが、例えば集団回収して、パトロールが回っていますね。これは現行犯なのかな。そこで例えばパトロールの人が、持ち去り行為をしている業者を見たら、そこで注意をうながして、それがあまりにも悪質だったら過料になるという流れでいいんですか、流れとしては。","respondent":"秋山資源循環推進課長","answer":"ご質問ですけれども、まず、持ち去り行為をした者に対して持ち去らないよう現場で、それから持ち去って車に積んでしまったものについては原状回復の命令をして、その命令に従わなければ、従わないということはそのまま持ち去ってしまうという状況になった場合に過料を科すです。","voiceIndex":54,"id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"ナンバープレートで追っていくのか、それとも例えば集団回収をやっている目の前で暴言をまたはいて、原状回復していってくださいと言っても、なおかつ無視して持っていってしまったという状況になったときに、電話をかけてパトロールの人が来たときにはもういないわけじゃないですか。そうなった場合というのは、逆にマニュアルとかをつくっているんですか。逃げてしまった場合はどうやって追っていくのか。","respondent":"秋山資源循環推進課長","answer":"パトロール隊では、例えばビデオを使ってその状況を、持ち去りの業者の撮影をして記録を残すなりして、持ち去り禁止の命令についてはその場で命令をして、それが次回、その日以降も続くわけですから。","voiceIndex":56,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"この資源回収を出されていたものを、例えば区の集団回収の人たちが集めて町会会館に移した場合というのは、これ、どうなりますかというのを１つお伺いして、この答えによってはその後の質問が変わっちゃうので、まずそれを先に聞かせていただいていいでしょうか。","respondent":"秋山資源循環推進課長","answer":"ですので、まず、悪質な者をこの条例を使って区民と一緒に取り締まっていくというか、そういうことを考えてあります。","voiceIndex":59,"id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのときに、せっかくこの条例を整備されるのであれば、例えば「区長または区長から指定された者」という中に、この「集団回収を行う団体を構成する者」という１文言が入るのであれば、何といったらいいのでしょうか、といいますのが、例えばそういう日に違法な業者があったときに、町会としても、例えば条例をすごく詳しく調べて盾にとられたときにどうにもならないのなら、現にパトロールの意味も込めて。","respondent":"岩崎環境清掃事業部長、島袋品川区清掃事務所長","answer":"集団回収と行政回収は同じ曜日で実施しているところはかなりあります。これは同じなんですから、何の問題もないということなんですね。一番私が心配しているのは、それだけ集団回収のほうが負担が大変なんですね。実際問題はパトロールに行くだけではなくて、待ち伏せてやっていきたい。それぐらいしないと、とてもじゃないけれども絶対に捕まらない。そういう準備がもろもろあるので７月に施行ということです。","voiceIndex":61,"id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"抑止効果の罰金とかいう話だったんですが、そこがちょっと何か、どういうことなのかもう少し説明してください。","respondent":"秋山資源循環推進課長","answer":"罰金になると、そういう運用になりますと、現場ですぐ過料を課すということとは、またちょっと変わってきますので、その辺も含めて検討していきたいというふうに考えております。","voiceIndex":64,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"４月ぐらいに説明会を集団回収の方に行うと言っていたんですが、今の時点で何かどんな説明をされるのかというのがもしあれば教えてください。そういう方々に対して、過剰に、実際どうなっちゃうのかなというのがちょっと心配なんですが、それはどういうふうに回収するのか。","respondent":"秋山資源循環推進課長","answer":"説明ですけれども、具体的には集団回収の団体の条例上の登録ということがありますので、それの内容の説明、それから登録の作業等がありますので、４月以降、順次団体の方に連絡をして説明、それから回収事業者に対しても同じような説明をしていくという予定です。","voiceIndex":66,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"集団回収ではない、行政回収のほうで、今、そちらは行政がどういう回収をしているのかということと、あと、例えば、区長に認められる指定された団体になりたいといった場合は、何かそういうルートというのはできているものなんですか。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"行政回収の業者ですけれども、今、品川のリサイクル組合のカムズというところが行政回収の資源回収をしておりますので、ここで区長、または区長から指定された者というのは、リサイクル協同組合のカムズというのを想定しています。そのときにトイレットペーパーを置いていったり、今は１円ぐらい払ったり、キロ１円ですね。というような努力をなさってきた、そういう非常に何といいますかね、努力してきた方々ですね。","voiceIndex":68,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"行政回収のほうはわかりました。集団回収のほうで、町会の方が直接回収してくれる業者と契約を結んで、今持っていってもらっているふうに伺っているんですけれども、区があっ旋とかしているんですかね。あっ旋業者というのは幾つぐらいあるんでしょう。","respondent":"秋山資源循環推進課長","answer":"現在のところ、集団回収の事業者ですけれども、４５社あります。","voiceIndex":71,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認させてください。今、古紙が出ている量は、区の中で把握している行政回収と集団回収でやって、それだけの数字ではないんですよね。それがこういう、持ち去りの業者によってどのぐらい抜かれているかというのを。","respondent":"島袋品川区清掃事務所長","answer":"今のところそれはちょっと把握しておりません。抜き取り業者がいるというので注意していますが、どのぐらいとられたというのはちょっと。申しわけありません。","voiceIndex":73,"id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"何件か持ち去りがあって、そこの判断が分かれているみたいなんですけれども、罰金でなくて、今回過料でやるという、その辺の考え方というのかな、犯罪ではないけれどもというところで、ちょっとその辺の過料にしたところをもう１回聞かせていただきたい。１点、路上に置いてあるもので、資源として置いてあるものはだれのものなのかという判断の根拠というのはどの辺にあるのか、ちょっと教えていただきたい。","respondent":"岩崎環境清掃事業部長","answer":"例えば８時ごろ、庁舎に下神明から歩いてきますと、必ず特定の業者が車に積んでいます。車で置いてあるところに来て、ぽんと積んで、また行って、また積んじゃうというので、歩くより速い程度ですね。というのは、しばしば目撃できるところです。","voiceIndex":79,"id":"exchange-031"},{"speaker":"飯沼副委員長","kind":"意見","question":"過料を課すというのはちょっとどうかなとよく思ったりもするんですけれども、今のお話を聞いて、やっぱり悪質なところを取り締まっていく部分では、本当に意識を高めていかなくてはいけないんだけれども、その過程においてはそういうルール違反というものの対応もあるのかなという感覚を持ちました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-032"},{"speaker":"渡辺委員","kind":"質問・要望","question":"自民党として賛成します。町会、自治会を初め、集団回収のことで会派のほうにも多数悪質業者対策の要望は多く伺っておりますので、区民要望に沿う形と、このタイミングというのも非常によろしいのかなということで、賛成でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"ホームレスの方々のお話というのもあって、今回悪質なということでご説明ありましたけれども、配慮を求めたいのと、あと、根本的には、また違う話かも知れないんですが、ホームレスの方々の実態に合った生活支援の前進も同時に必要だと考えております。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-034"},{"speaker":"稲川委員","kind":"質問・要望","question":"私は賛成です。７月１日から施行されるんですけれども、それを過ぎて以降は持ち去り行為が本当に減るように、逆に頑張っていただきたいと。町会の人たちの努力のたまものですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-035"}]},{"id":"topic-02","title":"平成２０年請願第１号、保険でも良い歯科医療ができるように求める請願","agenda":"平成２０年請願第１号、保険でも良い歯科医療ができるように求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"わからなければ構わないんですけれども、結構同様の趣旨の請願がかなり他自治体でも採択されていると思うんですが、それで意見書が上げられていると思うんですけれども、意見書が上がっているような自治体や、広がりなどについてちょっと、つかんでいるところがあれば教えていただきたいです。","respondent":"原国保年金課長","answer":"全部を把握しているわけではございませんけれども、ホームページ等で確認できる範囲ということで、今のところ９区ほどの状況をつかんでいるところです。不採択が１区、それから継続保留が５区、参考送付２区、意見書提出が１区というような状況をつかんでいるところです。","voiceIndex":95,"id":"exchange-036"},{"speaker":"安藤委員","kind":"意見","question":"区のほうは今ご紹介があったんですけれども、国立市とか、あるいは立川市などでも意見書が出ていたり、あるいは茨城の大洗町ですとか、群馬の前橋とかあって、昨年の夏時点では２７市町村で採択されているということですけれども、医療機関専門誌とかに紹介される形で広がっているのかなという認識がありますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-037"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"何かさらに求めているところもあるんですけれども、この辺の評価と、やはり検診の受診抑制というか、この辺が進んでいる中での進捗状況がどうなのかなというあたりはつかんでいらっしゃるんでしょうか。その辺をもし答えられたら。区民委員会なので、私もどうしようかなと思ったんですが。もしわかる範囲で。","respondent":"原国保年金課長","answer":"こういった広がりの中で、歯科の口腔の重要性、そういったものを実施しておりまして、今数字を申し上げましたが、平成１６年からの数字ですけれども、品川区といたしましては、平成８年度からそういった事業を展開して、表彰をしています。","voiceIndex":98,"id":"exchange-038"},{"speaker":"飯沼副委員長","kind":"質問","question":"私はびっくりしたんですが、現在、８０歳で８本前後の到達なんですって。診療報酬が極めて少なくなって大変であるという、そういった面で、歯科医師の５人に１人が年収３００万円以下、歯科技工士の３人に１人が２００万円以下といった、こういう状況で仕事をしているんだというのを見つけたんですが、その辺について、把握していらっしゃることを教えていただけたら。","respondent":"原国保年金課長","answer":"実態ですけれども、なかなか実態を把握するのは難しいところもありますが、１つの資料といたしまして、医療経済実態調査、これは診療報酬を改定する上での参考資料ということで中医協が使う資料になってあります。","voiceIndex":100,"id":"exchange-039"},{"speaker":"飯沼副委員長","kind":"質問","question":"やはりこの辺に今の大変さというのがあるんじゃないかなと思ったんですが、課長さんにばかり聞いていてもあれですが、せっかく区民の方からの請願なので、私はこの請願者の書かれている中身が、自分の調べた範囲ではもっともなんだな、大変なので何とか区民の皆さんが保険診療でいい治療を受けられるために、やっぱり国が動かなくてはいけないなと思って、この中身はもっともだと感じているんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"確認","question":"副委員長に答えるわけではないんですけれども、先ほどの他区で意見書が出されたというお話がありましたが、これはいつごろ出されたのか。というのは、先ほどお話をいただいた中で、中医協の答申が今年に出たわけですよね。するとそれ以前に出た意見書ですよね。そこら辺のところを、まず１点確認をさせてください。","respondent":"原国保年金課長","answer":"出されているのは平成１９年の４定で出されておりますので、そういった意味では今年の２月に出る前というところになってあります。","voiceIndex":103,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私たちもやはり、歯科医師とお会いすることはかなりあります。このような悩みも、お話を伺ったことはありますけれども、今の段階で中医協の答申が出てくる状況を待っていていいんじゃないかというお話を伺っております。中身ではなくて、まず表題部分。どうですか。答えられたら。","respondent":"原国保年金課長","answer":"基本的には国民皆保険の中で、健康保険というものが基本にあっての話ですので、その中でよりよい治療をということで、こういった診療報酬が２年に１回改定されているというふうに受けとめはしています。","voiceIndex":105,"id":"exchange-042"},{"speaker":"山路委員","kind":"質問・要望","question":"読ませていただいて、なるほどという面はあるんですけれども、歯科医師会全体の問題じゃないかなと思うんです。どうしても難しい問題だと、そういうことがあるんじゃないかと思うんですね。そういうことを考えますと、基本的に中身は、このようになっていただきたいということを思うんですけれども、この請願は歯科医師会全体ということかどうかわかりませんので、賛成しかねるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"この請願事項にある、よくかめる入れ歯の提供と、あと歯周病の治療管理が十分に保険の範囲でできるようになるということと、あと診療報酬で７３項目の２０年放置というか、据え置きという感じがありましたけれども、その診療報酬が上がるということ自体は、やはり今区が取り組んでいる９０１６とか、あるいは成人歯科検診というものをかなり細かくやっておられますけれども。","respondent":"原国保年金課長","answer":"診療報酬の改定につきましては、先ほど申し上げました中医協、こういったところでいろいろな情報を集めたり、あるいは国民の意見を聞いたり、委員の中には診療側、それから支払い側、公益を代表する、こういった方々の中で慎重に議論され、また。","voiceIndex":114,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、これは歯科医師会の総意ではないんですけれども、現状では、先ほど中医協の答申が出てくる中で、もう少しその状況、答申をちゃんと見きわめてから対処したほうがいいのではないかというお話を伺っております。ですから、自民党としては、状況をもう少し見計らってということで、不採択ということで考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-045"},{"speaker":"山路委員","kind":"意見","question":"先ほど言いましたように平成２０年度の改正案が出て、歯科医師会全体の問題としてどうかということだと思います。内容は確かにそうだと思います。内容は理解できるんですけれども、その取り扱いについては不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"やはりそういう前向きなというか、本当に待ったなしの状況なんだという、そういう前向きな改定となるためにも、いろいろなところからこういう自治体が歯科医療現場の実態を踏まえたような、変えてほしいという意見書を上げていくこと自体が、私はそういう前向きな改定にこれからどんどんつながっていくと思うので、賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-047"},{"speaker":"稲川委員","kind":"意見","question":"私は不採択です。先ほど山路委員の話にあったように、個人というか、どちらかというと歯科医師会という団体があるので、やはりそういうところから上がってくるものをしっかり研究していくべきだと思いますので、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-048"},{"speaker":"渡部委員","kind":"意見","question":"私も今回は不採択にしたいと考えています。それはやはり、この２月１３日の段階で中央社会保険医療協議会のほうから答申が出されております。先ほど説明の中にもありました、ほかの区からの意見書もそれなりに出ていたという中で、２月１３日の答申に少しは生かされているのではないのかなと、まず考えます。今回は時期尚早といいますか、タイミング的に考えても不採択でよろしいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":50376,"voices":135}},{"id":"h20-20080225-7","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"厚生委員会","time":"午前１０時０２分～午後５時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この階層を増やすことで区の増収分がどれぐらいになるのかということと、それから、あと１番目のところでは保育料負担が増加しないように配慮したということで書かれているんですけれども、それにもかかわらず、なぜ保育料が値上がりする人をつくったのかという、その値上げの理由と、それから、あとここのところには「子育て支援の充実に資する」ということで書かれているんですけれども。","respondent":"小林保育課長","answer":"大まかに３点のお尋ねかと思います。１点目の保育料階層区分の調整で、基本的に、所得が上がらなければ保育料は同一にするということでご説明をさせていただいたんですけれども、上がる人は間違いなくいないのかというお尋ねです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それともう１つは、次、３番目のところも聞きたいんですけれども、多子減額制度というのは、これは私たち共産党としても、条例提案も今まで行ってきたことで、今回も条例をもう一回出そうかなというふうなところで準備をしていたところが、区でこういう提案が出されてきたので条例は出さなかったんですけれども、そういうところでの対応でしたので多子減額制度というのは大歓迎なんですけれども。","respondent":"小林保育課長","answer":"１点目の階層を新設することによって期待される保育料ですけれども、現行の人数から試算いたしますと、１,２００万円前後の保育料が見込めます。それから２点目に定率減税の扱いなんですが、これはそもそも税制改正ないしは税源移譲の関係とは異なる視点からの問題かと思います。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１つ、これは今回の１番のところの階層区分の調整というのは税制改定によるものに対しての調整だと思うんですけれども、改定を行わなければ保育料は大幅に減収になってしまうための調整ということだと思うんですけれども、これは国の税制改定によるものなので、多分、ほかのところも全部、２３区もやっているんじゃないかなと思うんですけれども、２３区の税制改定による調整も含めて。","respondent":"小林保育課長","answer":"そうした中で、２３区の対応といたしましてはほとんどの区で何らかの対応は予定しております。ちなみに、聞いておりますところは、この４月に同じような趣旨で改定をする区は１２区前後あるやに状況を把握しています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１２区前後が４月から改定するということであれば、それ以外の１１区が改定しないということは何かすごい保育料が下がってしまうのかなと思うんですけれども、そういうわけではないんですか。","respondent":"小林保育課長","answer":"その他、保育料体系と一緒に飲み込んで考えたいので近々対応の方針を出しますと言っている区も確かに数区はありますが、基本的にはすべての区で何らかの対応を考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"３番目の多子減額制度の拡充ということで、少子化対策の大きな財政支援になると思うんだけれども、今言った他の自治体でここまでの減額制度をやっているようなところはあるのかどうか、品川区独自のアイデアとしてこういうふうに考えられたのかどうかを教えてください。","respondent":"小林保育課長","answer":"直近の状況把握では、改正前の品川区、階層に応じて３割、４割、５割の減額をしているという区が１５区ございまして、それを下回る区もあります。したがいまして、今回改正をして品川の水準に至るという区は、大田区を含めまして、そう多い数はございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"大田区を含めてそう多いことはないというのは、大田区もやっていますよということなのか、大田区も含めてそう多くないというのは、大田区もやっていないということなのか、だから品川区と、あと二、三区しかありませんよということなのか、その辺を教えてください。","respondent":"小林保育課長","answer":"大変失礼しました。今回、品川区がやりますと、この内容は、５割、１割は品川区と大田区だけです。ほかの１５区は従前の品川区と同じ程度で、今回の第１回定例会にはそれ以上の拡充の方向は出されてございません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"堺委員","kind":"質問","question":"それから２番目の場合、これも先ほど、今回、負担の適正化ということで、Ｄ２１が１６９名ですか、Ｄ２２が９２名、Ｄ２３の方が１６１名、合わせて４２２名でしょうか、こういう方々には新しくこういう形でご負担をいただくということなので、こういう方々は平年度化するとどの程度の区としての税収増になるのか、平成２０年度の場合は半年間経過措置として従来どおりということですから。","respondent":"小林保育課長","answer":"３点目の多子減額ですが、ご指摘いただきましたとおり、これを実施することによって平年度ベースで２,２００万円程度の保育料の減収となるという見込みです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"こういう大ざっぱな計算でいくと、そのまま調整しなかった部分、これはＤ階層の部分、そのままいくと１億４,０００万円の減収ですから、だけれどもＤ階層は２１から新しくやると、それが１,２００万円の増、ですから、この段階で、これで１億２,８００万円の減収ですかね。それでも、調整した後でも減収になってきはしないかなという気がするんですが、その辺はどう数字的に見込まれているんですか。","respondent":"小林保育課長","answer":"今は歳入のお話ですけれども、当然、それに際しまして、事業規模が拡大しますので、支出ももちろん増えてまいります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、何でもそうかと思います。だけれども、やっぱり限りある財源の中でやっていくとなると、場合によってはそれなりのご負担もしていただかなければいけないんだという考え方でいけば、私は今回の保育園の保育料の３点については十分理解ができると思っているんですが、それでも、こういう形にしたとしても、先ほどの課長のご説明でも、若干の減収があるんですよということでいいんですかね。","respondent":"小林保育課長","answer":"新たな弾力化云々という、その他の変動要因を別にすれば、残念ながら、保育料は今回の調整を行いましても減収となります。","voiceIndex":22,"id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ちょっと伺いたいんですけれども、今回３点の改定ということなんですけれども、保育料の収入全体としては何か先ほど微増だというお話だったと思うんですけれども、今回、Ｄ階層のところの改定、今回の見直しをやらなければ全体として１億４,０００万円の減収になると、それは税制改定の影響ですから、それをこういうふうにある意味では変わっていくというのは当然だという、その改定での影響というのは。","respondent":"小林保育課長","answer":"先ほどご説明させていただきましたが、税源移譲がされたと、何もやらなければ１億円から最大１億４,０００万円ぐらいの影響額が出て、その分、区は減収になってくると。ところがこれをご審議いただいた結果のとおり調整をしたとします。","voiceIndex":24,"id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"意見","question":"私がやっぱりよくわからないのは、Ｄ２２、Ｄ２３階層のところの新たな段階をつくるということなんですけれども、これは負担能力に応じたということの負担の適正化というふうなことなんですけれども、もう１つは子育て支援の充実、上のほうの１は保育料負担が増加しないように配慮したというふうになって、今、子育て支援が叫ばれている中で、区も保育料の増加にならないようにと言っているのにＤ２２。","respondent":"小林保育課長","answer":"他方、年齢によってもかなり違いますけれども、実際の保育にはできるだけ効率的、合理的な運営に努めておりますけれども、例えばゼロ歳児、一番高い場合には月５０万円前後の費用がかかっている、それに対して保育料を幾ら払っていただくかということを考えた場合。","voiceIndex":26,"id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"なんですけれども、今の説明のところでは、一定の収入のある人のところで負担ができるのであれば、そういう負担を求めていくんだということなんですけれども、私はそこのところがもうちょっと、なぜ今、１つは税制改定の中でも負担が上がらないように配慮した、全体の保育料の減額をしよう、負担を減らしていこう、そういう中で、何であえて今のこの２つの段階なのか。","respondent":"古川児童保健事業部長","answer":"加えますと、今、保育園の運営経費を１００といたしますと、利用者の負担は大体１２％弱です。ほとんど８２％が区の負担でございまして、これはとりもなおさず全区民が負担しているわけですので、そういった部分については当然理解がいただけるかと、こう考えております。","voiceIndex":28,"id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"今、１番目と３番目というのは、私はここのところは非常にわかるんです。ですけれども、ちょっとわからないのは、やっぱり２番目のＤ２２、Ｄ２３のところなんです。今、部長のところでは、全体の減収のバランスをこうやってとるんだと、そういうふうなお話があった。今の減収のバランスをとるということになると。そういうふうに見えるんだけれども、そこのところはどういうふうな説明なんでしょうか。","respondent":"古川児童保健事業部長","answer":"多子軽減をやった分を２番目のこの階層でとは毛頭考えてございません。つまり保育料が運営費全体にどう占めているかという問題は常に私どもは考えていかざるを得ないと思ってございまして、一定の収入をもって運用をしていくわけです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"須藤委員","kind":"意見","question":"それぞれ、保育料の改定にあたって、１、２、３と分けて整理をしていただきました。１番は当然そういう処置をしなきゃしようがないだろうと。それから３番目については、今、品川区、大田区ぐらいしかやりませんよという、大きくしっかりとした少子化対策の一環として一歩進めたということで、非常にこのことについては是といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"先ほど何点か質疑の中で確認をさせていただきましたが、我々が望むことは、なるべくなら負担増につながらない、これは大前提でして、それが一番いいと、これはそのとおりだろうと思うんですが、やはり今後の子育て支援という視点からとらえても、これからのさまざまな事業展開においても、必要なものはきちっと確保するということで進めていかざるを得ない、そういうふうに理解をするところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"これは、この値上げで１,２００万円ということですけれども、品川の財政力からすれば十分賄えるというふうなところも思いますし、それから適正な負担ということであれば、私は国の負担こそ求めるべきだと思いますし、もともと子育て支援の財政支出というのが日本はすごい少ない、ＯＥＣＤの中でも３０カ国中２６番目というところですので、子育て支援にはもっと増やすべきだというときに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-016"},{"speaker":"本間委員","kind":"質問・要望","question":"結論を言いますと、総じて、それぞれ１、２、３ともよく理解できます。それから３番目は、子育て支援の１つとして、今、大変子育て支援、子育て支援ということで、さまざまな角度からいろいろな区民からの要望が出ている中で、多子世帯に対する手だて、経済的負担を和らげていくというふうな部分は、これも大変よいことだなと思います。総じて、この保育園保育料につきましては賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-017"},{"speaker":"高橋委員","kind":"質問・要望","question":"この１７号議案に関して賛成です。１つだけ、多子減額制度がこの先、もう少し進んでいくといいと思いますので、要望だけです。","respondent":"松澤委員長、上山介護保険担当課長","answer":"これより第１７号議案、品川区保育の実施等に関する条例の一部を改正する条例について、採決をいたします。本案は、挙手により採決をいたします。賛成多数です。よって、第１７号議案、品川区保育の実施等に関する条例の一部を改正する条例については可決いたしました。説明資料の下のほうになりますが、施行期日は平成２０年４月１日とし、最後のその他ですが、平成２０年度の保険料と関連し。","voiceIndex":37,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば平成１８年度に戻すとか、そういうことはできないのか、そこの中身を１つ教えていただきたいのと、あとは第４段階の経過措置の方が２段階あって、第５段階の経過措置の方が３段階ありますけれども、この５つの段階のそれぞれの人数を教えていただきたいのと、今回、本来であれば平成２０年度の保険料になるのが平成１９年度のまま据え置くことによって、保険料の減収分というのがどれくらいになるのか。","respondent":"上山介護保険担当課長","answer":"これに伴う減収の見込み額になりますけれども、約４,２００万円を推計しています。その理由ですけれども、今回、税制改正の影響を受けた方につきましては、介護保険制度といたしまして、弾力的な運営に努めたです。政令ですけれども、平成１９年度と同額です。","voiceIndex":43,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、品川区がそれを実施に移して据え置いたというところでは、高齢者の所得の少ない人への配慮が必要だというふうなことで判断したということなのか、そこのところを１つ確認をさせていただきたいと思います。それともう１つは、こういう政令が出て、２３区の他の自治体がどういう措置をとったのかということがわかったら、その点についてもお聞かせいただきたいと思います。","respondent":"上山介護保険担当課長","answer":"他区の状況ですけれども、昨年の秋の状況ですが、その時点で経過措置を継続するというところではっきり意思を示している区が約半分ございまして、その残りの半分につきましては未定というような状況です。","voiceIndex":45,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それともう１つ、ここのところで、その他のところで、減額制度の対象者の拡大というふうなところで、これも共産党は前から条例提案もして提案をしてきたので、拡大ということに対してはすべきだと思っているところなんですけれども、９６万円から１２０万円に改めた、その１２０万円の根拠と、それから、なぜ９６万円から１２０万円に拡大をしようとしたのかということと、あとこれが広がることで。","respondent":"上山介護保険担当課長","answer":"今回、第三期の介護保険料を設定するにあたりましては、新たに第２段階ということで、これまでの低所得者の方に対する保険料設定をするとともに、今回、区独自の減額制度につきましても、今お示ししているように。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そこを１つ教えていただきたいのと、あとは私たちがこれを提案したときも、賃貸住宅にお住まいの方と持ち家の方では、おのずと住宅費にかかる費用というのが大きく変わってくるので、住宅費も生活保護基準並みの住宅費というのを賃貸住宅の方は認めるべきだと提案をしていたんですけれども、ぜひそういうふうにもしていただきたいと思うんですけれども、そこの考え方はいかがでしょうか。","respondent":"上山介護保険担当課長","answer":"１点目の後期高齢者医療制度の施行ということで申し上げましたけれども、制度の施行に伴いまして、高齢者にも保険料等の負担が生じるということを視野に入れているです。他区の状況ですけれども、特例減額といたしまして実施している区が１８区ほどあるです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは要望ですけれども、これは１２０万円に９６万円から拡大をされたというのは一歩前進というふうなことで評価はするものですが、他区はもっともっと拡大をしているという状況が大きくありますので、他区の状況も踏まえて、ぜひさらに拡大をしていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"２０億円も基金に、去年のあれから見ると２０億円ですよ。これは、積み立てが６５歳以上１人あたり３万円でしょう。私はもっと、今、後期高齢者医療制度も入って負担増になると、そういうことへの配慮ということであれば、もっと本当に配慮してほしい。これではちょっと住民への説明も、本当に情けないなと思います。強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-024"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合における決定事項","agenda":"東京都後期高齢者医療広域連合における決定事項","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかし、これが今度、７５歳以上の高齢者の１万５,０００円以上の人から、相手の生活状況を考えずに天引きという形になってしまうわけですから、相談の機会が奪われるということになると思うんですよね。国民健康保険でも滞納者がかなり多いので、そういうところは、区としてはそういう状況になる心配に対してどういうふうに対応しようとしているのかということを一つお聞かせいただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"それもさらに、また広域連合でも同じような合議体をつくりましてそれで決まっていくように、何段階も経て、慎重に対応されるものと考えておりますので、今、ご指摘のようなものについては、機械的にこういうものを適用していくものではないというふうに考えているところです。","voiceIndex":59,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だけど、来る機会がなくなっちゃうわけですね。ですから、９割近い人が病院に通院しているわけですよ。品川区でも、高齢者には資格証明書を出しませんというふうに、事務とか、いろいろな作業を考えると、悪質な人というのはこれしかいないわけですから、逆に非効率じゃないかと思いますし、資格証明書や短期証を出すことによって収納率が上がったという実績は国民健康保険でもないんですよね。","respondent":"冨岡高齢事業課長","answer":"１点目の年金からの天引きの件ですけれども、結果的にとられる場合があるかもわかりませんけれども、徴収猶予にその時期までさかのぼって該当していれば、事務的な細かいことはこれから確認しなければなりませんが、例えばその部分はお返しするとか。","voiceIndex":61,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、広域連合の減免制度、今回は減額されたということもありますけれども、それに加えて、各自治体で保険料の減免制度を、介護保険でも先ほど減免制度拡大の報告がありましたけれども、そういう形で、自治体独自の減免制度というのをぜひつくれないものかと思うんですが、これに対してはいかがでしょうか。","respondent":"冨岡高齢事業課長","answer":"そういうことから考えますと、最終的には１００億円近くの一般財源を投入して、当初２０８万円、その後２０１万円というふうに厚生年金の平均のあれが変わりましたけれども、７万４,０００円だったというところが、今、最終的には５万３,８００円ということで。","voiceIndex":63,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２.２倍から１.６４倍に軽減しましたと言っても、１倍からすると１.６４倍ですから、３万２,０００円が５万３,０００円になってしまうわけですから、これはほんとうに大変な値上げだと思うんです。それで住民税と所得税はゼロだったのが、両方合わせて５万円ぐらいの負担増になっているんですよ。そういうところにぜひ心を寄せて、区としての減免制度もご検討いただきたいというふうに思います。","respondent":"木下福祉高齢事業部長","answer":"それで、広域連合の方で昨年の夏にアンケート調査をしたということを申し上げたと思いますけれども、その中で、１割負担でいいんではないかという方が、これは７５歳以上の方が答えていますが、６１.２％です。","voiceIndex":65,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、私たち現役世代の人だって保険料はみんな払っていますけど、それは高齢者になったら病気をするのは当たり前ですから、病気をするのが当たり前の高齢者になったときに、安心してかかれる医療をつくってほしいというのが、現役世代の私たちの願いでもあるわけですよね。だから、そういうところで言えば、減免制度についてはこれからの課題というふうなところでもご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、相当いろいろなところでこの制度についての説明をしっかりしていただくということを、まずもってお願いしたいと思います。","respondent":"冨岡高齢事業課長","answer":"もちろん丁寧な説明を心がけてまいりますし、制度がスタートしましても、今回、納めていただくのは７月になるかと思いますが、それまでにつきましても、さらに周知に努めてまいりたいと思っているところです。","voiceIndex":68,"id":"exchange-030"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほどもご説明いただいたんですが、ちょっと申しわけないんですが、こちらでいいんでしょうか。そこの米印ですか、「保険料の均等割軽減については、二人世帯（ともに被保険者）を想定して算出した」。この一連のことについて、先ほどちょっと聞いたような気がするんですが、よく理解できなかったので、重ねてもう１回、ご説明をいただきたい。","respondent":"冨岡高齢事業課長","answer":"先ほどにつきましては簡略な説明でございましたので、さらにもう一度説明をします。この表につきましては、今回の低所得者軽減を講じる前の保険料と、旧ただし書き所得５５万円の階層まで、今回の４段階の所得割保険料の軽減を減じた場合の比較が出ております。","voiceIndex":70,"id":"exchange-031"},{"speaker":"堺委員","kind":"質問・要望","question":"同じ説明を２度していただいて申しわけありません。同じ説明だったのかもしれませんが。要するに、こういう４段階の方々という言い方でいいんでしょうか。一番右の方には、差ということで、一番上が金額的に４,９２０円のマイナス、その次が８,６１０円のマイナス。それで、住民説明会については、２９日から始まって６回のようなんですが、これで今回はしようがないという形になるんでしょうか。","respondent":"冨岡高齢事業課長","answer":"それに際しては、さらにご理解をいただけるよう、丁寧な説明に務めてまいる所存です。","voiceIndex":72,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、１枚目のところで、葬祭費の支給ということで、これは前から、国民健康保険と同じように、今までどおり出す方向で検討するというふうにご答弁いただいていたと思うんですけれども、これは今までどおり、７万円の支給ということでいいんでしょうかという確認をさせていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"とにかくまず、「こういう制度です」ということで、わかりやすいプリントを、資料を用意させていただいて、丁寧に説明をしてまいりたいと考えています。","voiceIndex":74,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つすごく心配しているのが、２月始めに突然、血圧を下げる薬、インシュリンの注射または血糖を下げる薬、コレステロールを下げる薬のどれかを使用しているかを質問して、一つでも該当する場合は、その健診から除いてもらうという指示が厚生労働省の方から出たというのが新聞報道であったんですけれども、これについてはどうなっていくのかということについても教えていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"この前厚生労働省の記事が出た件ですけれども、厚生労働省では、たしか２月の説明会で、厚生労働省の見解として、「健診の目的が糖尿病等の生活習慣病の早期発見や重症化予防であって、治療中の方については必要性が薄く、必要な検査は治療の一環として行われているために。","voiceIndex":76,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そういうので７４歳までは健診を受けられるのに、７５歳になったとたんに「血圧の薬を飲んでいるから」ということで健診が受けられないということになると、いろいろなところでほかの病気を見落とす危険にもつながっていくし、早期発見とか予防にも逆行するので、これは突然出てきたという感じがするんですけど、これに対しては自治体の方からも。","respondent":"冨岡高齢事業課長","answer":"次年度以降につきましては、これは、国、それから広域連合から我々に委託をされている事業に、こちらでさらに特別に対応している部分ですので、総合的に考えながら進めてまいりたいと考えています。","voiceIndex":78,"id":"exchange-035"},{"speaker":"宮崎副委員長","kind":"質問","question":"新聞、あるいはテレビでは、例えば終末期の医療のところで過剰診療しないようにという確約をとると、医療機関に高く診療報酬が払われるとか、そういう報道なんかもあったりして、医療の中身自体が、年寄りは医療を受けるなというような印象を受ける報道もあるんですが、そこら辺のところは、行政の方は今、どういう認識になっているんでしょうか。","respondent":"冨岡高齢事業課長、木下福祉高齢事業部長","answer":"表現が適切だったかどうか、５００円という形で、広域連合では自己負担金という形で決めております。区につきましては、負担をいただかないという方向です。後期高齢者医療制度の診療報酬については、いつも診療報酬の告示は３月の下旬だったと思いますけれども、最終的にはそこで確定になろうかと思いますが、高齢者の疾病状況に着目した診療報酬のあり方というのを検討していまして、一つは。","voiceIndex":80,"id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"先ほど鈴木ひろ子委員の方から、健康診査のところは、例えば高血圧とか糖尿病とかを治療していると受けられなくなるという動きなんだという指摘があったんですけれども、この説明資料のところでは、健康診査事業約１０億円というふうになっているんですが、これはさっきも指摘があった、おそらく高血圧、糖尿病だけで半数以上の方が治療を受けているだろうと思うんですけれども。","respondent":"木下福祉高齢事業部長","answer":"特に、平成２１年度になりますと、国保連合会のレセプトと突合せができるように制度上はなる予定なんですが、そうなってきますと、その部分については把握ができるようになるということです。","voiceIndex":83,"id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"質問","question":"今、国の方の考え方が明確に出てきた、そういうところで、区あるいは広域連合をどうするかというところが問われてくると思うんですけれども、そこのところの区側の考え方を改めて聞いておきたいと思います。大変だというふうに言いながら何で考えないのか。そこのところが全くわからないんですけれども、どうでしょうか。","respondent":"木下福祉高齢事業部長","answer":"保険料の方の、品川独自の減免についての考え方でありますけれども、まず、今回の高齢者を中心とした医療制度改革というのは、世代間の公平も踏まえながら、医療制度を将来にわたって堅持していく、そういう大事な改革でありまして、その中では。","voiceIndex":85,"id":"exchange-038"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"それと、健診の方は、国の方の考え方が出てきておりますけれども、それを受けて自治体がどうするかというのが、今、問われると思うので、このところはしっかり受けられる体制を、例えば、血圧なり、糖尿病なり治療をしていれば、そういう角度での健診というのはあるんですけど、健康診査というのは全体にやるわけですから、そういう病気の角度からの検査だけじゃなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-039"},{"speaker":"須藤委員","kind":"意見","question":"先ほどもお話ししましたけれども、４月から始まる後期高齢者の条例制定、しっかり各自治体やっていかなきゃならないのは当然だと思います。それから規約についても先ほどお話ししましたとおりです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"第１９号議案に対しては反対です。７５歳以上の人を差別していくんだという医療制度が、この後期高齢者医療制度ですから、戦争時代を苦労してくぐり抜けて、戦後の焼け野原から日本を築いてきたこの高齢者、７５歳になったら差別をするという医療制度に対しては、共産党は４月からの実施を中止させて、制度そのものを撤回すべきだと思っているところですので、今回の条例に対しても反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-041"},{"speaker":"本間委員","kind":"質問・要望","question":"新しい大きな医療制度改革に伴う制度ですから、これにつきましては対象者も７５歳以上というようなこともありますので、十分な配慮をしながら説明、周知に尽くしていただきたい。元気な方もいらっしゃるし、いろいろな方もいるわけですが、老婆心ながらといいますか、そんなことの中で丁寧に、繰り返し繰り返し、理解、納得していただくようなことをお願いしたいということをもって、第１９号議案は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-042"},{"speaker":"高橋委員","kind":"意見","question":"第１９号議案と第２６号議案に賛成をいたします。一つだけ、住民説明会で、もしうまく予定等が合いましたら、これには八潮が入っていないので、高齢の方がいらっしゃって、遠くまで行けないので、八潮や南大井の方で開けるなら、お願いできればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-043"},{"speaker":"須藤委員","kind":"質問","question":"このこと自体は、東京都ときちんと交通整理ができて、方向性ができたかなという思いがあって、今まで各ブロックでいろいろ決められたこともそのまま流れていきますよというようなお話なんですが、そういった東京都といろいろ協定を持ってきて、区としてよかったよという点、それから財源的には東京都と区とどういうふうになっていくのかなと、そのあたりを教えてください。","respondent":"志村生活福祉課長","answer":"長々ご説明したとおり、路上生活者の対策につきましては、１区だけ、あるいは城南ブロックだけというわけにはまいりません。","voiceIndex":105,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり私もこの路上生活者の対策事業ができて改善されているんだろうなと、相談を受けた方でもここにつながって自立された方もおりますし、そういう点では評価されるんじゃないかと思うんですけれども、改めてこの緊急一時保護センターと自立支援センター、この制度を使ってどれくらいの方が自立できていったのか、また生活保護になった方というのもいらっしゃるのではないかと思うんですけれども。","respondent":"志村生活福祉課長","answer":"これは１２月から１月の間、いわゆる年末年始対策を行いましたので、厳冬期対策と言っていますけれども、ここでいつもの方よりは余分にその需要がありましたので、定員の枠内では行ってありますけれども、現在はその方の対応が終わりましたので、今、稼働率につきましては。","voiceIndex":109,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとインターネットで、新宿野宿労働者の生活・就労保障を求める連絡会議という、ホームレスの方たちを支援している方たちの去年の路上生活者対策に関する要望書というのを見たんですけれども、そこの中でも、やっぱり縮小するというのは問題なんじゃないかというのが書かれていて、特にこの寒いときにすごく大変だというのが書かれていて、この調査の中でも、いろいろな声が書かれていて。","respondent":"志村生活福祉課長","answer":"先ほどご説明したとおり、この同じ施設の中で、同じ担当員によりまして緊急一時保護、それから自立支援ということでありますので、例えばＡさんはこの２５人枠の緊急にいるんですけれども、それが例えば１週間で体力の回復、あるいは１週間で求職活動ができるとなりますと。","voiceIndex":111,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、予算が３３億円から１９億円に圧縮するということなんですけど、やっぱり貧困が拡大しているところで、予算を圧縮するのではなくて、しっかりかけて、減らすんじゃなくて、必要な対応がそのまま、必要なところは継続し、拡大するところは拡大するということを含めて、予算の圧縮というところにシフトして縮小させていくというのはどうかなと思うんですけど、いかがでしょうか。","respondent":"志村生活福祉課長","answer":"すみません、ちょっと私の説明が足りなくて申しわけありませんでした。地域生活移行支援事業は、平成１９年度で新たな、いわゆる新規の方についての展開はもうしませんということなんです。","voiceIndex":113,"id":"exchange-047"},{"speaker":"宮崎副委員長","kind":"意見","question":"今回の変更の理由は路上生活者の実態が変化したから、この変化に見合って、改正するんだという説明なんですけれども、路上生活者の数の変化がここにも書いてあるんですけれども、平成１１年が５,７００人、平成１９年が３,１００人ということなんですけれども、先ほど指摘があったんですけれども、いわゆるネットカフェ難民というのが非常に増えてきて、以前はいわゆるホームレスになると。","respondent":"志村生活福祉課長","answer":"ネットカフェ難民と言われております方々につきましては、ちょっと私もいろいろな会合等でお聞きした話ですと、一応就労の形態はとれていると理解しています。それで例えばアパートに入るための敷金、頭金等がなかなか工面できない。","voiceIndex":115,"id":"exchange-048"},{"speaker":"宮崎副委員長","kind":"確認","question":"そこのところを確認したいんですけれども、そうするとやっぱり結局、今いわゆる貧困、ホームレスの実態が変わってきていると、そういう中に、行政側がなかなか実態に対応できていないのかなという心配もあるんですけれども、改めて今の東京都のほうがやっているという中身がもうちょっとわかれば、どんな実態でやっているのか。わからないんです。","respondent":"志村生活福祉課長","answer":"あるいは例えば私ども窓口で、そうした民間の宿泊施設等ご紹介すれば済むべきものなのか。これを私どもが窓口の対応する中で判断をする、あるいはそうしたことに対するお答えを出していくというものであろうと思ってあります。","voiceIndex":117,"id":"exchange-049"},{"speaker":"宮崎副委員長","kind":"意見","question":"要するにネットカフェ難民の対策、現状がどうなっていて、その対策がどうなっているのかというのが全然わからないところで、何かこの路上生活がこうなっているからということで言うと、切り縮めていくというのが非常に心配だなと感じました。感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回の新しいシステムへの移行というのは、予算そのものも３分の２以下に減らすという中身ですし、人数が見た目では減ったとはいえ、新たなホームレスが増えている中で、貧困が大きく広がっている中で、人数も減らし、それから特に私はこの借上げアパートの３００戸を今使っている人は続けるということですけど、新規の方というのがかなりの需要があるのではないかと思うんですが、これそのものをなくして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-051"}]},{"id":"topic-03","title":"平成２０年請願第２号、介護保険の改善を求める請願","agenda":"平成２０年請願第２号、介護保険の改善を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この請願ではまず第１が特別養護老人ホームを増設してくださいという請願項目ですけれども、この特別養護老人ホームに関しては、私も何度も取り上げてきましたけれども、去年の１１月までは特別養護老人ホームの整備は完了したという答弁だったんですけれども、長期基本計画の中で整備については検討するとなったことは、本当に一歩前進だと思うんですけれども、私は１日も早く増設してほしい。","respondent":"蓼沼高齢福祉課長","answer":"ですから、入所基準につきましても在宅介護の困難性というものが１つのポイントをつける要素になっておりまして、それに施設の方が準ずるということになっております。おおむね言えることですけれども、例えば昨年の９月の入所調整会議の時点では、在宅の方が１４９人おられます。","voiceIndex":132,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、課長が言われたのは、在宅の方が優先ということで、在宅で、要介護３以上で、９０歳以上、８５歳以上、８０代の前半の方でも要介護度が高かったら、在宅であればほかの困難性とかがつけば入れる場合もあるという感じでイメージしていいでしょうか。半年間で入れた人がいるのかどうか。いるのであれば、何人入れているのか、このことを教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"ちょっと今のご質問に具体的に対応する資料を持ち合わせておりませんけれども、先ほど申し上げました平成１８年度の１年間で、特別養護老人ホームに入所された区内の方が１２０人強いらっしゃいますけれども、その内訳を申し上げますと、在宅が約８０人、病院の方が１６人。","voiceIndex":134,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この方も自宅で何年も介護を続けて、１００歳の方の息子さんですから、息子さんも７０代になるわけですが、それで息子さん自身が脳梗塞で半身麻痺でありながら、奥さんと一緒に介護を続けてきたんだけれども、自分の体調ももう介護は続けられないということで、この方も病院に入院をしたわけですけれども、長い間、ずうっと自宅で介護を続けて、もう限界だということで。","respondent":"蓼沼高齢福祉課長","answer":"ただ施設に入っていることだけで、全く入所ができないのかということでもありません。総合的な要介護度、年齢、あるいは在宅介護の期間等を含めまして、総合的に判定をしています。","voiceIndex":136,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、見直しの中ではこの介護の困難性というのは、入院していようがいまいが、２０点がつくということになるということでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"今、いろいろご指摘があったような点につきましては、では、いつまでたっても老人保健施設等の施設に入っている者は入所できないのかというような声もありましたので、そういった点も加味して、今見直しをしていますけれども。","voiceIndex":138,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はここのところはどうしても認識を変えていただかないと、本当に私は涙を流している人があふれていると思うんです。病院に入院している人は１１３人、老人保健施設の人は１４８人。要介護５であっても、９０歳を超えないと入れない。これが実態なんですね。こういうことでも、この人たちが必要でないというふうに言い切れるのかどうかというのを私は改めてお聞きしたいと思います。いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"しかし今、委員のご指摘が再三ありましたような点も含めて、もう少しそういった施設に入っている方にも一定の配慮ができないものかということで、見直しを進めているところです。","voiceIndex":140,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとケアホーム西五反田は２５万円から３０万円の利用料ですけれども、原小学校の跡地はそれよりももっとみんなに納得していただける値段にしたいということで、１６万円から２０万円ということで言われていますけれども、これはなぜケアホーム西五反田と違う値段にしたのか。なぜ下げたのかということと、２点お聞かせください。","respondent":"蓼沼高齢福祉課長","answer":"ケアホームにつきましては今現在、西五反田があって、原小学校跡と都南病院の跡の整備が予定されております。今後につきましては、本会議でもご答弁申し上げましたように、ケアホームも含めて今後長期基本計画の中であわせて検討していく予定です。","voiceIndex":142,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、原小学校跡は小学校の跡ということで、建設コストもかからないということで、１６万円から２０万円に下げられるということで、建設コストの関係でそういう値段に抑えられると考えていいんですか。","respondent":"蓼沼高齢福祉課長","answer":"それから都南病院跡地につきましては、今利用料等については詰めているところですけれども、ここにつきましても、区立施設ですけれども、運営事業者のほうにも一定の負担をしていただくということで、そういった中で利用料につきましてはできるだけ低廉にということで。","voiceIndex":144,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、人の配置はケアホーム西五反田と原小学校跡では、原小学校跡のほうが人の配置が少ないと、そういうふうに考えていいんでしょうか。だけど、実際は西五反田のケアホームは第３次募集でやっと集まったというのが実態だと思うんです。そういう方針というのは、どうしても納得がいかないんですけれども、そこら辺のところを改めてご説明いただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そういう意味では、今後もそのような特別養護老人ホームも、今回の長期基本計画の見直しの中で十分検討しますけれども、やはり多様なニーズがあるということは確かでありますので、このケアホームの部分についても引き続き。","voiceIndex":146,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私はお金の払える人にとっては選択肢として並んでいるというふうに見えるかもしれないんですけれども、この１６万円から２０万円が払えない人にとってみれば、やっぱり特別養護老人ホームしかないということになるので、国民年金しかもらっていなくて、生活がぎりぎりの人にとっては、選択肢として並んでいると部長が言われても、そういうふうには全然見えなくて、特別養護老人ホームしか選べないんですよね。","respondent":"蓼沼高齢福祉課長","answer":"そういう意味では部長が申し上げましたように、幅広くいろいろな選択肢を用意しているということですので、割合で申し上げますと、今現在もベッド数では特別養護老人ホームが７割ぐらい占めているわけですから。","voiceIndex":148,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"グループホームと特別養護老人ホームというのは種類が違うので、多様なニーズということになると思うんですけど、ケアホームというのは基本的に特別養護老人ホームに代わる施設というふうに区が説明してきたとおり、そこで違うというのは利用料の問題ですから、選択肢、選択肢と言われますけど、お金のない人には選択肢に入らないんですよ。選択肢にはならない。それでも選択肢と言えるんですか。","respondent":"蓼沼高齢福祉課長","answer":"これが現実だと思います。そういった意味では、特別養護老人ホームも含めて、さまざまなサービスの提供を区としてはいろいろな区民の声があるわけですから、ニーズにこたえていく必要があると考えております。","voiceIndex":150,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私は３０人しか待っていないケアホームを７１人分つくり、さらにこれからも計画していくと。４００人待っている、だれでもが入れる特別養護老人ホームは、１０年、２０年のスパンでしかつくらないと。これは明らかにお金のある人にだけ優遇する施策であって、これは自治体としてやるべきものではないと思います。とりあえず、一たん終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-062"},{"speaker":"須藤委員","kind":"質問","question":"ですから、先ほどの選択肢があるというお話ですけれども、いろいろな区民のニーズを見ながら、それから保険料をいかに理解できる費用というか、保険料にセットしておくということも大切だろうと思うんですが、こういった特別養護老人ホーム、いわゆる施設をつくっていくことで、その保険料に影響するのかどうかということを１つ聞きたい。","respondent":"蓼沼高齢福祉課長","answer":"いずれにいたしましても、そういう施設整備あるいはサービスの充実、それと保険料の負担、そういったことも含めて、今後、１つには区の長期基本計画の検討がありますし、平成２１年度からは介護保険事業計画の第四期に入りますので、この第四期事業計画の策定に当たっても。","voiceIndex":153,"id":"exchange-063"},{"speaker":"須藤委員","kind":"質問・要望","question":"本当に今お話があったように、基本構想を今度の議会でも出されていますけれども、それが１つの少子化、高齢化という、あるいは情報化、いろいろな社会情勢の変化に伴って、基本構想を新たにつくられていくと。先ほどお話を伺うと、福祉用具も医師の判断によって対応という形もとられるというようなお話がありました。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-064"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"それはそれで当然だと思うんですけれども、私はそういうことをするのであれば、まず数を増やさないと、こっちのほうを増やすと、こっちのほうが割を食っちゃうというふうになると思うんですけれども、例えば在宅の場合ですと、これまで区の説明は、在宅が困難になったら入所の見通しが持てるようにするということをよく説明するんですけれども、今のお話でいくと、数を増やさないと。","respondent":"蓼沼高齢福祉課長","answer":"そこで、施設サービスが開始されれば、それが保険料にはね返るということはあるわけですけれども、これは今までも言われてきておりますけれども、いわゆる施設と在宅と比較すると、施設サービスのほうが保険料にはね返る割合が大きいということが言われておりまして。","voiceIndex":156,"id":"exchange-065"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"原小学校跡のところは、先ほどそういう説明があって、施設をつくれば保険料にはね返るという説明であれば、そこのところは、今細かいことは手元にないということであれば、やっぱり大ざっぱなそういう試算をやったんじゃないですか、今、頭の中にあるものでも出していただきたいと思います。それとも無理やりあけるということになるんですか。","respondent":"木下福祉高齢事業部長","answer":"小規模多機能居宅介護もちょうど在宅と施設の中間的なものでありますし、夜間対応型訪問介護というサービスも品川区は始めておりますので、これらもトータルで見ていただきながら、なるべく在宅で支援をしながら、介護が困難になったら施設入所。","voiceIndex":158,"id":"exchange-066"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"こっちが増えるのが当然じゃないですか。介護保険特別会計だけですよ、それで３億円の貯金積み増し。在宅が困難になったら入所の見通しが持てると、ずっと言うんですけど、それだったら在宅が困難になったらというのはどういう基準なんですか。相変わらず、私は今、施設の方が入りやすくするとかいろいろあったけど、やっぱり数を増やしていくことなしに解決できないと思うんですけれども、どうでしょうか。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホームを含めまして、今回の長期基本計画の中で、これは施設が幾らあっても、きっと供給が、手を挙げる方を増やしていくという現象はあり得るんだと思いますが、やはり一定の安心感を引き続き持っていただくためには。","voiceIndex":160,"id":"exchange-067"},{"speaker":"宮崎副委員長","kind":"提案","question":"財政がこれだけ１年間で。これから長期基本計画の議論にしますというのではなくて、必要だと思うんだったら、いつぐらい、そういうことをしっかり区として責任を持って提案すべきじゃないですか。それともう１つ、先ほどの在宅が困難になったらと言うけど、じゃ、これは一体だれがどういうふうに決めるんですか。在宅が困難になったらなんて、だれがどういう基準で判断するんですか。どうでしょうか。","respondent":"木下福祉高齢事業部長","answer":"もう１つ、入所調整会議を経ることによって、第三者の判断を加えることによって、それを客観性を担保しようということでありますから、あいまいということではなくて、ご本人、家族の意向を踏まえたことをベースに判断をしているということであります。","voiceIndex":162,"id":"exchange-068"},{"speaker":"宮崎副委員長","kind":"質問","question":"実際に入れないんだから。入所待ち４００人待っていますとなったら、今言っている話、土台から狂っちゃうんですよ。ちょっと最後に２点聞きたいんですけれども、１つはやっぱり原小学校跡は低廉にという説明がありました。西五反田のケアホームは月２５万円から３０万円かかると、これに対して低廉にと言いました。低廉にと言うんだったら、一体だれを焦点に当てた考え方なんですか。どうでしょうか。","respondent":"木下福祉高齢事業部長","answer":"それからもう一方で、やはり国民年金クラスの方も当然おられるわけでありまして、そのことで随分誤解をされておっしゃってましたけれども、十分認識をしているわけでありまして、それはまさに介護の世界でもセーフティネットということは当然あると思うんですね。","voiceIndex":164,"id":"exchange-069"},{"speaker":"宮崎副委員長","kind":"意見","question":"最後になりますけれども、やっぱり今、品川区の介護制度というのは収入の少ない人の顔を見ていないなという感じがします。さっきも言ったけども、答弁がないんですけれども、私は長期基本計画の議論待ちじゃなくて、やっぱり必要だと考えるんだったら、私は区の考えとして、いつごろ、どのぐらいの規模でつくるのか、この場合、早く区の考えを出すべきじゃないかと思います。これを言いたいと思います。","respondent":"山田副区長","answer":"ご指摘いただいている、いわゆる所得に着目をしたところの新型特別養護老人ホームというご提案については、これも含めて、今後の長期基本計画の検討の中で私どもは、これは当然場所もあります、財源もあります、等を含めて。","voiceIndex":167,"id":"exchange-070"},{"speaker":"堺委員","kind":"質問","question":"あらかた自分なりに理解はできてきたつもりでいたんですが、何点か基金の件でお話が出ておりましたので、もう１回くどくなっちゃうかもしれませんが、私自身が理解するために、基金のもののとらえ方というんですか、考え方というんですか。私自身は基金は否定しない立場です。その辺のところもう１回ちょっと教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"どのくらい基金として積んでおくのが額としていいのかどうかというのは、保険者のほうの判断になりますけれども、別に明確な額の基準はございませんが、やはり保険制度の安定的運用ということを考えながら、あるいはサービスの量の見込みというものを考えて。","voiceIndex":169,"id":"exchange-071"},{"speaker":"堺委員","kind":"確認","question":"もう１点、ちょっと今のご説明の中で確認させていただきましょうか。第三期ですか、平成１８年度、平成１９年度、平成２０年度、このときは取り崩す予定だったけれども、制度改正に伴って、給付が抑えられたから取り崩さなくてよくなったんだと、たしかおっしゃったかな。今、そうメモしてあるんですが、その辺もうちょっと具体的に教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"ただいま第三期の事業計画が動いておりますけれども、この事業計画におきますサービス量の見込みからして、保険料の設定をしたときに、保険料を一定程度低く抑えようということで。","voiceIndex":171,"id":"exchange-072"},{"speaker":"堺委員","kind":"質問","question":"そうすると今、平成１９年度、平成２０年度のあと１年間ありますね。その辺と、それからもう１つ、第四期には基金の運用について、これは保険者の判断によると、考え方によると。効果的な運用ということですと、例えば今回は積み立てるけれども、第四期になると、これも当然状況の変化によるんでしょうが、取り崩しということも、それはあり得るということなんですか。","respondent":"蓼沼高齢福祉課長","answer":"ですから、いずれにいたしましても、今日もいろいろサービスの整備について出ましたけれども、事業計画でのサービスの量の計画と、それに伴う給付の見込みによって保険料も設定し、基金についてもどれぐらい取り崩して。","voiceIndex":173,"id":"exchange-073"},{"speaker":"堺委員","kind":"質問","question":"冒頭、私も申し上げましたように、基金というのはやっぱり始めた事業が、継続性といいましょうか、そういうためにある一定の基金を確保しておいて、担保しておいて、その事業のサービス低下につながらないように安定的な事業あるいはサービスが提供できるようにということで必要なんだと、私は理解しているんですが、今お答えいただいた方向性もそういうふうにお答えいただいたように理解をしているんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも入院をしちゃったときに、もう紙おむつは必要であるにもかかわらず、それが使えないということになって、在宅でいるのであれば、そのまま紙おむつは支給せざるを得ないわけですから、その方が入院をしたときには、ただ現物から現金に切り替えるということだけで済むわけですから、なぜこれができないのか、ぜひ現金支給をしてほしいと思うんですけど、できない理由も含めて。","respondent":"蓼沼高齢福祉課長","answer":"これにつきましては、先ほどご説明申し上げましたように、制度改正の４月実施から９月の経過措置の期間、区のほうでは４月の前からもケアマネージャーが入って、この制度の趣旨についてご説明して、理解をしてきていただいているところです。","voiceIndex":176,"id":"exchange-075"},{"speaker":"須藤委員","kind":"質問・要望","question":"それなりに質疑をしたので、本日結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-076"},{"speaker":"須藤委員","kind":"質問","question":"先ほど質疑の中でも何点か聞かせていただきまして、考え方も整理させていただきました。基本構想が今議題に出されていますので、これをしっかり認めて、それにつなげて長期基本計画というふうに段取りをとって、議会としてもしっかり発言していきたいと考えています。ですから、このものについては、まだ願意に沿いがたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-077"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、半年に１回、こういうことなのか、１年にこういうことなのか、どちらにしても、そういう今ある施設の中で対応をされているという中にあって、病院とか老人保健施設という、いわゆる施設に入っている人はなかなか入りづらいじゃないかというご指摘に対しては、今、施設入所者に対しても介護の困難性等を重視して、十分配慮できるように見直しを進めているというご答弁もいただきましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから区民全員をお金のあるなしで差別をしないというところでの特別養護老人ホームの増設を１日も早く計画をしてほしいと思います。長期基本計画というふうに言いながら、第四期の介護保険の計画ということもありましたので、私は第四期の介護保険の計画の中に、ぜひ１日も早い特別養護老人ホームの増設の計画を立てていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-079"},{"speaker":"本間委員","kind":"意見","question":"それから３つ目も同様ですが、これは社会福祉協議会の運営ということで、在宅の人々に対する支援のための支給ですが、これまでの利用実態、需要状況から判断しつつ対応してきたというようなこともありますので、充足をしているという現状がある、また区民の理解を得ているということを思って、以上の３点につきましては、願意に沿いがたいということで締めくくりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-080"},{"speaker":"高橋委員","kind":"意見","question":"長期基本計画の中で特別養護老人ホームの建設ということも含めて、介護保険全体に関して検討していくという旨が区長から議会でも答弁がありましたし、今回も副区長からその旨の答弁がありましたので、その対応を注視していきたいと思います。それにより、願意に沿いがたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3194#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":101366,"voices":192}},{"id":"h20-20080225-8","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"建設委員会","time":"午前１０時０２分～午後０時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第２２号議案 品川区手数料条例の一部を改正する条例","agenda":"第２２号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"何点か伺いたいんですけれども、まず今回の改正の、２番の租税特別措置法のほうは、手数料は金額的には変わらないということでしたので、１番の建築基準法関係と３番の都市計画法関係についてちょっと伺いたいんですけれども、それぞれ変更点がありますけれども、法律の改正に従うといいますか、改正を受けての文言整理的ものなのか、それとも区の政策判断なのか。","respondent":"片田建築課長、齋藤住宅課長","answer":"ただ東京都については、そういう他府県の動向を見定めながら、なおかつ昨年６月２０日に施行されました新たな法改正に基づく審査、特にこれについては国の方針ということで。開発許可手数料につきましては、この１０年間分をさかのぼって調べましたけれども、一般の区民の方が開発許可をしてまで家を建てた例はございませんので、ほとんどデベロッパーの方が営業目的で宅地を造成したものですので。","voiceIndex":8,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"そこをどんなふうなお考えになっているのか伺いたいのと、逆にだからといって、ほかの自治体が進んでいる間に、品川区だけは取りませんよと。だけど相手には取られますよという、こういう関係もまたどうなのかなというのはあわせて疑問に思うので、反対するものではないんですけれども、ただそこに疑問が残るので、そこをちょっと教えてください。","respondent":"齋藤住宅課長","answer":"手数料の決まりというのは根本のご質問ですので、なかなか説明が難しいんですが、例えば使用料であれば使用の対価です。税金であれば、住民票を置けば区からサービスを受けようが受けまいが支払い義務が生じます。","voiceIndex":11,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"それからもう１つ、手数料について、先ほどの具体的には都市計画法の関係の説明でありましたけれども、手数料の中に職員の、現場へ何回か行ったとか、どれくらい時間がかかったかと、それを算定しているんだというお話がありましたけれども、今回のこの手数料の中でどれくらいの割合をそういうふうに考えているんですか。","respondent":"齋藤住宅課長、片田建築課長","answer":"手数料の実費相当分の考え方ですが、一例を挙げますと、事前検査として３０分、申請内容の審査として６０分、許可手続として４５分、完了検査に６０分、そして印刷製本、旅費、通信費その他相当分を勘案いたしまして。手数料についても、先ほど委員のほうから際限なくということではございませんで、少なくとも事務に関する必要な経費、現場あるいは事務の審査等々に関しての必要な経費を、時間あるいは人数等々含めて割り出した中で。","voiceIndex":13,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"採算だけではない必要なものというのは、必要な仕事ということがあるわけですから、手数料の考え方については、私は納得できません。そもそも税金を納めて、給料として皆さん仕事をされているわけですから、条例に関しては区民の暮らしを直接奪うものではありませんから、反対するものではないですけれども、手数料の考え方については意見として述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"今、質問の中で確認をさせていただきたいんですけれども、計画通知の手数料というところでは、他区と同等とおっしゃったと思うんですが、これは東京都も２３区も今回、すべてのところでかかっているのかどうかということと、同等は確認でもう一度答弁をお願いします。それから民間との費用の比較というところで、計画通知は、建築確認と同じだということも、そこもあわせて確認です。","respondent":"片田建築課長、齋藤住宅課長","answer":"ただ説明をちょっとつけ足ししますと、過去においては、計画通知、公の建築物については、一部構造等の審査が免除されていた時代が実はございました。他区との関係でご質問がございましたが、他区は改正して２年たったので、改正をしたというのが他区のお考えです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"開発行為のほうで実費で算定をしていくということは、でも特別区すべて給料の算定が違うと思うので、そこは違いがあるということの認識でいいのかということと、もう１つ、先ほど自治体の事業として、建築確認のほうなんですけれども、例えばどういうところ、自治体間でそういう徴収をし合う事例というのがどういうものなのかということと、免除規定が都にあるということでしたけれども。","respondent":"片田建築課長、齋藤住宅課長","answer":"逆の立場で、区が１万m2以上の大きなものを区内につくる場合、逆にこれは東京都のほうに対してその手数料を支払うという考え方になっていますので、例えばほかの他府県であれば。現員現給の質問ですが、今回は２３区の標準的なものを使わせてもらいました。ですから、２３区とも算出根拠としては同じものです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"阿部委員","kind":"質問・要望","question":"計画通知というものをもうちょっと教えていただきたいんですけれども、計画通知というのは今までのお話の中で、要は民間ではなくて公が建てるもの、ですから、品川区の場合は品川区内に、区ですとか、都ですとか、国ですとか、そういった主体が建築物を建てるときには、建築確認ではなく計画通知という手続をとる、そういう理解でよろしいですか。","respondent":"片田建築課長","answer":"今、委員がおっしゃっていただいた、そういうような考え方に基づいて、一般の建築基準法の場合の確認については第６条という条項を使っておりますし、あと計画通知については、基準法の第１８条という条項がありまして、そこは計画通知と別建てになってあります。","voiceIndex":23,"id":"exchange-007"},{"speaker":"阿部委員","kind":"確認","question":"もう１つ、関連質問なんですけれども、１万m2が基準になって都が建築確認をするか、区がするかというように聞こえたんですが、品川区が１万m2以下のものをつくる土地というのは、品川区が品川区に対して計画通知というものを出すんですか。これは手数料と関係なくなるんですか。","respondent":"片田建築課長","answer":"もし品川区が区の権限でできる１万m2以下のものを区の中で設置するといった場合には、例えば区長名で建築主事あてに何千m2の建築確認を出していくといった取り扱いになっています。ただ１万m2を超えるようなものは、区を経由して東京都のほうに申請書類を送付する。","voiceIndex":25,"id":"exchange-008"},{"speaker":"阿部委員","kind":"確認","question":"ということは、これまでは民間では取っていた建築確認の手数料を、公同士だとただにしていたと言ってはあれですけれども、官の場合には同じ仕事をしていても手数料を取らなかったという状態から、官であっても同じように手数料を取りますよということにしたということで、これはむしろ正常な負担になっているのかなと。単に意見ですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"これは答えられなくてもいいけれども、もし答えられる部分があったら教えてほしいのは、今、この時代になって、しっかりピアチェックもやれというようになってきたときに、１万m2の今の話があったけれども、これは、今、事務配分をやっているので、ここのあれじゃないかもしれないけれども、せっかくこういう法改正があったんなら、これをもしやろうというときに。","respondent":"片田建築課長","answer":"１つは、この改正理由の審査事務量の増ということを踏まえてという件ですけれども、実は先ほどもちょっと説明の中で申し上げましたように、東京都のほうとしても、今回の手数料を上げる、計画通知について同等に徴収することに対して。","voiceIndex":28,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"最初のはいいです。２番目もいいです。だけど３番目の話は、確かにルート１にすると、コンクリート量も増えるし、ダブルチェックが効いているからということで、それはオーケーなんです。だけれども、これから審査をするときに、例えば特に行政間で、例えば中高層の部分については、学校系なら中高層で済むわけですから、そうなったときに、安全なんだよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"須貝委員","kind":"確認","question":"今回、品川区手数料条例を一部改正するということなんですが、改正は２３区、東京都一律ということで、これは方向性としてはしようがないと思うんですが、その改正されたときに、今、建築確認の日数も結構かかっている。やっぱりそれでは今の審査事務量が増えたということならば、増員するとか何かということももちろん大切だと思うんですけれども、その辺についてどのようにお考えでしょうか。","respondent":"片田建築課長","answer":"ただ法の告示がすでに出されている部分も含めて、国のほうでは建築確認の円滑化ということで、それぞれ指導あるいはそういう相談機関を設置して対応しているんですが、やはり私どものほうとしても、これまで以上に事前の相談体制なり。","voiceIndex":31,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"意見","question":"計画通知に係る手数料を取るということであって、今の話だと、民間から全部値上げというところをちゃんと答弁しないと、計画通知なんだから、行政間の計画通知に対して手数料を取るというのは、もちろんそれがここに出ていることだと思っているんだけれども、値上げするんだから、それに対するどうという話に対してちゃんと答弁がないと、簡単に全部値上げするみたいな話になるよ。","respondent":"片田建築課長","answer":"したがいまして、サービスのアップのところと、手数料を上げてさらにサービスのアップにつながったという部分とは切り分けて考えさせていただきたいと思っていますし、サービスの件については、これまでもそのような対応をさせていただいてきているところですので。","voiceIndex":33,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"確認","question":"サービスの話をしているわけじゃなくて、何度も言うようで悪いけれども、今まで無料でやっていたものを、新たにしっかり行政間でも計画通知に係る審査手数料として取るものが条例に出てきたわけだ。そこは確認したいと思います。","respondent":"岩田まちづくり事業部長","answer":"説明が悪く混乱を招きまして申しわけございません。今回ご提案をしている３点の内容のうち、２については文言の整理だけです。１について、建築基準法関係については、今、委員がおっしゃったように、民間の建築確認にかかる手数料は一切いじっておりません。","voiceIndex":35,"id":"exchange-014"}]},{"id":"topic-02","title":"平成２０年請願第３号、上大崎３丁目（最高裁判所・裁判所共済組合）旧みやこ荘跡地に関する請願","agenda":"平成２０年請願第３号、上大崎３丁目（最高裁判所・裁判所共済組合）旧みやこ荘跡地に関する請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう少し経過のほうをご説明いただきたいと思うんですけれども、この請願に至るまでの品川区との協議の経過、裁判所の経過もあるのかもしれませんけれども、この経過を少し教えていただけますか。","respondent":"松代管理工事課長","answer":"その中では、みやこ荘が３月末で閉鎖するということで、今回の請願にありますような形で地元としては考えているというお話をお聞きしております。国の意向等を確認してほしいというお話があった経緯があります。","voiceIndex":44,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう少し伺いたいのは、更地にしてしばらくの間は機械警備で管理するのだと。更地の状態というのはどういう状態なのか、もう少し教えていただきたいんですけれども。","respondent":"松代管理工事課長","answer":"一応フェンスで囲いまして、中に入れないような形にするという状態で、そのままの状態で更地という、何もしないということでしたので、余計なことだったかもしれませんけれども、通常、こういった場合、更地にして数カ月放置されると、ほこり等の対応が周辺から出るので。","voiceIndex":46,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区自身が当事者じゃないんですから、暫定的に言えることはなかなか今、把握し切れないのかもしれませんけれども、少なからず今のお話ですけれども、まずは請願の暫定的な利用を可能にしてくださいという部分では、最高裁判所とのやりとりの中で、１本の道を開くべきじゃないのかなと思うんですね。","respondent":"松代管理工事課長","answer":"これは国を挙げて、都を挙げて、近々直下型大地震が来るだろうということを前提に、さまざまな対応をとっているところでございまして、そういった意味で１つの事例を申し上げますと、この１０年の間に３割ぐらいの確率で直下型の大震災が来る。","voiceIndex":48,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"大体この総合危険度ランク１、確かに１でしょう。もちろん全部の木造の耐震の状態がどういうわけだか、細かく正確に把握しているわけじゃないけれども、倒壊危険度１、火災危険度２ということは、そういうお宅もあるわけですから、そこを薄いというのは、それはちょっと暮らしをよく見ていないんじゃないかなと。もう１つ、荏原地区を優先、それは優先すべきところはありますよ。","respondent":"松代管理工事課長","answer":"２点ございまして、１点は、今申し上げましたように、いろいろなご意見があるかもしれませんけれども、区としては防災上の観点から、そこに優先順位をつけて、公園等の手当をしてそこを整備していこうと思っているのが１点、もう１点は財政面ですけれども、当該地。","voiceIndex":50,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"請願に書かれているように、子どもたちが自然に触れ合うこうした場所も欲しいと。そうした場所が防災上役に立つんだと、必要なんだと。この署名の数を見ても、参考も含めると１,４００人ですよね。それだけの方が、直接ここのお住まいの方だと思うんですよ。不必要なものには支出すべきじゃないですよ。最後に質問なんですけれども、仕組みとして教えていただきたいのは、国の土地と言っていいのでしょうか。","respondent":"松代管理工事課長","answer":"これを売却する場合は財務省のほうに移管されます。財務省のほうが普通財産として売買等の手続になろうかと思います。その際、そこと売買交渉をすることになろうかと思いますので、その際は、将来何に使うかによって、当然いろいろと価格の点で交渉等があろうかと思います。","voiceIndex":52,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"じゃ、仕組みとして、国から買うときに値段を安くする、そういう仕組みはあるわけですね。もう少しその仕組みを教えていただけますか。どれくらい、半額になるのか、その辺がちょっとわからないので。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"ただ今までのケースで言いますと、将来、公園とかというところであれば、そういったところでの配慮といったものは一定程度あろうかと思いますが、ただそれはそのときそのときの判断ですし、今、国はこういった国有財産、官舎等。現段階では、当初に管理工事課長のほうから申し上げましたように、最高裁判所のほうはこの土地をまず自分たちとしてどのように再利用するかを検討中であるというお答しかいただいていないわけです。","voiceIndex":54,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"ここのところで暫定的な使用として今、最高裁判所が基本的には検討しているというところだったんですけれども、前の道路用地の農園化というか、そういうな豊町とか東五反田、そういうようなことで、ここの請願にもあります子どもたちが自然に親しみ、土に直接触れ、のびのびとかつ安全に遊べる場所にしてほしいのですよというようなところで。","respondent":"岩田まちづくり事業部長","answer":"それと１点目のこの請願につきましては、町会長を含め、これだけ多くの地域の方が短期間でこれだけの請願署名をされたというのは、なみなみならぬご努力であり、それだけ地域にこういう声、望む声があるということは。","voiceIndex":57,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"全体のまちづくりというところではいろいろ協議をしていかなければいけないということがありますので、さっき言った暫定的なというところでは、世田谷区のほうで、そういう建築物をつくるという計画があるんですが、動かなかったときに、そこを市民がかかわる花壇として２年間ぐらい提供したという事例もあるし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、方針は未定だと。これは活用は、逆に言うと、検討しているんだけれども、いつごろまで検討されるんですかというのは、聞くぐらいは聞いてもいいと思うんだな。それが１つ。財務省の普通財産に変えたら、まず難しいかなというところがあるわけで、逆にここに約１,０００坪あるわけですから、活用の中で、例えばちょっとした官舎を建ててもらってもいいわけ。","respondent":"松代管理工事課長","answer":"結論から申し上げますと、問い合わせたときには、非常にクールで厳しい対応で、決まっていませんという繰り返しと、まさに今、検討中だということの繰り返しでございました。","voiceIndex":60,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"本当に普通財産になったら非常に難しい話が出てくるわけだから、今の暫定の問題も含めて、１回そういう場をつくれるような形が、私はあってもいいのかなと思っているので、それはぜひお願いをしておきますし、私はこれは趣旨をしっかり受けて、しっかりその趣旨で扱っていただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"そのときに地元の方々とよくない関係の中で職員の官舎ができていくというのは最高裁だって望まないことだと思いますので、その辺、地元の方の思いをまさに最高裁に直接持っていくような形をとったほうが、例えば官舎であれば、あるいは他の施設であっても、つくれば地域の一部の人たちになっていくのだからということで、ぜひそこは硬軟あわせてやっていただきたいということと、それから、いや。","respondent":"松代管理工事課長","answer":"最高裁等の方針が決まっていないということから、想定の話になりますので非常にお答えしづらいというところですが、全く可能性がないかというと、これはもちろん交渉によると思います。","voiceIndex":63,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問・要望","question":"こういったことは本当にタイミングと情報戦だと思いますので、コンタクトはとりつつ、ぜひ頑張っていただきたいと思います。これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"},{"speaker":"三上委員","kind":"質問・要望","question":"国の方針として、山手線内にある国の施設等については処分する方向でいる。それに加えて、山手線の外にある小山台公務員住宅さえも処分するという方針が、平成２２年にはという１つの目安がある。これは申し述べていってもいいんじゃないかと思います。質問的な部分というのはもう既に話がありましたのであれですから、そういった点で要望はぜひとも品川区としても申し述べていってもらいたいと思います。","respondent":"松代管理工事課長","answer":"今、委員からお話がありました隣接する目黒宿舎、当面建物としては残るという話を聞いていますので、将来的ことは、そういった意味では、ここの部分も、今、委員がおっしゃった官舎はすべて見直すという点の１つかと考えていますが、これは一応ご報告までです。","voiceIndex":66,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"多くの地域の方がこれだけ要望されているということはとても大切なことなので、ぜひご尽力いただきたいということ、やはりあくまで裁判所共済組合の持ち物ということで、裁判所のほうでもどういうふうに判断して使うというのもまだきちんと決まっているわけでもないし、一応方向性とすれば何かに使うことを検討しているんだと思うんですが、ぜひ住民の皆さんも直接働きかける。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出していただきたいと考えています。先ほどもちょっと私は触れましたけれども、相手のあることも含めて、住民の方々がこれだけしっかり趣旨を述べられて、住民の方に再度動いていただかなくちゃならないこともあることも踏まえて、やっぱり行政側も一緒になって動くということを考えると、ぜひ趣旨採択でお願いしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-029"},{"speaker":"中塚委員","kind":"意見","question":"私は結論を出すということと、態度としても採択すべきだと思います。ここに書かれている住民の方のご意見は十分理解できます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"意見","question":"さっきも説明したんですけれども、これは最高裁判所というところが今、お持ちになっていて、請願を採択したということになると、相手も、この管理部局も強硬になる可能性があるし、その採択を受けて、行政側が動いたら逆効果になるかもしれないので、先ほど言ったように、住民の方には対応してくれるというお話があるのであれば、それを後押しするために、その部分については趣旨採択にして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"これは所有者が最高裁判所なので、まだこちらでなくて国が持っているという意味からすると、採択という形をつくってしまうよりも、住民と区のほうで裁判所と交渉していかなければいけないというスタートラインであるわけですから、ここでけんかを売るというよりも、住民の方と区が大きくは同じ方向を向く。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"私も住民と行政と一緒の方向で取り組んでいただきたいということで、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"今、皆さんのほうが趣旨採択ということで、全会一致の重みもありますから、ただ、僕は採択を主張したのは、住民の願いをきちんと議会が受けとめて、真っすぐ届けることが大事だと思ったのでそう述べましたけれども、私も趣旨採択ということで結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-034"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、説明があったとおり、３年ほどですか。わりと新しいのに、これだけのパネル何枚分になるんでしょうかね。はがれたというのはどうだったのかなという感じで、実際、風が原因で飛んでしまったんだろうけれども、なぜ飛んでしまったのか、専門的なことはわかりませんけれども、原因は特定されているのか、業者とのやりとりの中をもう少しご説明いただけますか。","respondent":"齋藤住宅課長","answer":"業者は３８ｍの風には対応できると言っておりましたが、構造上、二、三cmのビスでとめる程度のものでございましたので、そもそも構造上の問題がある。","voiceIndex":89,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えばルーバー的な風抜きがあるような目隠しタイプのこういうものもあるし、そういうことが起きたのであれば、やっぱりどこかで改修するときもあれば、いつかほかの施設でもそういうものがあるのであれば、生かして、風が抜ける目隠しタイプのものがあるわけですから、それはどこかの頭の片隅に置いておいていただくということをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"２月２１日の川西絹子議員の質問で、大井林町都営住宅跡を取得し、品川区基本構想の中での活用について伺いたいと思います。住宅の取得に関するところで、もう少し詳しい状況が聞けたら伺いたいなと思っています。もっと具体的に言いますと、答弁の中で、都として跡地を検討する動きもあるという話があったので、どういうことなのかなというところをもう少し説明していただけたらということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":33083,"voices":96}},{"id":"h20-20080225-9","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"文教委員会","time":"午前１０時０２分～午後０時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"例えば、週２０時間で、４時間勤務で５日間というａのケースを選択する場合に、私なんかは単純に、朝の始業からお昼ぐらいまでの４時間を選択するのかと思うんですけれども、いろいろなケースによって、そうではない場合もあるのかもしれないので、その辺の出退勤の時間が、４時間なら４時間というところで、いろいろなケースとして選択できるのかどうか、朝の始業時間からなのかどうか。","respondent":"河野指導課長、市川庶務課長","answer":"幼稚園教諭の育児休業取得状況ですが、現在私が把握している範囲内では、現段階でたしか育児休業をとっている教職員はいかなったと記憶しています。私からは、１点目と３点目のご質問です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"例えば、極端な場合、１０時から、拘束を入れて３時ぐらいになるんですか。そういう時間でも可能だということでいいわけですね。そこをちょっと確認したいと思います。そういうところで、私は否定的にとらえないでおきたいと思っているんですけれども、その辺のいろいろな状況を聞きたいと思って、質問しているので、そういうことでよろしくお願いしたいと思います。","respondent":"河野指導課長、市川庶務課長","answer":"現在の品川区立幼稚園における教諭の年齢構成そのものが、非常に二極化しているのが現状です。主な層としては、新卒数年ぐらいの２０代の教員と、４０代、５０代の教員ということで、３０代の教員が非常に少ないというのが実態です。それが、ワンパターンにならないように、先ほど説明させていただきました４つの形態を取り入れて、この中で選択しているという制度的なバックアップもあります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"金野委員","kind":"質問","question":"ご父兄の方、園児という側から見たときに、この育児休業をとって、この制度でやって、もし、担任の方がこの制度をとられた場合、途中で担任がかわるということが多分あるんだろうなと思うんですけれども、その場合、保護者へのお知らせというんでしょうか、園児たちが急に職員の方が、担任がかわられるということは結構大変かなと、園児の受ける感じとしては大変かなと思うんですけれども。","respondent":"河野指導課長","answer":"幼稚園教諭がこの制度をとった場合の措置ですが、時間でとるのか、あるいは勤務日数でとるのか、それによっても対応が変わってくるかと思いますが、今の状況で、私たちで考えている方向としては、完全に休業するわけではございませんので、当該教諭が勤務しない場合には。","voiceIndex":11,"id":"exchange-003"},{"speaker":"金野委員","kind":"質問","question":"そうすると、ふだん、クラスが、担任が何人制になっているのか、そこら辺、ちょっと勉強不足なんですが、来る日と来ない日とをその担任がした場合、代替の先生は、同じ職員でやってくださるんでしょうけれども、常にそのクラスにかかわっている方がそれをしてくださる、そうではない状況なんですか。","respondent":"河野指導課長","answer":"したがいまして、常勤の教員が後補充に入るということについては、今のところ無理だろうなと考えております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"金野委員","kind":"質問","question":"お子さん方にとっても、自分が幼稚園の中でのお母さんとしても慕っていた担任の先生が急にかわるというのは、子供たちの園生活にも何かしらの影響がないとは言い切れないと思うので、その辺のところは、スムーズに、園児たちや保護者にとっても不安がないような形でぜひお願いしたいと思います。保護者への周知というか、それはどうされるんですか。","respondent":"市川庶務課長","answer":"保護者の周知につきましては、当該の園長のほうから保護者に対してきちんと説明をして、理解を求めると指導してまいりたいと考えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"短時間勤務というのが制度化されたということで、大変評価したいと思っていますが、どういう方が利用するのかなと思うんです。自分はこういうふうにやりますという制度なのか、それとも、例えば、自分のお子さんが病気になったりしたときに利用できるものなのか、通常、今、育児休業というのは３年かそれぐらいですよね。その辺はいかがなんでしょう、どういう使い方を想定しているんでしょうか。","respondent":"市川庶務課長","answer":"ただいまのご質問ですけれども、委員ご自身がご指摘なさっていたように、やはり今の次世代育成支援というか、仕事と子育ての両立というのを、底辺を厚くするというか、いろいろなメニューを用意して、この少子化の世の中への対応策をというところから考えられたものだと思います。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、実際幼稚園教諭ですから、責任感があるわけであって、なかなか使いづらいだろうなというのを率直に感じるんです。たくさん代替教員とか、雇用するわけにはいかないと思うので、多分その施設の中でのやりくりになってしまうだろうなと。もう一つ、退職金のところが、退職金のところがよくわからなかったので、もう一度説明していただきたいんですけれども、どういう改正なんですか。","respondent":"市川庶務課長","answer":"つまり、１２カ月ではなくて、８カ月を退職手当の算定の計算対象にしますという取り扱いだということです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"山内委員","kind":"確認","question":"１点だけ確認をお願いできればと思うんですが、２番の2)の勤務形態なんですが、これは４通りありますよね。例えば、この４通りからしか選べないということでよろしいんでしょうか。","respondent":"市川庶務課長","answer":"したがいまして、この４つしかパターンがございません。","voiceIndex":21,"id":"exchange-008"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、例えば、私、３時間しか働けないといった場合は、極端な話、１日３時間しか無理なんですといった場合は、これに一番近いので、これで見ますと、ａの４時間掛ける５日間という形になるので、これを選んでくださいということで、こちらから指導するという形になるんでしょうか。","respondent":"市川庶務課長","answer":"実情では、この育児短時間勤務制度というものは、この４つのパターンがありますので、ここから選んでもらうことになるという説明になると思います。はその本人の事情と仕事の内容、職場の実情、それを掛け合わせた上で考えていくということになろうかと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけ、僕も、今の山内委員にもちょっと関連しているんですが、この勤務時間は、例えば、ａが４時間、５日間となっていますが、多分働いていると、実際いろいろなケースが起きてくると思うんですけれども、時間が４時間と決まっているけれども、それこそ残業という形がどうしても必要になった場合に、残業に関することがどこにも載っていないものですから。","respondent":"市川庶務課長","answer":"これはフルタイムと同じですので、正規の勤務時間がその職員の場合には、１日４時間でしたら、４時間ということで、しがたって、先ほど説明しましたけれども、給与も、給料月額はその分しか出ないわけですので、実情に応じて超過勤務をしたときには。","voiceIndex":25,"id":"exchange-010"},{"speaker":"大沢副委員長","kind":"質問","question":"改正概要の中の「等」ということが３つ、「育児短時間勤務職員等」と「勤務時間等」、そして、「給料月額等」、これは最初の「職員等」は、２の(2)で説明をされている勤務時間等の「等」は３番で説明されている、「給料月額等」は４番で説明をされているということで、大きな３番の(2)の1)の「週休日の割振り等」ということ、(1)と(2)なんですけれども。","respondent":"市川庶務課長","answer":"週休日のところで、「週休日の割振り等」と書いてありますけれども、まず１つ典型的なのは、割振った週休日を振り替える場合があります。そういったこと、これを含めて、「等」ということで示させていただきました。","voiceIndex":27,"id":"exchange-011"},{"speaker":"市川委員","kind":"質問","question":"３ページに１時間当たりの給与額というのが載っているんですけれども、１時間当たりの給与額というのを、常勤の週４０時間で働く方と変わってくるということなんでしょうか。","respondent":"市川庶務課長","answer":"そうしたものが、同じ数式の中にまざっておりますので、基本的にはこういう計算をすれば、フルタイムの職員とは別の時間額が、時間単位の中で出るです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"大沢副委員長","kind":"質問","question":"ちょっと蒸し返しになるんですけれども、さっきの３番の(1)と(2)なんですけれども、「週休日および勤務時間の割振りは」と、「および」ということで同列になっています。下の週休日のことで、「週休日の割振り等は勤務の内容に従い、定める」と。説明ください。「勤務時間等」と書いてあるんですけれども、「勤務時間等」というのは、週休日も「等」の中に入るんですか。","respondent":"若林委員長、市川庶務課長","answer":"庶務課長、(1)の勤務時間等と(2)の週休日をしっかりと分けて、関連して説明するとまたややこしくなりますので、一つ一つ明確にした上で、表現等に何か説明してもらえればと思いますが。(1)の「勤務時間等」ですけれども、これは１週間の勤務時間、それから、週休日および勤務時間、ここで勤務時間がダブっちゃっているところが、申しわけございません、確かに、ただ、ここで申し上げたいのは。","voiceIndex":31,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"基本的なことが全然わからなくて、一番最初に聞けばよかったんですけれども、今、幼稚園教諭の勤務時間というのは、朝何時からなのか、区職員とどういうふうに、同じなのか、違うのか、その辺を確認したいのと、産休もそうですけれども、育休をとった場合の代替職員というのは、配置されるのは当然だと思うんですけれども、どの程度配置されているのかどうか、その２点が。","respondent":"河野指導課長","answer":"産休、育休代替ですが、これは特別区人事・厚生事務組合のほうで採用選考を実施して、産休代替候補者を名簿搭載して、必要が出た場合には、その名簿搭載者の中から、それぞれの区が面接等を実施して、最終的にお願いするという形です。","voiceIndex":36,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ただ、幼稚園の教諭は、子どもを育てるという仕事、教育職ということもあって、質問の中にもありましたけれども、担任との関係で、いろいろな問題が出てくる場合もあるかもしれませんけれども、同じ子ども、人様の、区民の子どもを預かって、自分も自分の子どもを育てるという立場にある職だということでは、職場の中での相互理解、相互支援態勢というのを整えていかなければいけないと思うし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"}]},{"id":"topic-02","title":"通学区域の取り扱い","agenda":"通学区域の取り扱い","exchanges":[{"speaker":"南委員","kind":"確認","question":"全然つまらないことで、地図で確認すればいいんですけれども、確認してこなかったので、八潮４丁目というのは、どこにあたるんでしょうか。八潮４丁目、５丁目全域だと書いてありますけれども、八潮団地は５丁目なんですけれども、４丁目というのは、昔、品川清掃工場があった、あそこなのかなと、ちょっとわからないので、確認したいんです。","respondent":"古里学務課長","answer":"八潮団地の下側、住宅区域ではないんですけれども、スポーツの森がある、大田の区境のところまでが八潮４丁目です。","voiceIndex":58,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"わかりました。でも、公園だから、人が住むような用途にはなっていないと思うんですけれども、通学区域はそういうものなんですか。","respondent":"古里学務課長","answer":"一応八潮の地域ということで、すべて入れてあります。申しわけありません。","voiceIndex":60,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":15470,"voices":72}},{"id":"h20-20080225-5","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"総務委員会","time":"午前１０時０３分～午後０時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査の（１）第１０号議案、品川区基本構想","agenda":"議案審査の（１）第１０号議案、品川区基本構想","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと私も第１回目の報告のときからの資料をいろいろ読み返させていただいて、疑問に思ったことを改めて質問させていただきたいのですけれども、まず１つは、せっかく区長が来てくださっていますので、１回目のこの策定委員会が行われた際に、区長が参加をされて、あいさつされておられるんですけれども、その中で行政改革ということでお話をされていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"どのようにあらわれているのかを少し教えていただきたい。","respondent":"福島長期計画担当課長","answer":"もちろんこの基本構想を策定するに当たりまして、委員の皆様にはそういったことも含めまして検討していただきました。その結果として、この今回の基本構想がなされている。当然ながら、前のものを分析されているし、また、基本構想につきましても、事務局としても説明しています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"というよりも、区長のごあいさつ、先ほど言ったごあいさつの中身というのは、区政が行政が１０年、２０年進んでいく中て、当然その間に区長が交代をされたりとかという流れがあっても、それによって途切れることはないんだよというのが基本的な考え方なんだと思うんです。ですから、この中でどう読み取ればいいのかというのがわからないので、そこをお聞きしたんです。","respondent":"福田企画部長","answer":"これにつきましては、今、長期計画担当課長が申しましたように、策定委員会の中でも一定の議論はいただいておりますが、しかし、本格的にはこれから始まろうとするその基本計画の中で、今後の施策、それからそのパッケージとしての政策。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"施政方針の中でも、区長が本来そういうものは基本的なことだというふうに述べておられるんですけれども、単純に当たり前のことだというのではなくて、やっぱり繰り返し繰り返しこうした本来受け継ぐべき基本的な理念というものも明確に記述をしていくべきではないかというふうに申し上げているんですけれども、もう一度その辺を。","respondent":"福田企画部長","answer":"先ほど長期計画担当課長が説明いたしましたように、この基本構想自身が、この基本構想の前提を記述しております。具体的には、２ページ、基本構想を貫く３つの理念、この前文のところです。区は基本的な施策について、これを重点的に実施する、これが大前提だと。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地委員","kind":"意見","question":"これもちょっと私、また読み返させていただいたんですけれども、この中で４ページのところで、非正規職員が２００６年で全労働人口の３３％にまで達しているとか、あるいは、９ページのところでは、社会保障の給付金が高齢者に多く回されている状況なので、子どもに回す分を多くするんだと、こういうデータなどもありますけれども、区はこうした改定の課題が、こういう出された資料について。","respondent":"福島長期計画担当課長","answer":"これをどのように取り込んでいるかということではありますけれども、こちらはあくまでも資料といたしまして委員の方にお示しし、この中からどんな課題が見えてくるか、品川区としてはどういう方向を向いたらいいのかということを策定委員の皆様にご検討していただきたい。","voiceIndex":13,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"非正規の雇用が、例えば、この資料だと３３％になっていますよと、これは本当に今の時代の中で所得格差だとか、貧困のあらわれとして、品川区だけが違うというわけではないんだと思うんですけれども、そうじゃないからこそ改定の課題ということで、こうして資料として上げられたのではないのでしょうか。","respondent":"福島長期計画担当課長","answer":"そういった意味で、区の考えが載っていないということで、あくまでこの基礎資料をもとに次の施策を考えるというものです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"というか、分析する必要のない資料だということに聞こえてしまうんですよね。区民生活の中に、今、日本全土を覆っている格差の問題だとか、貧困の問題というのが進んでいるというのは、これはもう行政でもとらえていると思うんですね。だけど、あくまでも国の問題として単に出しただけでというふうに今のお話ではとれるんですけれども、もう少しそこを。","respondent":"福島長期計画担当課長","answer":"あくまでも資料の出どころが国だです。その実態を踏まえて、どのような施策を考えていくのか、それはまた真剣に考えなければいけない問題であると考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"文章上のところで幾つかお聞かせ願いたいんですけれども、１つは、１ページ目にありますけれども、第１章のところで、バブル経済の崩壊とその後の経済再生というふうに記述をされていますけれども、この辺がよくわからないんですけれども、経済再生と言いましても、経済そのものが先ほどの改定の課題の中でもいろいろなデータがある中で。","respondent":"福田企画部長","answer":"その後、いわゆる失われた１０年、これが続きました。今はようやくのこと経済成長２％、そこまで経済が回復した、このことを指しているものでございまして、一たん崩壊はしたけれども、やはり日本経済は力強く再生に向かっている、そのような認識です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"２％というお話がありましたけれども、実質的には確かに企業そのものは今年から去年にしても大変大きな利益を上げているというのは確かにそのとおりなんですけれども、ただ、実質的には勤労者、国民の多くが実質的な収入としては、この１０年ばかりで６％からは７％くらい下がってきている実態があるわけですから、そこは国が経済について言うのと。","respondent":"福田企画部長","answer":"しかし、この中では、この１行目にありますように、区政を取り巻く社会経済環境、このことを大きな視野でとらえた場合には、大局的にはここにありますように経済再生、こういうふうに言っていいのだろうというような認識です。","voiceIndex":21,"id":"exchange-009"},{"speaker":"菊地委員","kind":"意見","question":"どうしてもそこは実際の私たちの区民生活から見れば、絶対に納得できる部分ではありませんので、やっぱり区民生活というものに目を向けた形での第１章であれば第１章の中で実際に区民生活というものを記述をされるべきではないかというふうに思いますし、国際都市というのであれば、そこに区民生活の中にこそ軸足を置くべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"私も今回、基本構想策定のお話を伺い、また考え方を伺うことができて本当にうれしく思っております。その中で、これは要望も含めてなんですけれども、これだけ夢のある基本構想という形になりつつあるということで、やはりこれを見た品川区民の期待、これはすごい品川区になっていくなということが多分感じられると思うんですね。","respondent":"福島長期計画担当課長","answer":"職員ですけれども、実は職員向けには研修も考えておりまして、今週の木曜日なんですけれども、職員向けの研修ということで、基本構想について勉強する、職員も一緒になって勉強しましょうということで、基本構想の研修も開かれる予定です。","voiceIndex":24,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１つ言えば、生存権とか、あるいは基本的人権を守るために、すべてをどういうふうに区民生活の支援をしていくのか、このことを明確にすることが求められていると思うんですけれども、でも、この文章全体の中でもどうしてもそうした行政の責任としての部分が、この中で協働とかという言葉であいまいにされているのではないかというふうに思います。以上の理由で第１０号議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"基本構想ということですから、現行のこと、これらのことも大きくそれぞれの委員の皆さんが視野に入れながら、そういうさまざまな定見を生かされた中でご意見が出されてきて、新たな方向というものをそれぞれお話があったんだろうと思うんですね。それを言葉にまとめるわけですから、なかなか難しいことだと、これだけの言葉の経緯、大論文をつくるのではありませんので。ということを申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どうしてもやっぱり何回も聞かなければいけないことは、区長会が質問を出して答えが返ってきた。中身は非常に真剣なことになるものですから、やっぱり大切なことは、これを区長会がどう受け取っていくか。それを具体的に、例えば、区長会の中で専門の検討部会をつくっていくのか、これは区長会でどういうふうに具体化していくかということが大きなスタンスだと思うんですよね。","respondent":"濱野区長","answer":"これを実現していくための手立てということにもなろうかと思いますし、まず１つ重要なのは、特別区がこれを旗印にして１つにまとまらない限り、このレポートは全く単なる字が並んでいることにしかなくなってしまうと。","voiceIndex":42,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけれども、基礎自治体連合というものがはっきりとイメージをしていく、これに向かってすべての２３区の区長が一丸となっていくんだという、そこはどうしても確保していかないと、本気でこういうことをやっていこうとすれば、非常に大きな障害になってくると思うんです。ですから、意見になっていますけれども、もしこれで、今、濱野区長の個人の意見は聞きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ。これは本当に純粋によくわからないところなんですけれども、区長が最後にご報告された仮に道州制になったときというお話があって、そういう中で基礎自治体連合ができあがることで、基礎自治体としての役割というか、そのほうがむしろ強くなるのではないかみたいなお話があったんですけれども、その辺の考え方をちょっとよくわからないところなので、そこだけ教えていただければと思います。","respondent":"濱野区長","answer":"つまり、もっと広域な行政体になるわけですから、それが品川区はどうしたとか、何々区はどうしたなんていうようなことの仕事を取り込んだままそういう広域な自治体になることはできないだろうから、したがって、都の区の制度、このレポートの趣旨というのは。","voiceIndex":45,"id":"exchange-016"}]},{"id":"topic-02","title":"移らせていただきます。 議案審査の（２）第１１号議案、品川区職員定数条例の一部を改正する条例","agenda":"移らせていただきます。 議案審査の（２）第１１号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"今回の定数のところで一番大きいのは調理ということですけれども、もしわかりましたら、何校ぐらいを考えておられるのかちょっとお聞きしたいのと、それともう１つは、昨年の委員会で業務委託をする際に考える基準みたいなものが、定義みたいなものがあるのかということをお聞きしたときに、区民サービスが減らない限りは事務を効率的にしていこうという考え方がベースにあるんだ、減らないというのは、多分。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"調理のほうですけれども、調理の業務代行の校数は平成２０年度で７校を予定しております。委託に関して業務のチェックですが、これに関しては、指定管理者でもそうですけれども、現場を各所管課が確認して指導等、仕様書にのっとった業務が行われているか、それについて日常的に把握して指導を行っている、こういう状況です。","voiceIndex":52,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"今後、調理代行のほうも７校ということですけれども、これもこれから契約になっていくんだと思うんですけれども、その際のきめ方というのをちょっと確認をさせていただきたいのと、それと、業者がかわることで人がかわるとか、とにかく安定しない部分が出てくると思うんですけれども、今のチェックの話だと、日常的にというだけで、具体的にどういう、最初の契約というのがあるにしても。","respondent":"堀越行財政改革担当課長","answer":"事業執行上の決め方の部分です。これは事業を進めるに当たっていろいろな、例えば職員の体制ですとか、そういういろいろな状況、民間の市場規模等、いろいろなこと勘案しまして、総合的に見直しを図りながら民間の委託導入等を決めてきている、そういう考え方です。","voiceIndex":55,"id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"調理業務の代行のところで、どうしても気になるのが、どの分野でもそうなのかもしれませんけれども、やっぱり日常的にどうチェックをされるのかというのが大変気になるところで、昨年、給食に関して言えば、大間窪小学校をはじめとして３校で、昨年でしたか、調理の委託をした業者が途中で辞退をされるということがありましたけれども、こういう問題が日常的なチェック体制の不備の中で起こるのか。","respondent":"堀越行財政改革担当課長","answer":"したがいまして、事業者の選定の段階、それから執行状況のチェックの段階、そして区として事業者の実施主体の責任として適正に管理をしている、そのように認識をしております。","voiceIndex":57,"id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"その辺の日常的なチェックの仕方というものをやっぱりきちんと構築すべきなのではないかなというふうに思います。そのためには、やはりきちんとした委託後にどうなるのかということを検証できるような検討委員会なども、私はぜひとも必要なのではないかなというふうに思うんですけれども、そういう新たな体制づくりについて考えがあればお聞かせ願いたいと思います。","respondent":"堀越行財政改革担当課長","answer":"今後の体制について、これからいろいろな、例えば指定管理にしてもそうですし、指定管理部分についてはモニタリングのシステムを今年度から実際に実施しておりますし、そういった部分も合わせて。","voiceIndex":59,"id":"exchange-020"},{"speaker":"菊地委員","kind":"意見","question":"サービスの後退というのは、部分的には実際に起きているわけですよね。私は否定するわけではないですけれども、今回の本会議でうちの議員がやらせていただいた区で働く労働者、委託先の労働者にしても、最低賃金の問題も含めて、区民サービスとは何かということを考えていくことではないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-021"},{"speaker":"浅野委員","kind":"提案","question":"ホームページでちょっと確認しましたら、平成１９年と平成１８年の対比という形で載っていた部分をにらみまして、そのような形で、例えばこの２ページでありますと、事務が全体で何人で、その中で増減があって、平成２０年度は何人になるのか、ちょっと煩雑になりますけれども、そのような表をぜひつけていただければ、例えば増が非常に多い、その中でこれだけ増減したのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"第１１号議案については、反対をします。先ほど申し上げたように、区民サービスで後退をする部分、行政が本来区民サービスを考えるときに、あるべき姿というところから後退をした部分があるので、そうした立場で反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"資料の見開きの４ページのものです、ちょっと聞き逃したのかもしれないので、何点かお尋ねしたいんですけれども、今度の新しい育児短時間勤務のところで、小学校就学まで、お子さんが６歳でしょうか、取得期間の単位なんですけれども、これは１カ月以上１年以下というのは、６歳に達するまでの間に、この期間だったらとれますよということなんですか。","respondent":"榎本人事課長","answer":"ですから、この育児短時間勤務はとりあえずまずは１年間しか請求ができないという制度の設定のものです。","voiceIndex":71,"id":"exchange-024"},{"speaker":"菊地委員","kind":"意見","question":"１年間とりますよね。あけてから再度請求できるというような、ちょっとどうもそこが……。","respondent":"榎本人事課長","answer":"今のまず取得単位のところで１年以下になります。ただ、下から２段目のところで、再度の請求というところで、同一の子については期間終了後１年経過後に再度の請求ができるということで、ここで１年経過をしなければ再度の請求ができないというのが原則なんです。","voiceIndex":73,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"それと、この資料の３ページで、一番最後にある並立任用のところなんですけれども、お二人の方が同じように育児で短時間勤務に入っている場合には、小さいお子さんは常にそうですけれども、病気で保育園から突然呼び出されたりとかということが常にあると思うんですけれども、同じような育児の短時間勤務ということだと、２人で実際に任用していくみたいな考え方というのはあるんですか。","respondent":"榎本人事課長","answer":"ただ、これができるのは、週２０時間勤務の人が２人いないとできないということなので、週２５時間勤務ですとか、２４時間勤務を選択された場合には、できないということになります。","voiceIndex":75,"id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"こういうせっかくできた制度の中で、多くの皆さんが楽にとられることが必要なんだと思うんですけれども、要は、今の部分で、２０時間勤務の人が２人いたとして、同じ職場で職員としてどういうふうな考え方で、これはきちんとした加配みたいな感じになってしまうかもしれませんけれども、そうした職員体制がやっぱり必要なのではないかなというふうに思います。申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-027"},{"speaker":"土井委員","kind":"質問・要望","question":"確認させていただきたいのが１つと、もう１つ、先ほどの延長再度請求のところのことです。さきほどの話で１年以下というのは、延長しても１年以下という意味ですか。それから、これら労働条件にかかわる中身等でもありますから、当然法律の条項のほかに、組合の皆さんといいますか、職員の団体の皆さんとの間でお話し合い等がされたと思うんですけれども、その状況はどうなんですか。","respondent":"榎本人事課長","answer":"ただし、１回そこまでの最初の取得が終わった場合には、１年経過した後でないと再度の請求はできないということです。それから２点目の労働条件につきましては、職員団体それぞれの団体、労働組合に協議をいたしまして了承を得ているところです。","voiceIndex":78,"id":"exchange-028"},{"speaker":"浅野委員","kind":"質問","question":"資料の３ページ目（４）の2)、在職期間等からの除算というところで、期末手当、勤勉手当があるんですけれども、それぞれ文言が違っているんですが、ちょっと具体的に、例えば、週２０時間ですが、丸々１年間とった場合に、それぞれこの期間というのはどのようになるのか教えていただけますか。","respondent":"榎本人事課長","answer":"３分の１を除算ということなので、３分の２は勤務したものとみなすので、８カ月勤務したものとして退職手当については在職期間をカウントするという形です。","voiceIndex":80,"id":"exchange-029"},{"speaker":"浅野委員","kind":"質問","question":"例えば、期末手当の場合ですと、１年間、週２０時間でやった場合、短縮分の２分の１に相当する期間というのは、半分ですから、例えば１年をベースとした場合には、これは２分の１になっているのか、それとも４分の３になるというのか、ちょっとそこら辺が認識できなかったので、その勤勉手当もご説明ですとゼロになるというふうに聞こえたんですけれども、読み方によっては半分なのかなというふうに。","respondent":"榎本人事課長","answer":"その半額にならない部分がどこかというと、先ほどの期末手当の部分が実際に４分の３支給になって、勤勉手当が２分の１支給ということなので、その部分で年収ベースで行くと半額を上回っているという形になります。","voiceIndex":82,"id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"これには、いわゆる雨期の集中豪雨等があるような期間は仕事をしないという、これが非常に大きな影響を与えているわけですね。それによって金額も増え、工期も増えてしまったという形なんですけれども、例えばこの目黒川に関する限りにおいては、すぐ近隣に出水防止のための大きなプールを、ため物をつくってありますよね。そういうものはこういうものには何ら考慮されないんですか。","respondent":"青木都市開発課長","answer":"私どもとしても、そうは言っても、改修が進んでいる河川であるから通年施工が可能ではないかという協議は東京都河川部と進めておりましたけれども、その平成１７年当時の実際に杉並区や中野区のほうで中小河川が氾濫する被害が出ておることを踏まえると。","voiceIndex":93,"id":"exchange-031"},{"speaker":"土井委員","kind":"意見","question":"そうだったんだというふうに理解しなければいけないんだと思うんだけれども、やはり技術的にあんまり根拠が薄いんですよね。要するに、向こうであふれたからこっちもというだけだったら、責任逃れだけなんです。そうしなければ、下手をすると、もう１つ小さな橋がかかってしまうぐらいの値段になってしまうわけですよね。ぜひそういう技術的な面も含めてこれから働きかけをお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"今後、よくこの委員会で積算の話が話題になりますけれども、こういう工事というのは、実際の人員の問題ですとか、いろいろ工事上の問題でないとなかなかこういうふうにこの数字が４億６,０００万円出たというのは、きちんとしたものなのかどうかというのがよくわからないことだと思うんですけれども、その辺を教えていただきたいのと、もう１つ、たくさんのコンクリートの固まりが出てきたということで。","respondent":"青木都市開発課長","answer":"２点のご質問にお答えいたします。","voiceIndex":96,"id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"最後の部分で、通常必要ない。結果として、そういう考え方のもとでこの４億６,０００万円からの新たな工事費が必要になってしまったと考えると、その辺を計画性、最初の計画での不完全さというのは否めないんだと思うので、そこはやっぱりこれからのこうした工事には生かしていく部分だと思うんですけれども、その辺はどうなんですか。何かの規定があってそういうことになっているのか。","respondent":"青木都市開発課長","answer":"確かにこういったことで当初の予定が狂うという点では、非常に私どもとしてもご迷惑をかけて申しわけない部分ではあるんですが、何から何まですべて事前の調査を万全にすることが望ましいという考え方ではないと考えています。","voiceIndex":98,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1776#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":44550,"voices":106}},{"id":"h20-20080226-6","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"区民委員会","time":"午前１０時０２分～午後０時１０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"近隣セキュリティシステムが継続できるということで、大変よかったと思います。それから、ちょっと気になっているのは、ＹＯＺＡＮと品川区が契約しているわけですよね。ＹＯＺＡＮもジャスダック上場会社ですし、ソフトバンクですと東証一部上場という大手企業同士ですから、その辺の契約関係に問題はないと思うんですが、その辺の確認だけ聞いておきたい。","respondent":"中山地域活動課長","answer":"それで、どのようにつながっていったのかということでありますけれども、これは企業間の交渉の中身にもかかわってくるかもしれませんけれども、基本的には運用事業者がソフトバンクであり、そういうノウハウを持っている、そういうことの中で。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"例えば、今度４月以降も、これから先の話ですけど、ソフトバンクと契約になるとしたら、そこでソフトバンクと新たに契約するという形になるのか、その辺をもう一点確認したい。","respondent":"中山地域活動課長","answer":"今年度の契約につきましては、先ほど申し上げたとおり事業譲渡でございまして、新たな契約変更という手続は必要なく、ＹＯＺＡＮの契約がそのままソフトバンクに事業譲渡されるという形で、新たな契約はございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"途中でＰＨＳから変更とかということもありましたけれども、今回先ほどのご説明の中で、事業の経営の悪化に伴いというご説明がありましたけれども、最初のときに、プロポーザルのほうでＹＯＺＡＮに決まったと聞いていますけども、そのときの選定する際の区の考え方というのはどうだったのかということをちょっとざっと聞きたいんですけども。","respondent":"金子産業振興課長","answer":"この件につきましては、先ほど地域活動課長から言いましたとおりですが、平成１７年に事業開始していまして、その前年、平成１６年度に事業者の選定を行っています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"総合的に評価ということだったんですけども、今回ちょっと経営が悪化してしまったということなんですが、そのときはもちろん総合的に判断して間違いないということで選ばれたと思うんですけども、今回そういう事業者の交代にならざるを得なかったという事態なんですが、何が計算違いだったのかということを……。","respondent":"中山地域活動課長","answer":"ＹＯＺＡＮの判断のところは区でちょっと答えるわけにはいきませんけれども、いわゆる事業の非常に厳しいとき、不採算の状況というふうな形で申し出がある中で、区としてはこれは子どものある意味で命にかかわる重要な事業だということで。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"ちょっと区民意識というのを啓発していく、啓蒙していくというのはなかなかご苦労があるんじゃないかなと思うんですけども、ちょっとやっぱりどうしても気になってしまうのは、今回のパブリックコメントで、区民の皆さんからの意見があまりにも少ないというか、意見件数が５件、区民からは３名で都民１名ということなんですが、やっぱり大事な点として、地域の防災計画ということなので。","respondent":"久保田防災課長","answer":"広報につきましては、全区民の７割以上の方が何らかの形でご覧になっているという世論調査の結果も出ておりますので、こうした周知の仕方が一番オーソドックスといえばオーソドックスですけど、確実な方法だというふうに考えております。","voiceIndex":17,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"先ほど広報に周知して７割が読んでいますということだったんですが、実態なんですけども、ちょっと私つかみきれていないところがあるんですが、確かにパブリックコメントをやっていますよというのは７割の方が知っていたかもしれないんですけども、じゃあ今どういう意見なのか、計画素案ができているのかということに関して、じゃあ本体はどこどこに置いていますから見てくださいというのは。","respondent":"久保田防災課長","answer":"わかりやすくどれだけ区民の方に説明するかということになると思うんですけども、私ども９月１日に広報を出しましたときに、非常にできるだけコンパクトに、焦点を今回の改訂のポイントを三つに絞ってご覧いただいたところです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"努力されているのはすごくよくわかるんですが、率直に言って少ない原因はどこにあるのかなということをお伺いしたいのと、あと話は別になるなんですけども、今回地域防災計画ということなので、ちょっと私も不勉強な点で申しわけないんですけども、地域で特性に応じてやっぱり自治体が決めるという意味でこの計画はすごく意味があると思うんですが、品川という地域特性の中で。","respondent":"久保田防災課長","answer":"当然今回の新しい被害想定に基づいた対策というのがこの地域防災計画の改訂ですので、避難者人口が非常に増えているということから、それの対応策として、従来の学校を中心とした避難所の充実、そのほかに私立学校とか、あるいは都立学校に広げて。","voiceIndex":21,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"住宅倒壊と火災ということでお話がありました。ほかにも都市型災害ということですけども、特に住宅倒壊と火災の問題では、今回改訂に新たに盛り込まれました耐震改修促進計画の大幅な前進というのが核になると思うんですけれども、これを計画の中でやはりいかに実効性のあるものにしていくかというのがすごく大事だと思うんですけども、そういう意味ではどういうような積極的なお考えをお持ちなんでしょうか。","respondent":"久保田防災課長","answer":"例えば今の火災の延焼対策としては、木造の住宅の建て替え支援事業を行っていく、これを新たな新規事業として盛り込んでいるというふうに聞いておりますので。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺のお答えを一ついただきたい。細かいことで何点か確認をさせてもらいたいんですけど、例えば、「素案の修正状況」の１ページ、前が間違ったのか、被害想定の中で、平成１７年国勢調査と平成１２年国勢調査、これは最初が平成１２年ということなのか、その辺が何なのというのが、まず読んでいると思います。この辺の考え方、これは個別のことで違うかもしれないけど、考え方を示してほしいなと思います。","respondent":"久保田防災課長","answer":"２点目の水の活用なんですが、基本的な考え方として、従来は学校避難所の場合の水の活用としては、まずプールの水を濾過して使うというのが一番に出ていたんですが、これもいろんなプールの水というのは活用の仕方はあるんですけども。","voiceIndex":25,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"多岐にわたり、ありがとうあります。最初に言った数字でちょっと気になったのは、平成１７年と１２年、国勢調査ね、わかったんだけど、同じ数字なの。平成１７年の数字は平成１２年のとは変わるんじゃないのということが１点疑問だった。だから、最初から平成１７年で平成１２年の数字を使っていたんだなというのが、人口のところです。ごめんなさい。その辺、これからお願いしたいんですが、どうでしょう。","respondent":"久保田防災課長","answer":"被害想定自体が、これは平成１２年の人口でもって東京都のほうがカウントしていますので、平成１２年が正しいと思います。それから、広域避難場所等の周知ですけれども、今回わが家の防災ハンドブックの中にも、地図表示の部分を相当織り込んで入れています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今回の計画の中で、帰宅困難者のことが新しくいろいろ盛り込まれていたと思うんですけども、この辺というのは、事業者との連携がとても大事であると思うんですけれども、その辺の意見とかはどこかで聞かれたのかどうかという点と、あと防災会議が明日２回目が開かれるということなんですけれども、１回目のときに、どのようなご意見が寄せられたのかわかったら教えていただきたいと思います。","respondent":"久保田防災課長","answer":"帰宅困難者対策なんですけれども、これも経緯がありまして、やはり帰宅困難者というのは、従来は１区だけではどうにも対応できないということで、東京都が中心になってこれはやっていくというような形で従来はずっと進めてきました。","voiceIndex":29,"id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ちょっと中身に触れてなんですが、住宅のところ、結構みんな家が住めなくなったりしたときにどうしたらいいのかという、応急住宅のところで実際に一時提供住宅とかいろいろ書いてありますけれども、この辺の住宅の確保、品川区の場合は都営なんかの空きなんかはほとんどないと思うんですが、この辺の住宅の確保というのはかなり関心が高いので、この点と、あと、広域の避難場所はとても遠くて行かれないので。","respondent":"久保田防災課長","answer":"あれはたしか４キロか５キロぐらいあるんじゃないかと思うんですけど。そういうものをできるだけ解消していこうという東京都の方針があって、内陸部に内陸部にというような形で考え方を進めてきている傾向があります。","voiceIndex":31,"id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この間、公園をもっとつくってほしいという話をしたら、やはり品川区は危険度の高い地域が多いので、まちづくりとともに公園も防災の要素にかなり重点を入れて取り組んでいますというような話をちょっと伺ったので、ぜひ力を入れてやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"しながわ環境大賞のほうで、大賞を受賞した清泉女子大学福祉環境委員会なんですけど、企業ということなんですけど、ちょっと何かそこら辺が、あれっ企業が何かしたのというのがちょっとわからないので、どういうふうな団体なのかなというのをもう少し聞きたいのと、あと、講演会のほうなんですが、中小企業のニーズの高い環境経営情報というふうに説明ありましたけども、そのかかわりというんですか。","respondent":"田村環境課長","answer":"似たような事業は、実は３月の頭にも予定しているのが、ＩＳＯ取得の事業者交流会というのを３月４日に予定しています。","voiceIndex":38,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"今回第２次の基本計画ということなんですけれども、今後どういうふうに改善していくかということも含めちょっとお伺いしたいんですけど、その考え方として大事だと思うのが、ごみの組成なんですけども、ちょっと書いていたら申しわけないんですけども、まず、区内、区によって全然ごみの出方というか、どういうものなのかという組成が全然違うと思うんですけど、その実態をつかむことから。","respondent":"秋山資源循環推進課長","answer":"１０月に向けての説明会の実施ですけれども、今のところ、まず廃棄物減量等推進員の方に説明を行って、減量等推進員の方に地域で広めていただきたいということと並行して、町会、自治会、管理組合、それぞれに対して説明会のご案内を差し上げて、町会、自治会。","voiceIndex":44,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"といいますのは、そういったことを目標に出すことで、困難かもしれないんですけども、その実現に向けて行動していくとか、その中で廃棄物をつくるなら製品もつくらないという入口の対策ですとか、ものづくりのあり方とか、商品のあり方そのものを大きく転換することにつながると思うので、国内では徳島の上勝町ですかね、宣言をされているようなゼロ・ウェイストというような考え方といいますか。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"この計画が出口の計画ではないかというご指摘ですけれども、２２ページ以降、今後の取り組みということの中で、ごみの発生抑制、家庭系の発生抑制ですとか、事業系の発生抑制等を図ってあります。とりわけ事業系につきましては、二つに流れが分かれるものですから、一つは区の収集のほうに出す有料シール券ルートと、もう一つは、自分で清掃工場に持ち込むルートと。","voiceIndex":46,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"最後に質問したゼロ・ウェイストの問題なんですけども、ちょっとこういう考え方を、高い目標ではあると思うんですけど、そこを打ち出すことで、別に私は出口対策だけやっているんじゃないかと言っているわけじゃなくて、入口の対策をどうするかということがやはりすごく決定的に大事だとこの問題で言われていますので、そういう目標をつくることが、入口のごみの問題。","respondent":"岩崎環境清掃事業部長","answer":"そういう意味で、当然目標を持つとかというのは一つの方法でありますから、その方法を必ずやらなきゃいかんとかというような議論にはならないわけで、ちょっと委員の言われることがどういうことをやるべきだというご提案なのか、その辺がよく把握できないわけですけども。","voiceIndex":49,"id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問","question":"ちょっと教えてほしいのは、３ページに、「いわゆるあわせ産廃」と、ちょっと事業系のところが知りたいんですが、一般廃棄物と、「区長が一般廃棄物とあわせて処理することが必要と認めた産業廃棄物」、「いわゆるあわせ産廃」という、ちょっとこれの考え方と、５ページのところに「管路」、表のところに「管路」とありますよね。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"事業系のごみ量ですけれども、５ページの表－３の持込ごみ量は事業系の、区収集の右側に持込ごみ量というのがありますけれども、それが先ほど部長が答弁した二つのルートのうちの一つの直接事業者が持ち込んだ量になりますので。これもプラスチックは埋め立てないで、既に臨海パワーとかという熱エネルギーを回収する施設ができていますので。","voiceIndex":51,"id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"政令市なんかはしているけど、２３区はどこもまだしていないという部分においては、一部事務組合のあたりでやはり追求する部分であるかなと思いますが、その点を１点と、あと、今回の計画のところ、３Ｒのところが大変大きいわけなんですけれども、３Ｒをやはり追求していくというところがここにも書かれてあります発生抑制と再使用と再生利用というところを国も都も区も追っかけているわけですけれども。","respondent":"秋山資源循環推進課長","answer":"発生抑制のところですけれども、発生抑制に関しましても、今後の取り組みというところで書かれておりますし、各リサイクル団体、それから区民の方々にも啓発を行っておりますし、リサイクル団体との例えば先ほどもお話ししましたけども、マイバックの調査。","voiceIndex":54,"id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"容器包装リサイクル法にのっとって新たにリサイクルのルートができたということは一歩前進であるので、ぜひそこを拡大していく必要があるかなと思っていますが、私一般質問でもさせていただいたんですけれども、温暖化防止の中で、石油製品を燃やすということは、ほんとうに温暖化防止に逆行するという立場で、私は環境問題の一つとしてしっかりとらえていってほしいし。","respondent":"秋山資源循環推進課長","answer":"説明会のご意見ですけれども、もちろん説明会というのは分別の変更、それから資源回収の拡大につきまして、区民の方にご理解をいただくというのが第一の目的ですし、そういうところに関して理解をいただくためには。","voiceIndex":58,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういった意味では、やはり理解をしてもらう意味でも十分中身を説明するというのが第一と思います。私、ちょっと最後の質問なんですが、サーマルリサイクルでどのくらい回収というか、何かサーマルリサイクルはとっても効率が悪いと聞いて、その辺はさらに技術的に進んでいるのか、どのくらい回収されているのか、ちょっとその点をお聞かせください。","respondent":"秋山資源循環推進課長","answer":"効率ですけれども、品川区のごみが品川清掃工場で今現在発電の効率が１８％というふうに一部事務組合のほうから聞いてあります。この１８％という数字は比較的工場の中では効率がいいほうだというふうに一部事務組合のほうから聞いております。","voiceIndex":60,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":38552,"voices":68}},{"id":"h20-20080226-7","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"厚生委員会","time":"午前１０時０２分～午後 ４時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オアシスルームが具体的にどういうふうになっているのかというのが、よくわからない部分があるので、お聞きしたいんですけど、このオアシスルームは、１日、８時半から１７時半まで、それから東五反田保育園は、今度９時から１８時までになりますけれども、１日６名程度で、月曜日から金曜日までやっているということでいいんでしょうか。","respondent":"小林保育課長","answer":"１点目の利用率ですが、手元の資料は、この２月までの１０カ月の集計です。８園で実施しておりますが、平均で、１園当たり９６９人、時間数で４,５２７時間というのが実績です。これは、稼働率に直しますと５６.５％ほどになります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東五反田は、児童センターの１室をオアシスルームという形で使って、保育課がそれをオアシスルームとして管理するということでいいんでしょうか。それから、体制なんですけれども、６名程度に対して、保育士は、どういう方がどれぐらいの人数で保育される体制になっているのか、人的な体制についても教えていただきたいと思います。","respondent":"小林保育課長","answer":"東五反田の一体的な管理につきましては、委員から、今、お話しいただいたとおり、児童センターの一部をオアシスルームとして活用させていただきながら、全体の施設管理、そして運営等を一体的に行い、事業の充実、効率的な施設運営に努めていく予定です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オアシスルームというのは月曜日から金曜日まで５日で、そういうところで、６名程度受け入れるということで、平均で５６.５％ということですけれども、６名来るときもあるわけですよね。そういうところで言えば、６名に対しての保育士の配置というのは、どういう人をどう配置しているのかというのを教えていただきたいと思います。","respondent":"小林保育課長","answer":"時間によっては、例えば、乳児で一遍に６名ですと、めったにそういうことはございませんが、２名では足りませんので、それについては、園の中で、人数が確定した中での職員の配置フォーメーションで対応しているという状況です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最低でも２名で、その職員は正規職員、派遣職員、非常勤職員ということですけれども、今度は区立保育園は７園になるということだと思うんですけれども、区立保育園７園だけとっても、７園のオアシスルームを運営するに当たっての正規職員の数と、派遣職員、非常勤職員、これがどのぐらいオアシスルームで配置ということになっているのかを教えていただきたい。","respondent":"小林保育課長","answer":"各園によって大分状況が違いますので、幾つかご紹介をしてまいりたいと思います。平成２０年度の実施予定でご紹介をさせていただきたいと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"荏原保育園と東五反田保育園は業者への委託ということで、東五反田保育園は平成２０年度で言われたときは、児童センター業務と一体ということでしたけれども、東五反田保育園のオアシスルームの児童センター活用というのは平成２０年度からであって、平成１９年度は違うということなんですか。そういうのは、いろいろ形態がそれぞれ違うというのは、何か理由があるんでしょうか。","respondent":"小林保育課長","answer":"人的配置は、それに十分に対応しうる職員を配置していく、運営の仕方に対応したマンパワーを配置していくという考え方の中で、職員を軸にしながらも、非常勤、人材派遣、多様な雇用形態を活用して合理的に仕事に対応していくという関係で、必ずしも派遣なら派遣。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかるところでは正規プラス派遣、それから水神でも正規プラス非常勤ということですが、この正規職員というのは、それぞれ１名ずつなんでしょうか。オアシスルームをやることによって、正規職員を増やしているという考え方でいいんでしょうか。今後の方向もあわせて、お聞きしたい。それからもう一つお聞きしたいのは、実施保育園が何年かごとで変わっていますよね。","respondent":"小林保育課長","answer":"そういった微妙な需要の変化、それから、どこから来ているかというような地域的な偏在に対応して、あくまでも需要対応、より便利な配置ということで、今後も適宜、私ども保育園はおかげさまでいっぱい拠点を持っておりますので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オアシスルームは、最大のときは１０園あったわけですけれども、今は８園ということで、１０園では多すぎるということで８園になったんでしょうか。そこをあえて、請け負った業者は保育に入らないで、子どもだけを各クラスに入れるというのは、じゃあ、何のための委託なのかという感じがするんですけど、委託そのものもどうなのかという思いがするんですけれども、そこら辺のところは、いかがでしょうか。","respondent":"古川児童保健事業部長","answer":"したがいまして、今日のお答えが明日も同じとは限りませんので、あまり小さなところばかりを見ていただくのも、非常にお答えするほうも動いていますから、流動的な中で事業を実施していきたいと考えております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も、そういう点では、在宅子育て支援をどう充実させていくかというところで、区としてもほんとうに努力をされて、オアシスルームでも、地域の方々にほんとうに喜ばれていると思います。そういうところで努力されていることはわかりますけれども、その上でちょっと質問をさせていただきました。今、派遣職員が何人いらっしゃるのか。とりあえずそこだけ教えていただきたいと思います。","respondent":"小林保育課長","answer":"請負云々等のお話もございましたけれども、あくまでも働く側だとか、施設の管理、運営だとかいった売り手の立場ではなくて、ご利用いただく子どもの発育を確保するということを唯一絶対の目的として考えたときに。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、雇用の問題が大きな問題になっていますので、そういう点では、子どもにとってどうなのかということにも、職員の体制というのはかかわってくることでもありますので、そういう点では、ぜひ、職員体制のところでも、今の雇用のところできちんとした形での雇用の体制をとっていただきたいということを要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"そういう中で、やっぱりこれから求められていくのは、よくいろいろなところで言われる地域力というんでしょうか、その地域の中にある潜在的な能力、例えば、それが子育てに向かう地域力と言いましょうか、あるいは、学校周辺を中心とした地域の教育力とでも言いましょうか、そういう形の中で、特に最近、団塊の世代の人たちの有効活用とでも言いましょうか、長々とくどい話で恐縮ですが、場合によっては。","respondent":"古川児童保健事業部長","answer":"それはやっぱり、マンパワーを継続して活用していく事業では、なおさら一定のシステムが必要だろうと思います。そこでお支払いした報酬は、当然、地域の方々であれば、地域でまた何がしかに利用なさって、買い物に使うだとか、いろいろな還元ができると思っています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今後の対応というところでは、ジェイティフーズに「回収品の数量等を報告させ、回収が適正に行われるよう指導する」と書かれていますけれども、今まで、品川区の保健所が行ってきたことの報告ですけれども、こういうことがあった場合に、品川区の保健所の役割はどういうことになるのかということを、改めてちょっと教えていただきたいんです。","respondent":"平澤品川区保健センター衛生課長","answer":"したがいまして、処分については、厚生労働省のほうで、今後検討されると思います。","voiceIndex":29,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「回収品の数量等を報告させ、回収が適正に行われるように指導する」というところでは、これからも品川区の保健所がかかわっていくということになると思うんですけれども、もう随分時間が経って、回収された部分もかなりあると思うんですけれども、いつごろ、どういう形でまとめられるのかということを、ちょっと教えてください。","respondent":"平澤品川区保健センター衛生課長","answer":"いつごろですが、まず初めに、ジェイティフーズから、毎日速報値ということで、回収状況がＥメールで報告されております。は国のほうの報告事項となりますが、今のところ、４０万ケースほど回収されていると聞いております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"品川区民から１１件の相談があったということで、その内容といいますか、具体的にどういうご相談があったのか教えていただければと思います。","respondent":"平澤品川区保健センター衛生課長","answer":"医療機関に受診していない場合は、必ず受診してくださいというお願いをいたしました。次に、ご希望の方につきましては、検便を行いました。私どもの職員を派遣しまして、採便管を持ってお願いしたところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、入院なさったとかではなく、具体的に検便等で、とりあえずは収まったということなんでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"私どもの受け付けた相談で、入院等、重篤な事例はございませんでした。","voiceIndex":35,"id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"そういった仕組みがあるんだけれども、そのあたりで、今、幾つか問題点があると、国のほうで考えているんですけれども、実際に担当されて、そのあたり、こういうところがこういうふうになるといいんだというようなことがあれば、教えていただければ、我々としても、そういうものをやはり都や国へしっかり伝えていきたいと思っているんですけれども、そのあたり、いかがでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"再発防止策としまして、情報の一元化、緊急時の速報体制および輸入食品の検査ということが挙げられております。したがいまして、こちらの動向を見ながら、具体的な中身はまだ不明ですので、それを拝見いたしまして、私どもでできることから取り組んでいきたいと考えています。","voiceIndex":37,"id":"exchange-015"},{"speaker":"須藤委員","kind":"意見","question":"これは品川区じゃないんだけれども、千葉のほうでこういう事例があって、保健所へ市民の方が報告したけれども、それがなかなかしっかり伝わっていかないというようなことが、また問題を大きくしたという話もあるんで、例えば品川区で、特にありませんでしたというご報告なんだけれども、区として何かこういったことがあったときに、きちんとそういう仕組みがとれているのか。","respondent":"平澤品川区保健センター衛生課長","answer":"窓口等に苦情品をお持ちになった場合は、これは千葉のほうでどのような対応をされたのか、恐縮ですが具体的な中身がよくわかっておりませんので、コメントは控えしますが、ただ、私どもに寄せられた場合は、必ずそういったものについてお預かりをいたしまして。","voiceIndex":39,"id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"新聞、テレビで、品川区は、東京都から、２９日の夜ということで、ご報告では、７時半という時間外の時間に連絡をいただいて、しっかりすぐにジェイティフーズと連絡をとる、また東京都と連絡をとるという、対応がスムーズにいったので、区民の方々は、頑張っていただいているなという思いを強くしていますので、今後とも、何かあったときに、体制がとれるようにご努力をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先日の一般質問の中でもされて、冷凍食品は品川区では使っていないということだったんですけれども、ここは文教委員会ではないので、学校給食には触れないんですけれども、保育園の給食では、国産品を中心にというところが、ちょっと気になったんですけど、そういうところでは、給食の場合、食材とかも含めて、輸入品はどういう状況になっているのかということを、ちょっと教えていただきたい。","respondent":"小林保育課長","answer":"ただ、１００％ないのかと言われると、言い切れないのは、生産国を含めました表示をすべてされているわけではありませんので、確認できないものも中にはありますから、一切使っていないという言い方は、若干危険なところはあります。","voiceIndex":42,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"加工食品も使っていないということですので、もちろん冷凍食品も使っていないというのはわかりますし、これからも、ぜひ、それは貫いていただきたいと思うんです。材料とか何かで、輸入品で考えられるというのはどんなものがあるかというところあたりで、ちょっとわかる部分で、表示されていないというもの以外は使われていないということなのか、そこら辺のところを、わかる範囲で教えていただきたい。","respondent":"小林保育課長","answer":"わかる範囲で使っているものはないと考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"高橋委員","kind":"質問","question":"今回のこの事例については、区のほうで対応をきちんとされたと思うんですが、こういったことが起きて、こういうふうなことになった顛末というんでしょうか、そちらをここで報告されているんですけれども、区民はよくわからないと思うんです。結局、大きな問題もなかった、保健所のほうもきちんとされたということ。広報の仕方というんでしょうか、何というんでしょうか、それは。","respondent":"平澤品川区保健センター衛生課長","answer":"先ほど、ご説明した中に一部含まれてありますが、自主回収が終わった段階で、区のホームページ等を通じまして、できる限りの情報提供をしていきたいと考えています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"高橋委員","kind":"質問","question":"ホームページもいいですけれども、見ない方もいらっしゃるので、何かほかにプラスアルファしていただけるとありがたいと思うんです。広報「しながわ」とかに出すんでしょうか、ちょっとその辺わからないのですけれども、もし何か方法がありましたら、お考えいただけたらありがたいと思います。","respondent":"平澤品川区保健センター衛生課長","answer":"本件につきまして、事件性、また原因の究明という部分が、このまま私どもの自主回収の予定期間である平成２０年３月３１日をもってはっきりするのかどうか、非常に難しいと考えています。","voiceIndex":48,"id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問","question":"今回は農薬となっているんですけれども、検便というと、大体いわゆる食中毒のところでいろいろあるんですけれども、大体こういう対応なのか、あるいは、場合によったらもっと突っ込んだ検査をやるとか、そういうことがあるのか、大体このぐらいで終わっちゃうのか、そこら辺のところはどうなんでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"お尋ねの中身が、一般的な食中毒に関するものと若干違うということを、まずご承知おきいただきたいんですが、まず初めに、１月３０日で、私どもが東京都と一緒にジェイティフーズに立ち入り検査をしたときに、たまたま渋谷区のほうに、このサンプル品が残っておりましたので。","voiceIndex":50,"id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"例えば、区民との関係では、体調を崩したとなると、もうちょっと何か、保健所として検査をする内容がそろっているのか。あるいは、今回の場合は検便ぐらいでいいと判断したのか、そういうところはどうなんでしょうか。","respondent":"平澤品川区保健センター衛生課長","answer":"この中で、そういったような有機リン系を疑われるような事例はないという厚生労働省の発表もありますので、現在のところ、私どもで対応している中身で、まずは医療機関の受診、それとあわせて、私どもでできる検便、または食材があるような場合は、一度。","voiceIndex":52,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":21873,"voices":66}},{"id":"h20-20080226-8","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"建設委員会","time":"午前１０時０３分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東急大井町線の急行運転の開始","agenda":"東急大井町線の急行運転の開始","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"急行が通過する駅というのは、時速何kmぐらいなのか。周りの声がすごいだけに教えていただきたい。それから、監視員をしばらくの間配置するというお話ですけれども、時間帯というんですか、どの時間帯に置くのか。それから、しばらくの間というのは、東急がどういう間を指しているのか、教えていただけますか。そもそも東急がなぜ急行運転を始めたいのか、その説明も一緒にお願いします。","respondent":"阿部都市計画課長","answer":"スピードにつきましては、何kmかというのは把握してございませんけれども、ＡＴＣにつきましては、６０km速度でやるようにと聞いております。その制限を超えないような装置をつけると聞いております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、戸越公園駅の踏切で事故が起きてはならないと、安全対策に対する地域の声も強いもので、こういう質問をさせていただいているんです。一つは、急行が通ろうが、通るまいが、ホームドアの話はぜひ進めるべきだと思うので、東急のほうに伝えていただきたいと思うんですけれども、その点が１点。この間の経過も含めて、ちょっと教えていただけますか。","respondent":"阿部都市計画課長","answer":"３月に開かれる校長連絡会で、今、通学路が限定されておりませんので、全校長に対して、東急のほうから、急行が２８日から運行するという旨を周知いたしまして、もし沿線の学校以外で説明会をやってくれという要望があれば、東急が対処するということになります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"戸越公園駅の急行、地域の方と東急との話の中でも、そういう説明はあるけれども、やっぱり朝のラッシュ時ですと、電車が６０kmぐらいで通過するというので、もしものことがあってはいけないという不安が非常に強いんですよね。ぜひ、戸越公園駅にも急行をとめていただきたい。警備員は３カ月という話ですけれども、もっと時期を検討すべきだと思うんですけれども、いかがでしょうか。","respondent":"阿部都市計画課長","answer":"ホームドアの件ですけれども、これは東急のほうに確認しておりまして、東急のほうは、今のところつける考えはないです。安全対策につきましては、今申し上げたとおり、当面ですけれども、警備員もつく、あるいは通過する駅にも警備員をつけるです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状の安全対策ではまだまだ不安だという声があるのは、ぜひ、受けとめていただきたい。今の都市計画課長のお話ですと、これで十分だというお話ですけれども、戸越公園駅の問題については、地域の声によく耳を傾けていただいて、さらなる安全対策をとっていただきたいし、警備員の配置についても、３カ月でおしまいではなくて、状況を見ていただいて充実すべきだなと思いますので、最後に意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"警備員なんですけれども、配置が３カ月程度ということですが、自動放送装置というのもしばらくの間ということですが、これも同等の期間と考えてよいのでしょうか。それが１点です。それから、小学校に対する説明会のやり方なんですけれども、子どもたちに座学でやるのか、それとも現地でやるのかというのは、おわかりでしょうか。その２点をお願いします。","respondent":"阿部都市計画課長","answer":"例えば、保護者にビラを配ってくれとかいう要望があれば、それは個別に対応するという東急の話ですので、まずは学校に行って話をして、その後の周知の方法は学校によって異なるのかなと思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問・要望","question":"警備員の配置と違って、自動放送装置のほうは機械ですので、住民の方々の要望等、それから運用のされ方などを見ながら対応していただければと思います。どちらも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"駅と駅の間の１区間が短いだけに、そこに急行なりが走っていけば、普通列車も入りますので、あるところによっては、時間帯で相当長く踏切があかないというところも発生するような気もするんですが、その辺、もし東急のご見解なりがありましたら、教えてください。","respondent":"阿部都市計画課長","answer":"確かに、委員ご指摘のとおり、全体の本数も増えますし、急行と各駅停車ということになりますので、踏切の遮断時間が若干長くなろうかと考えています。ただ、現在もそうですけれども、常時閉まったような状態の踏切は出てこないかなと思います。","voiceIndex":15,"id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、それは東急のほうに、そういうふうに感じた部分もありますよということは言っていただきたいなと思います。もうひと工夫してほしいのは、踏切の線路の中に、段差が生じないように間に入れてある、枕木の上に乗せてあるもの、それが短過ぎるがゆえに、自転車なんか、そこから落ちないように通過するわけですよ。そういうことについての検討というのは、どうなんでしょうか。","respondent":"松代管理工事課長","answer":"何とか来年度、拡幅に向けて実施できるような計画を、今やっと進められるかなと思っています。しかしながら、ちょうどあそこはボトルネックになっていますので、そういった意味では、大崎高校側の歩道からスムーズに歩行者が歩けるようなものをまず基本に考えています。","voiceIndex":17,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"今、大崎高校のほうで、歩道側のほうに、お互い歩行者が通るというケースが多いわけですよ、自転車も。それだけに、お互いに踏切の中でぶつかり合っているわけですから、むしろ、このことのほうが事故が起きる可能性は高いと考えたほうがいいんじゃないか。","respondent":"松代管理工事課長","answer":"今、おっしゃることは、今後、もっときちんとやりますけれども、基本的には、全幅員が大体６ｍぐらいと考えています。中を通る車、それから歩行者を通すところを両側に設けたい。","voiceIndex":19,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"ここは、急行が走るということが定着するまで大分危険なエリアなんだろうなと思うんです。そこがつながっているだけで随分自転車なんかは通れるのにと。今のお話で、先々に計画されているということでしたけれども、そういう踏切については、早急に検討をしていただきたいということを要望します。それから最後に、警備員の配置ですが、荏原町駅なんかは、上り下り両方に配置されるということでしょうか。","respondent":"阿部都市計画課長","answer":"たしか、両方側につくということではなかったと思うんです。踏切の片方に警備員がつくような形だったと思います。１人ということです。","voiceIndex":21,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"踏切の両側に上下線が走りますよね。ということは、立っている方というのは、どういう任務を持って立っているんですか。","respondent":"阿部都市計画課長","answer":"要するに、くぐったりそういうことをしないように、当然通るわけですから、来ますよということです。あっちゃいけないことですけれども、そういうことがないように警備をするということです。","voiceIndex":23,"id":"exchange-011"}]},{"id":"topic-02","title":"小関橋架替整備工事委託契約の変更","agenda":"小関橋架替整備工事委託契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今の説明で、地中障害物と言ったらいいんですか、下水道管の外側にコンクリートの固まりみたいなものがあったという話だと思うんですけれども、専門知識がないのであれですけれども、コンクリートの固まりというのは人工物になるんですか。何でそんなものが地中から出てくるのか、産業廃棄物とは言えないのか、その辺、どういうことなのか、ちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"昨日のご質問でもいただいたんですけれども、事前に確認ができなかったのかということなんですが、図面に記載がなかったということと、高圧電線管であるとか、ガス管というのは、施工上傷つけやすいものですし、傷つけた後の事故が非常に恐ろしいものですから。","voiceIndex":29,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"今回、４億円の増額ということで、金額も大きいのでもう少し伺いたいんですけれども、図面に記載がなかったということですけれども、要は、下水道管をつくったときに保護するために工事が行われたわけですよね。下水道をつくったのは、東京都の下水道局になるのかな。要は、わからなかったのかなというのが率直な疑問なんですよね。その辺は、なぜなんでしょうか。","respondent":"青木都市開発課長","answer":"今回の金額増加につきましては、予定しなかったものを撤去するために時間を要した結果として、出水期の安全対策が必要になったことに伴うものですので、もし仮に、委員ご指摘のとおり、精密な事前調査を行った上で、障害物があることを明らかにしたとしましても、その場合には。","voiceIndex":31,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"改めて、調査をしてあるかどうかわからなかったというのではなくて、初めからあったものを、いわば東京都との連携の中で出てこなかったのかなと。そういう図面で、どこに何があるかというものはわからないんですか。","respondent":"岩田まちづくり事業部長","answer":"もう一つは、国土交通省、旧建設省の積算の考え方で、設計段階で膨大な労力と費用をかけて事前調査をした場合と、あらあらの調査で工事を発注し、現場段階で何か出た場合には詳細な設計をやり直して工事を進めていくというのとシミュレーションをかけまして。","voiceIndex":33,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"工事途中の、要は護岸をつくっている間にとめて、出水期をやり過ごさなければいけないようになってしまっているわけで、ざっくりした質問なんですけれども、この安全性というのはどのようなものなんでしょうか。この場所から大変近いところに住んでいるものですから、護岸がない状態で出水期をやり過ごさなければいけないというか、この辺、非常に矛盾であると思うし、どうなのかなというのが１点です。","respondent":"青木都市開発課長","answer":"工期ですけれども、右側のほうで、平成２１年の上部工での工期が長くなっている部分の説明ですけれども、当初、青い工程で組んだところは平成２１年３月までに、会計年度も閉じて、そのぐらいで終わられるだろうという計画を組んだ中で。","voiceIndex":35,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問・要望","question":"詳しい説明を、ありがとうございました。大体わかりましたが、最後の工期の周知のところなんですけれども、住民だけではなくて、あの辺はオフィスなので、昼間使っている人もありますので、チラシの配布体制ですとか、あるいは、その現地に看板でちょっと説明をつけるとか、住んでいる人だけではなくて、使っている皆さんにわかるような仕組みを考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、変なことを言います。平成１７年９月に起きた都内の集中豪雨を踏まえて、こういうことになったと。ただ、こういう渇水期とかにしか仕事ができない、あるいは集中豪雨は年に１回あるかないか、それでこの期間工事をやめる。水はとりあえず全部入ってこないわけですから、工事はやれる。それだったら、１回ぐらいあふれたって、その影響がどれだけあるんだと。それに対する対策をどうとるんだと。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"今後、そういう判断をすべきかどうかというのも、変なご質問をいただいただけに変な答えになっちゃいますけれども、実際にはちょっと答えは非常に難しいかなと考えています。ところが、平成１８年の都内での水害で、河川部が、そういうやり方はもうだめだと、この写真の左のように、完全に全部開放しない限りは河川部内の工事はさせないという方針が打ち出されてしまいましたので、今後は。","voiceIndex":38,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"提案","question":"まさにそのお話で、やっぱり日本的な発想をするというか、２年に１回あるか、３年に１回あるかもわからない形の中で、先ほど、昭和６０年ぐらいにそういうことがあったと。そういう前例を踏まえると、日本はこういう方法をとりたがる、とったほうがいいんだろうということで、こういう提案をされた。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-018"},{"speaker":"阿部委員","kind":"確認","question":"今の東京都がかなり強行だったというお話を伺っていまして、そうせざるを得ないんだろうと思いますが、ちょっと１点だけ確認させてください。この１３億円から１４億円というこの金額のうち、区の負担はどのぐらいなんでしょうか。","respondent":"青木都市開発課長","answer":"残り２分の１が、名目上、一たん区の負担金になりますけれども、都市再生総合整備事業という制度要綱に基づいて整備している公共施設につきましては、東京都からの都市計画交付金というものが補てんされておりますし、さらに、都区財政調整での交付金等が目的別に充てられまして。","voiceIndex":42,"id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"増額分も含めて、ほぼゼロということでよろしいですか。","respondent":"青木都市開発課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"}]},{"id":"topic-03","title":"東急目黒線連続立体化事業および武蔵小山・西小山駅前広場整備事業","agenda":"東急目黒線連続立体化事業および武蔵小山・西小山駅前広場整備事業","exchanges":[{"speaker":"井上委員","kind":"質問","question":"新しく植える１２本について、倒木の可能性もあるということだったので、１２本のうちの倒木の可能性のある本数は何本なのかということを、まず教えてください。","respondent":"浜脇街路事業担当課長","answer":"すみません、ちょっと説明の仕方が悪くて、図面にありますとおり３１本ございまして、変更後を見ていただきたいんですけれども、保存できるのは１５本です。ですから、１６本の移植の必要が出てきたということです。","voiceIndex":50,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"質問のほうが、ちょっとおかしかったのかなと思いますので、もう一度。１６本が今の現状から失われるということについて、そのうち歩道を持ち上げている木と、樹木医の判断によって、老木であるということで切らずにはおけない木と判断するので、その本数の内訳を教えてくださいという質問です。","respondent":"浜脇街路事業担当課長、松代管理工事課長","answer":"その移植したものを、改めてこっちには持って来ません。それは、先ほど言いましたように、古いので、２回も移動はできないという判断によるものです。そのために、今回、新しく１２本を入れますと。そういった作業をしながら、なるべく既存の桜を残しながら、どうしても残せないものについては、先ほど言いましたように、区内の公園といったところに移植をするといったことで工事を進めているものです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"本来、こういう計画というのは、こういうふうに計画変更を行おうとしているんですが、どうでしょうかと住民の方に説明をして、そのことによって、私たちがその意見を集約して、こういったところで判断ができるという仕組みのほうが正当だと思うんです。この報告について直接は関係ないですけれども、その辺について、そうであるのが議会だと思うんですけれども、ご意見をお聞かせいただければと思います。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"説明等につきましては、基本的には極力桜を残した状態で工事を進めるということで説明をしていきますし、設計変更に当たっては、こういった事情でやむを得ず変更せざるを得ないという説明をしていくという立場で進めているところです。一般の道路工事の場合、いわゆる道路工事による影響というのは、ほんとうにごく近隣の方だけにとどまるわけですけれども、今回の補助３０号線につきましては、一方通行のところを相互通行にするとか。","voiceIndex":55,"id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"こういうまちづくりについては、どこでどういうふうに変更ができるものかというのが、なかなか私はわからないので、今、悩みながらお伝えはしているんですけれども、ぜひ、ここのところでは、車で相互通行というよりも、桜並木を残したいということを大切に思われている方たちがいるので、ぜひ、そこのところは説明を聞いて、きちんと声を生かしていただければと思います。","respondent":"岩田まちづくり事業部長","answer":"ただ、次回、３月になりますと住民説明会をやりまして、住民の方から、もっといいプランのご提案があって、変更があれば、本委員会にもきちっとそれを説明した上で進めていくことは、当然のことだろうと考えています。","voiceIndex":58,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"桜は愛着があるだけに、できるだけ保存をするという方向の話は理解できるんですけれども、今、最後に話されましたけれども、一方で、ソメイヨシノは寿命が短いというところも事実で、欅とか、杉と違って、そういう意味では、極端に短いですからね。やっかい者扱いだと、どんどんなくなってしまうのは寂しいだけに、ちょっとその辺、もし検討をされているのであれは、教えていただけますか。","respondent":"藤田道路公園課長","answer":"ただ、街路樹として植えるときに、接ぎ木をした木をそのまま置けるかどうかというと、小さな木がその街路樹としてあるわけですから、枝は下からどんどん出てくる、そんなような状態で街路樹にはなかなかできませんので、今回みたいなケースは、やはり別な場所に植えて。","voiceIndex":60,"id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"今回の件は、もちろんここで苗木が育つとは、到底思えないんですよ。ただ、ソメイヨシノというのは時間とともに淡く薄いピンクになってくるよさがあるだけに、接ぎ木をすると、その色が残るものなんですよね。ぜひ、そういうことをご検討くださいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-026"},{"speaker":"須貝委員","kind":"意見","question":"この地域は、私も育ったところですが、地元、また近隣町会が３０年にわたって桜祭り、桜並木に愛着を持って地元が一緒に育ってきたと思いますので、ぜひ、地元の方に十分に配慮して、ここの歩道工事、道路工事等々をやっていただければありがたいなと思います。新しく持ってきたときに、バランス的にどうなのかなと。","respondent":"浜脇街路事業担当課長","answer":"そういうふうに、地元の方々から愛着とお祭りというものがございまして、先ほど言ったように、３１本中１５本が何らかの形でしか残らないと、１６本がなくなっちゃうということで、植えるものにつきましては、なるべく見劣りしないといいますか。","voiceIndex":63,"id":"exchange-027"},{"speaker":"三上委員","kind":"意見","question":"それこそまたおかしなことを聞いていいかなと思いますが、実は、２枚目のグリーンの矢印なんだけれども、対面通行の矢印の右、左は逆にすべきじゃないのかと。どうも運転する立場というか、どう判断したらいいのかと、さっきからちょっと悩んでいたんです。ちょっと修正していただいたほうがいいんじゃないか。","respondent":"浜脇街路事業担当課長","answer":"その辺で、このやり方からいきなりこうしちゃったものですから、こういうふうなミスになっています。この辺につきましては、説明会には、ご指摘がありましたように直して出します。ありがとうございました。","voiceIndex":65,"id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"すみません、説明のときに聞き漏らしたのかもしれませんけれども、一方通行の逆転化、これは何月何日から行われるのか、周知方法と、周知期間を教えていただければと思います。","respondent":"浜脇街路事業担当課長","answer":"３月末を工事の期間としますので、４月頭と考えております。その予定ですけれども、工期につきましては、ビラとか看板で、工法が変わりましたということを、当日前後にお知らせしたいと考えています。説明会の中では、４月１日を目途にということで、ご説明をします。","voiceIndex":67,"id":"exchange-029"},{"speaker":"阿部委員","kind":"質問・要望","question":"一方通行が逆転化するというのは、その道に慣れ親しんだ人にとっては結構危険なことだと思うんです。何となく、あっち側から車が来なければ安全と思っていたのが、後から来ちゃうわけですし、特にお年寄りとか子どもたちとか、感覚的に、車がどっちから来るというのが逆転するわけですから、慣れるまでは非常に危険だと思います。その辺は、強く周知方を図っていただくよう要望します。よろしくお願いします。","respondent":"浜脇街路事業担当課長","answer":"当面につきましては、看板もやりますし、当然、ガードマン等もつけます。今、お話があったように、ちょうど学校の入れ替えのこともありますので、近隣の学校について、こういう交通規制になりますということについては、周知を図りたいと考えていますので、やってまいります。","voiceIndex":69,"id":"exchange-030"},{"speaker":"阿部委員","kind":"意見","question":"さらになんですけれども、その中で、例えば、古い標識がちょっと残ってしまったりとか、あるいは、反対に向いた道路の表示ですとか、そういったものが残ってしまうととても混乱のもとになりますので、そういうこともあわせて、気をつけて、ぜひ混乱、事故のないようにお願いいたします。","respondent":"本多委員長","answer":"本件を終了いたします。","voiceIndex":71,"id":"exchange-031"}]},{"id":"topic-04","title":"分譲マンション維持管理相談事業の実施","agenda":"分譲マンション維持管理相談事業の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"相談実績はまだ寂しいばかりなのかなとは思うんですけれども、分譲マンションの管理組合の悩みや、そういうのはすごく広がっているなというのが実感なんですよね。ぜひ、何とか区民の間に進めていただきたいなと思うんです。相談業務の中で、どういうふうに相談員がアドバイスというか、力を貸してくれるのか、その辺、ちょっと教えていただけますか。","respondent":"齋藤住宅課長","answer":"マンション管理士で食べていける人はそれほどいません。一級建築士や行政書士やさまざまな資格とあわせてお持ちで、得意分野はいろいろあります。特に修繕計画につきましては、マンション３分の２以上の議決がないとまとまらないんです。","voiceIndex":80,"id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"総会を開いても、古いマンションになってくると、なかなか集まること自体も難しいし、高齢化の問題、持っている人と住んでいる人が違う問題、いろいろ背景にあるんでしょうけれども、管理組合の方の話を聞くと、３０年を超えたマンションだけれども、５０年、１００年使えるマンションにするには、どういう管理、修繕の計画を持てばいいのか、そこを悩んでいるそうなんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問","question":"初回のみ無料とするということですけれども、２回目以降そのまま継続して契約がされるかどうかというのはなかなか難しいものがあると思うんです。そうすると、毎回、ボランティアでいろいろなところに行かなければならなくなる可能性もあると思うんですけれども、そこのところは、どういう検討の結果、このようになったのか。２点、教えてください。","respondent":"齋藤住宅課長","answer":"そういったところまでいかなくて、例えば、犬の問題、駐車場の問題、そういった法的な対応をどうすればいいですかというのは、月２回のマンション相談会を使えます。","voiceIndex":83,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"私が勘違いしていたのかもしれないんですけれども、もともとの第２、第４の相談というのは、品川区として７,０００円の費用弁償をお支払いして相談をしているということだと思うので、初回のみ無料というところで、代表の方がみんなを集めて、どういうふうに相談をしようかというような話だったら、組み立てを考えるというのであれば、ボランティアで協力をしていただくというのはありなのかなと。","respondent":"齋藤住宅課長","answer":"ただ実際に、業務が、耐震補強だとかに移るようになったら、マンション管理士１人ではできませんし、専門の工務店、建設会社に相談しなきゃいけない。これのコーディネーターになれば、当然、契約の対価としてもらえる、こういうふうに考えております。","voiceIndex":85,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"整理すると、仕事あっ旋的な発想が、マンション管理士たちの出会いの部分については、そういうことでボランティアの考え方ということでよろしいんでしょうか。","respondent":"齋藤住宅課長","answer":"そうとられるといけないので、仕事の紹介はするなと言っております。犬、猫の問題、駐車場に勝手に使用しているという違法駐車の問題は、普通の第２、第４の水曜日にやると、こういうふうにお願いしています。","voiceIndex":87,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"申込み方法は、電話で随時受け付けているのは区の住宅課で、その６名のマンション管理士会に、どなたか行ってくださいというつなぎをするということでいいですか。","respondent":"齋藤住宅課長","answer":"そのとおりです。","voiceIndex":89,"id":"exchange-037"}]},{"id":"topic-05","title":"の所管質問","agenda":"の所管質問","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"本会議の答弁で、東京都のほうが検討する動きもあると聞こえたんですけれども、そういう答弁があったので、東京都の検討の動きというのはどういうものなのか、経過も含めて、そこをもう少し詳しく教えていただきたいということです。よろしくお願いします。","respondent":"齋藤住宅課長","answer":"都営大井林町住宅跡地の活用スケジュールについてという、Ａ４版横の資料に基づいて説明します。現場です。平成１９年１２月までには、入居者は退去されました。昨日、見て来ましたら、躯体は全部ありませんでした。ガラの搬出と基礎工をちょっとやっておしまい。","voiceIndex":93,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"この資料で見ると、東京都での、住宅施策等での利用の有無、ここはもう決まったのかどうか、今、どの時点なのか。そこを教えていただけますか。","respondent":"齋藤住宅課長","answer":"これは平成２０年度当初で、この４月から実際のＰＴが始まる。今、ちょっと言いましたが、ＰＴの窓口のところに、もう幾つか活用策を提案したいという声が、都市整備局の中で来ているという話を聞いております。","voiceIndex":95,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、私としては、ぜひ区移管で区営住宅をつくってほしいということは変わらないんですけれども、どちらにしろ、経過の中で地元区の意向確認というのが来るわけですよね。そもそも区移管で区営住宅をつくってほしいと思いますけれども、この流れで、さらに地元区の意向の確認が来たら、ぜひそこで手を挙げていただいて、区営住宅の増設を進めていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":32321,"voices":105}}]);
